#[test]
fn hob_batch9_bound_damage_recipient_is_filtered_before_destruction() {
    let mut engine = test_engine(2);
    let source = test_instance(
        "damage-source",
        test_definition("damage-source", "Artifact - Equipment"),
        "player-0",
    );
    let dragon = test_instance(
        "dragon-recipient",
        test_definition("dragon-recipient", "Creature - Dragon"),
        "player-1",
    );
    engine.state.players[1].battlefield.push(dragon);
    let stack_object = StackObject {
        id: "stack:damage-source".to_string(),
        controller: "player-0".to_string(),
        card: source,
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: Some("triggeredAbility".to_string()),
        ability_rule: None,
        decisions: BTreeMap::new(),
        targets: BTreeMap::from([(
            "damageTarget".to_string(),
            TargetRef::Permanent {
                instance_id: "dragon-recipient".to_string(),
            },
        )]),
    };
    let effects = json!([
        {
            "kind": "dealDamage",
            "source": { "kind": "self" },
            "amount": { "kind": "integer", "value": 1 },
            "recipient": { "kind": "chosenTarget", "id": "damageTarget" },
            "bindRecipientAs": "damagedObjects",
        },
        {
            "kind": "destroyPermanent",
            "permanent": {
                "kind": "filterObjects",
                "objects": { "kind": "boundObjects", "binding": "damagedObjects" },
                "where": { "kind": "subtypeContains", "value": "Dragon" },
            },
        },
    ]);
    assert!(effects.as_array().unwrap().iter().all(effect_supported));

    engine
        .execute_effects(
            &effects,
            &stack_object,
            &mut BTreeMap::new(),
            &mut BTreeMap::new(),
            &mut EmeritusDecisionProvider,
        )
        .expect("the linked damage and destruction resolve");

    assert!(engine.permanent_position("dragon-recipient").is_none());
    assert!(
        engine.state.players[1]
            .graveyard
            .iter()
            .any(|card| card.instance_id == "dragon-recipient")
    );
}

struct EmeritusDecisionProvider;

impl DecisionProvider for EmeritusDecisionProvider {
    fn choose(
        &mut self,
        _state: &GameState,
        request: &EngineDecisionRequest,
    ) -> Result<usize, EngineError> {
        let selected = match request.kind {
            DecisionKind::Attackers => request
                .options
                .iter()
                .position(|action| action.kind == ActionKind::DeclareAttacker)
                .or_else(|| {
                    request
                        .options
                        .iter()
                        .position(|action| action.kind == ActionKind::FinishAttackers)
                }),
            DecisionKind::Priority => request
                .options
                .iter()
                .position(|action| action.kind == ActionKind::PassPriority),
            DecisionKind::ResolutionChoice => request.options.len().checked_sub(1),
            _ => Some(0),
        };
        selected.ok_or_else(|| EngineError::new("test decision has no matching option"))
    }
}

struct PassageDecisionProvider;

impl DecisionProvider for PassageDecisionProvider {
    fn choose(
        &mut self,
        _state: &GameState,
        request: &EngineDecisionRequest,
    ) -> Result<usize, EngineError> {
        request
            .options
            .iter()
            .position(|action| {
                action.label == "Choose Island" || action.kind == ActionKind::DeclinePayment
            })
            .ok_or_else(|| EngineError::new("test decision has no matching option"))
    }
}

struct CastSpellDecisionProvider;

impl DecisionProvider for CastSpellDecisionProvider {
    fn choose(
        &mut self,
        _state: &GameState,
        request: &EngineDecisionRequest,
    ) -> Result<usize, EngineError> {
        request
            .options
            .iter()
            .position(|action| action.kind == ActionKind::CastSpell)
            .or_else(|| request.options.len().checked_sub(1))
            .ok_or_else(|| EngineError::new("test decision has no option"))
    }
}

struct WardDecisionProvider {
    pay: bool,
}

impl DecisionProvider for WardDecisionProvider {
    fn choose(
        &mut self,
        _state: &GameState,
        request: &EngineDecisionRequest,
    ) -> Result<usize, EngineError> {
        if request.kind == DecisionKind::ResolutionChoice {
            let kind = if self.pay {
                ActionKind::ChooseResolution
            } else {
                ActionKind::DeclinePayment
            };
            return request
                .options
                .iter()
                .position(|action| action.kind == kind)
                .ok_or_else(|| EngineError::new("requested ward choice is unavailable"));
        }
        Ok(0)
    }
}

struct IslandNameDecisionProvider;

impl DecisionProvider for IslandNameDecisionProvider {
    fn choose(
        &mut self,
        _state: &GameState,
        request: &EngineDecisionRequest,
    ) -> Result<usize, EngineError> {
        request
            .options
            .iter()
            .position(|action| {
                action
                    .decisions
                    .get("chosenLandName")
                    .and_then(Value::as_array)
                    .is_some_and(|values| values.iter().any(|value| value == "Island"))
            })
            .or(Some(0))
            .ok_or_else(|| EngineError::new("land-name decision has no option"))
    }
}

struct RepeatingPriorityDecisionProvider;

impl DecisionProvider for RepeatingPriorityDecisionProvider {
    fn choose(
        &mut self,
        state: &GameState,
        request: &EngineDecisionRequest,
    ) -> Result<usize, EngineError> {
        let preferred = if request.kind == DecisionKind::Priority && state.stack.is_empty() {
            ActionKind::ActivateAbility
        } else {
            ActionKind::PassPriority
        };
        request
            .options
            .iter()
            .position(|action| action.kind == preferred)
            .or_else(|| {
                request
                    .options
                    .iter()
                    .position(|action| action.kind == ActionKind::PassPriority)
            })
            .ok_or_else(|| EngineError::new("repeating test decision has no option"))
    }

    fn requests_explicit_priority_pass(&self, _player_id: &str) -> bool {
        true
    }
}

#[derive(Default)]
struct CountedLoopDecisionProvider {
    number_requests: usize,
}

impl DecisionProvider for CountedLoopDecisionProvider {
    fn choose(
        &mut self,
        state: &GameState,
        request: &EngineDecisionRequest,
    ) -> Result<usize, EngineError> {
        let preferred = if request.kind == DecisionKind::Priority && state.stack.is_empty() {
            ActionKind::ActivateAbility
        } else {
            ActionKind::PassPriority
        };
        request
            .options
            .iter()
            .position(|action| action.kind == preferred)
            .or_else(|| {
                request
                    .options
                    .iter()
                    .position(|action| action.kind == ActionKind::PassPriority)
            })
            .ok_or_else(|| EngineError::new("counted loop test decision has no option"))
    }

    fn choose_number(
        &mut self,
        _state: &GameState,
        request: &EngineDecisionRequest,
    ) -> Result<i32, EngineError> {
        assert_eq!(decision_number_bounds(request), Some((0, 100)));
        self.number_requests += 1;
        Ok(3)
    }

    fn requests_explicit_priority_pass(&self, _player_id: &str) -> bool {
        true
    }
}

#[derive(Default)]
struct MultipleBlockersDecisionProvider {
    attackers_declared: usize,
    blockers_declared: usize,
    saw_attack_assignment: bool,
    saw_block_assignment: bool,
}

impl DecisionProvider for MultipleBlockersDecisionProvider {
    fn choose(
        &mut self,
        state: &GameState,
        request: &EngineDecisionRequest,
    ) -> Result<usize, EngineError> {
        match request.kind {
            DecisionKind::Attackers => {
                if self.attackers_declared == 0 {
                    self.attackers_declared += 1;
                    return request
                        .options
                        .iter()
                        .position(|action| {
                            action.kind == ActionKind::DeclareAttacker
                                && action.attacker_id.as_deref() == Some("attacker")
                        })
                        .ok_or_else(|| EngineError::new("attacker action is unavailable"));
                }
                let serialized = serde_json::to_value(state)
                    .map_err(|error| EngineError::new(error.to_string()))?;
                self.saw_attack_assignment = serialized["combat"]["attackers"][0]["attackerId"]
                    == "attacker"
                    && serialized["combat"]["attackers"][0]["defender"]["player"]["playerId"]
                        == "player-1";
                request
                    .options
                    .iter()
                    .position(|action| action.kind == ActionKind::FinishAttackers)
                    .ok_or_else(|| EngineError::new("finish attackers is unavailable"))
            }
            DecisionKind::Blockers => {
                if self.blockers_declared < 2 {
                    let blocker_id = if self.blockers_declared == 0 {
                        "blocker-a"
                    } else {
                        "blocker-b"
                    };
                    if self.blockers_declared == 1 {
                        let serialized = serde_json::to_value(state)
                            .map_err(|error| EngineError::new(error.to_string()))?;
                        self.saw_block_assignment = serialized["combat"]["blockers"][0]["blockerId"]
                            == "blocker-a"
                            && serialized["combat"]["blockers"][0]["attackerId"] == "attacker";
                    }
                    self.blockers_declared += 1;
                    return request
                        .options
                        .iter()
                        .position(|action| {
                            action.kind == ActionKind::DeclareBlocker
                                && action.blocker_id.as_deref() == Some(blocker_id)
                                && action.attacker_id.as_deref() == Some("attacker")
                        })
                        .ok_or_else(|| {
                            EngineError::new(format!(
                                "{blocker_id} cannot block the already-blocked attacker"
                            ))
                        });
                }
                request
                    .options
                    .iter()
                    .position(|action| action.kind == ActionKind::FinishBlockers)
                    .ok_or_else(|| EngineError::new("finish blockers is unavailable"))
            }
            DecisionKind::CombatDamage => request
                .options
                .iter()
                .position(|action| {
                    action.decisions["combatDamageAssignments"]["blocker-a"] == 3
                        && action.decisions["combatDamageAssignments"]["blocker-b"] == 1
                })
                .ok_or_else(|| EngineError::new("expected combat-damage division is unavailable")),
            DecisionKind::Priority => {
                let serialized = serde_json::to_value(state)
                    .map_err(|error| EngineError::new(error.to_string()))?;
                if serialized["combat"]["attackers"][0]["attackerId"] == "attacker"
                    && serialized["combat"]["attackers"][0]["defender"]["player"]["playerId"]
                        == "player-1"
                {
                    self.saw_attack_assignment = true;
                }
                request
                    .options
                    .iter()
                    .position(|action| action.kind == ActionKind::PassPriority)
                    .ok_or_else(|| EngineError::new("pass priority is unavailable"))
            }
            _ => Ok(0),
        }
    }

    fn requests_explicit_priority_pass(&self, _player_id: &str) -> bool {
        true
    }
}

fn test_definition(id: &str, type_line: &str) -> CardDefinition {
    CardDefinition {
        id: id.to_string(),
        is_commander: false,
        is_game_piece: false,
        is_sideboard: false,
        is_token: false,
        mana_cost: "{0}".to_string(),
        name: id.to_string(),
        power: has_card_type_name(type_line, "creature").then(|| "2".to_string()),
        rules: Vec::new(),
        toughness: has_card_type_name(type_line, "creature").then(|| "2".to_string()),
        type_line: type_line.to_string(),
    }
}

fn has_card_type_name(type_line: &str, card_type: &str) -> bool {
    type_line
        .split(|character: char| !character.is_alphabetic())
        .any(|word| word.eq_ignore_ascii_case(card_type))
}

fn test_instance(instance_id: &str, definition: CardDefinition, owner: &str) -> CardInstance {
    let mut instance = card_instance(owner, &definition, 0);
    instance.instance_id = instance_id.to_string();
    instance
}

fn test_engine(player_count: usize) -> GameEngine {
    let filler = test_definition("filler", "Basic Land - Plains");
    GameEngine::new(
        GameSetup {
            opening_hand_size: 7,
            players: (0..player_count)
                .map(|index| PlayerDeck {
                    cards: vec![filler.clone(); 12],
                    id: format!("player-{index}"),
                    name: format!("Player {index}"),
                    starting_life: 20,
                })
                .collect(),
            starting_player: 0,
        },
        73,
    )
    .expect("test setup is valid")
}

#[test]
fn parsed_bounded_free_hand_cast_evaluates_the_current_permanent_count() {
    let parsed = parse_oracle_card(OracleCardParseRequest {
        card_name: "Test Wizard".to_string(),
        type_line: "Legendary Creature - Avatar Wizard".to_string(),
        mana_cost: Some("{3}{W}".to_string()),
        oracle_text: Some(
            "At the beginning of combat on your turn, you may cast an instant or sorcery spell with mana value X or less from your hand without paying its mana cost, where X is twice the number of legendary Wizards you control."
                .to_string(),
        ),
        layout: None,
        faces: Vec::new(),
    });
    let rule = parsed.abilities[0]
        .rule
        .clone()
        .expect("the bounded free-cast trigger parses");
    assert!(rule_is_executable(&rule));

    let mut source_definition =
        test_definition("bounded-cast-source", "Legendary Creature - Avatar Wizard");
    source_definition.rules = vec![rule.clone()];
    let source = test_instance("bounded-cast-source", source_definition, "player-0");
    let mut cheap = test_definition("eligible-instant", "Instant");
    cheap.mana_cost = "{1}{U}".to_string();
    cheap.rules = vec![json!({
        "kind": "spellAbility",
        "source": { "kind": "self" },
        "effects": [{
            "kind": "gainLife",
            "player": { "kind": "controllerOf", "object": { "kind": "self" } },
            "amount": { "kind": "integer", "value": 1 },
        }],
    })];
    let mut expensive = test_definition("expensive-sorcery", "Sorcery");
    expensive.mana_cost = "{2}{U}".to_string();
    expensive.rules = cheap.rules.clone();

    let mut engine = test_engine(2);
    engine.state.players[0].battlefield = vec![source.clone()];
    engine.state.players[0].hand = vec![
        test_instance("eligible-instant", cheap, "player-0"),
        test_instance("expensive-sorcery", expensive, "player-0"),
    ];
    let trigger = StackObject {
        id: "stack:bounded-free-cast".to_string(),
        controller: "player-0".to_string(),
        card: source,
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: Some("triggeredAbility".to_string()),
        ability_rule: Some(rule.clone()),
        decisions: BTreeMap::new(),
        targets: BTreeMap::new(),
    };
    let mut bindings = BTreeMap::new();
    let mut decisions = BTreeMap::new();
    let eligible_cards = &rule["effects"][0]["cards"];
    let maximum_mana_value = &eligible_cards["where"]["operands"][1]["right"];
    assert_eq!(
        engine.runtime_numeric_expression(maximum_mana_value, &trigger, &bindings, &decisions,),
        Some(2)
    );
    assert_eq!(
        engine.resolve_runtime_object_ids(eligible_cards, &trigger, &bindings, &decisions,),
        Some(vec!["eligible-instant".to_string()])
    );
    engine
        .execute_effects(
            &rule["effects"],
            &trigger,
            &mut bindings,
            &mut decisions,
            &mut CastSpellDecisionProvider,
        )
        .expect("the eligible spell should be offered and cast for free");

    assert_eq!(decisions["spellsCastWithoutPaying"], 1);
    assert!(engine.state.stack.iter().any(|object| {
        object.card.instance_id == "eligible-instant"
            && object.decisions["withoutPayingManaCost"] == true
    }));
    assert!(
        engine.state.players[0]
            .hand
            .iter()
            .any(|card| card.instance_id == "expensive-sorcery")
    );
}

#[test]
fn parsed_counted_lord_bonus_tracks_only_matching_controlled_permanents() {
    let parsed = parse_oracle_card(OracleCardParseRequest {
        card_name: "Test Dwarf Lord".to_string(),
        type_line: "Legendary Creature - Dwarf Noble".to_string(),
        mana_cost: Some("{2}{R}".to_string()),
        oracle_text: Some(
            "Other Dwarves you control get +1/+0 for each artifact token you control.".to_string(),
        ),
        layout: None,
        faces: Vec::new(),
    });
    let rule = parsed.abilities[0]
        .rule
        .clone()
        .expect("the counted lord static ability parses");
    assert!(rule_is_executable(&rule));

    let mut source_definition = test_definition("counted-lord", "Legendary Creature - Dwarf Noble");
    source_definition.rules = vec![rule];
    let source = test_instance("counted-lord", source_definition, "player-0");
    let dwarf = test_instance(
        "other-dwarf",
        test_definition("other-dwarf", "Creature - Dwarf Warrior"),
        "player-0",
    );
    let human = test_instance(
        "unaffected-human",
        test_definition("unaffected-human", "Creature - Human"),
        "player-0",
    );
    let mut token_definition = test_definition("artifact-token", "Artifact - Treasure");
    token_definition.is_token = true;
    let first_token = test_instance("artifact-token-1", token_definition.clone(), "player-0");
    let second_token = test_instance("artifact-token-2", token_definition, "player-0");
    let ordinary_artifact = test_instance(
        "ordinary-artifact",
        test_definition("ordinary-artifact", "Artifact"),
        "player-0",
    );

    let mut engine = test_engine(2);
    engine.state.players[0].battlefield = vec![
        source,
        dwarf,
        human,
        first_token,
        second_token,
        ordinary_artifact,
    ];
    assert_eq!(
        engine.current_power(&engine.state.players[0].battlefield[0]),
        2
    );
    assert_eq!(
        engine.current_power(&engine.state.players[0].battlefield[1]),
        4
    );
    assert_eq!(
        engine.current_toughness(&engine.state.players[0].battlefield[1]),
        2
    );
    assert_eq!(
        engine.current_power(&engine.state.players[0].battlefield[2]),
        2
    );

    engine.state.players[0].battlefield.remove(3);
    assert_eq!(
        engine.current_power(&engine.state.players[0].battlefield[1]),
        3
    );
}

#[test]
fn parsed_named_token_supplement_preserves_quantity_without_recursing() {
    let parsed = parse_oracle_card(OracleCardParseRequest {
        card_name: "Test Token Supplement".to_string(),
        type_line: "Legendary Creature - Halfling Citizen".to_string(),
        mana_cost: Some("{1}{G}".to_string()),
        oracle_text: Some(
            "If you would create a Food token, instead create a Food token and a Treasure token."
                .to_string(),
        ),
        layout: None,
        faces: Vec::new(),
    });
    let rule = parsed.abilities[0]
        .rule
        .clone()
        .expect("the named-token supplement parses");
    assert!(rule_is_executable(&rule));

    let mut source_definition = test_definition(
        "token-supplement-source",
        "Legendary Creature - Halfling Citizen",
    );
    source_definition.rules = vec![rule];
    let source = test_instance("token-supplement-source", source_definition, "player-0");
    let stack_object = StackObject {
        id: "stack:token-supplement".to_string(),
        controller: "player-0".to_string(),
        card: source.clone(),
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: Some("spellAbility".to_string()),
        ability_rule: None,
        decisions: BTreeMap::new(),
        targets: BTreeMap::new(),
    };
    let mut engine = test_engine(2);
    engine.state.players[0].battlefield = vec![source];
    engine
        .create_tokens(
            &json!({
                "kind": "createTokens",
                "controller": { "kind": "controllerOf", "object": { "kind": "self" } },
                "quantity": { "kind": "integer", "value": 2 },
                "token": { "kind": "namedToken", "name": "Food" },
            }),
            &stack_object,
            &BTreeMap::new(),
            &BTreeMap::new(),
        )
        .expect("the replacement creates both named-token groups");

    let names = engine.state.players[0]
        .battlefield
        .iter()
        .filter(|card| card.definition.is_token)
        .map(|card| card.definition.name.as_str())
        .collect::<Vec<_>>();
    assert_eq!(names.iter().filter(|name| **name == "Food").count(), 2);
    assert_eq!(names.iter().filter(|name| **name == "Treasure").count(), 2);
    assert_eq!(names.len(), 4);
}

#[test]
fn parsed_linked_global_destruction_gains_life_for_actual_destructions_only() {
    let parsed = parse_oracle_card(OracleCardParseRequest {
        card_name: "Test Plate Stacker".to_string(),
        type_line: "Legendary Creature - Dwarf Warrior".to_string(),
        mana_cost: Some("{3}{W}".to_string()),
        oracle_text: Some(
            "When Test Plate Stacker enters, destroy all artifacts and enchantments your opponents control. You gain 1 life for each permanent destroyed this way."
                .to_string(),
        ),
        layout: None,
        faces: Vec::new(),
    });
    let rule = parsed.abilities[0]
        .rule
        .clone()
        .expect("the linked global destruction trigger parses");
    assert!(rule_is_executable(&rule));

    let source = test_instance(
        "plate-stacker",
        test_definition("plate-stacker", "Legendary Creature - Dwarf Warrior"),
        "player-0",
    );
    let mut indestructible = test_definition("indestructible-artifact", "Artifact");
    indestructible.rules = vec![json!({
        "kind": "keywordAbility",
        "source": { "kind": "self" },
        "ability": { "kind": "indestructible" },
    })];
    let mut engine = test_engine(2);
    engine.state.players[0].battlefield = vec![
        source.clone(),
        test_instance(
            "friendly-artifact",
            test_definition("friendly-artifact", "Artifact"),
            "player-0",
        ),
    ];
    engine.state.players[1].battlefield = vec![
        test_instance(
            "destroyed-artifact",
            test_definition("destroyed-artifact", "Artifact"),
            "player-1",
        ),
        test_instance(
            "destroyed-enchantment",
            test_definition("destroyed-enchantment", "Enchantment"),
            "player-1",
        ),
        test_instance("indestructible-artifact", indestructible, "player-1"),
        test_instance(
            "unmatched-creature",
            test_definition("unmatched-creature", "Creature"),
            "player-1",
        ),
    ];
    let trigger = StackObject {
        id: "stack:plate-stacker".to_string(),
        controller: "player-0".to_string(),
        card: source,
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: Some("triggeredAbility".to_string()),
        ability_rule: Some(rule.clone()),
        decisions: BTreeMap::new(),
        targets: BTreeMap::new(),
    };
    let mut bindings = BTreeMap::new();
    engine
        .execute_effects(
            &rule["effects"],
            &trigger,
            &mut bindings,
            &mut BTreeMap::new(),
            &mut EmeritusDecisionProvider,
        )
        .expect("global destruction and linked life gain resolve");

    assert_eq!(engine.state.players[0].life, 22);
    assert!(matches!(
        bindings.get("destroyedPermanents"),
        Some(RuntimeBinding::Objects(objects)) if objects.len() == 2
    ));
    assert!(
        engine.state.players[0]
            .battlefield
            .iter()
            .any(|card| card.instance_id == "friendly-artifact")
    );
    assert!(
        engine.state.players[1]
            .battlefield
            .iter()
            .any(|card| card.instance_id == "indestructible-artifact")
    );
    assert!(
        engine.state.players[1]
            .battlefield
            .iter()
            .any(|card| card.instance_id == "unmatched-creature")
    );
}

#[test]
fn parsed_controller_turn_equipped_keywords_follow_turn_and_attachment_state() {
    let parsed = parse_oracle_card(OracleCardParseRequest {
        card_name: "Test Lances".to_string(),
        type_line: "Artifact".to_string(),
        mana_cost: Some("{2}{W}".to_string()),
        oracle_text: Some(
            "During your turn, creatures you control that are equipped have first strike and vigilance."
                .to_string(),
        ),
        layout: None,
        faces: Vec::new(),
    });
    let rule = parsed.abilities[0]
        .rule
        .clone()
        .expect("the controller-turn equipped keyword ability parses");
    assert!(rule_is_executable(&rule));

    let mut source_definition = test_definition("lances", "Artifact");
    source_definition.rules = vec![rule];
    let source = test_instance("lances", source_definition, "player-0");
    let equipped = test_instance(
        "equipped-creature",
        test_definition("equipped-creature", "Creature - Dwarf"),
        "player-0",
    );
    let unequipped = test_instance(
        "unequipped-creature",
        test_definition("unequipped-creature", "Creature - Dwarf"),
        "player-0",
    );
    let mut equipment = test_instance(
        "test-equipment",
        test_definition("test-equipment", "Artifact - Equipment"),
        "player-0",
    );
    equipment.attached_to = Some("equipped-creature".to_string());
    let mut engine = test_engine(2);
    engine.state.players[0].battlefield = vec![source, equipped, unequipped, equipment];
    engine.state.active_player = 0;

    assert!(engine.permanent_has_keyword(&engine.state.players[0].battlefield[1], "firstStrike"));
    assert!(engine.permanent_has_keyword(&engine.state.players[0].battlefield[1], "vigilance"));
    assert!(!engine.permanent_has_keyword(&engine.state.players[0].battlefield[2], "vigilance"));

    engine.state.active_player = 1;
    assert!(!engine.permanent_has_keyword(&engine.state.players[0].battlefield[1], "firstStrike"));
    assert!(!engine.permanent_has_keyword(&engine.state.players[0].battlefield[1], "vigilance"));
}

#[test]
fn parsed_temporary_and_noncombat_damage_triggers_execute_with_correct_lifetimes() {
    let hall = parse_oracle_card(OracleCardParseRequest {
        card_name: "Test Dragon Hall".to_string(),
        type_line: "Artifact".to_string(),
        mana_cost: Some("{3}".to_string()),
        oracle_text: Some(
            "{1}, {T}: Until end of turn, target creature gains \"Whenever this creature deals combat damage to a player, create a Treasure token.\""
                .to_string(),
        ),
        layout: None,
        faces: Vec::new(),
    });
    let hall_rule = hall.abilities[0]
        .rule
        .clone()
        .expect("the temporary trigger activation parses");
    let hall_source = test_instance(
        "test-dragon-hall",
        test_definition("test-dragon-hall", "Artifact"),
        "player-0",
    );
    let attacker = test_instance(
        "temporary-attacker",
        test_definition("temporary-attacker", "Creature - Dwarf"),
        "player-0",
    );
    let hall_stack = StackObject {
        id: "stack:test-dragon-hall".to_string(),
        controller: "player-0".to_string(),
        card: hall_source,
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: Some("activatedAbility".to_string()),
        ability_rule: Some(hall_rule.clone()),
        decisions: BTreeMap::new(),
        targets: BTreeMap::from([(
            "targetPermanent".to_string(),
            TargetRef::Permanent {
                instance_id: "temporary-attacker".to_string(),
            },
        )]),
    };
    let mut engine = test_engine(2);
    engine.state.players[0].battlefield.push(attacker);
    engine
        .execute_effects(
            &hall_rule["effects"],
            &hall_stack,
            &mut BTreeMap::new(),
            &mut BTreeMap::new(),
            &mut EmeritusDecisionProvider,
        )
        .expect("the temporary trigger is granted");
    assert!(
        engine.state.players[0].battlefield[0]
            .definition
            .rules
            .iter()
            .any(|rule| rule["event"]["kind"] == "combatDamageToPlayer")
    );
    engine.enqueue_combat_damage_to_player_triggers("temporary-attacker", "player-1", 2);
    assert_eq!(engine.state.stack.len(), 1);
    engine
        .resolve_top_stack(&mut EmeritusDecisionProvider)
        .expect("the granted combat trigger resolves");
    assert!(
        engine.state.players[0]
            .battlefield
            .iter()
            .any(|card| type_line_contains(&card.definition.type_line, "Treasure"))
    );
    engine
        .cleanup(&mut EmeritusDecisionProvider)
        .expect("cleanup removes temporary granted abilities");
    assert!(
        !engine.state.players[0]
            .battlefield
            .iter()
            .find(|card| card.instance_id == "temporary-attacker")
            .expect("the attacker remains")
            .definition
            .rules
            .iter()
            .any(|rule| rule["event"]["kind"] == "combatDamageToPlayer")
    );

    let damaged = parse_oracle_card(OracleCardParseRequest {
        card_name: "Test Impenetrable Dragon".to_string(),
        type_line: "Legendary Creature - Dragon".to_string(),
        mana_cost: Some("{5}{R}".to_string()),
        oracle_text: Some(
            "Whenever Test Impenetrable Dragon is dealt noncombat damage, create that many Treasure tokens."
                .to_string(),
        ),
        layout: None,
        faces: Vec::new(),
    });
    let damaged_rule = damaged.abilities[0]
        .rule
        .clone()
        .expect("the noncombat damage trigger parses");
    let mut dragon_definition =
        test_definition("test-impenetrable-dragon", "Legendary Creature - Dragon");
    dragon_definition.toughness = Some("10".to_string());
    dragon_definition.rules = vec![damaged_rule];
    engine.state.players[0].battlefield.push(test_instance(
        "test-impenetrable-dragon",
        dragon_definition,
        "player-0",
    ));
    engine
        .deal_damage_amount_with_kind(
            TargetRef::Permanent {
                instance_id: "test-impenetrable-dragon".to_string(),
            },
            2,
            "combat-source",
            true,
        )
        .expect("combat damage resolves without matching the trigger");
    assert!(engine.state.stack.is_empty());
    engine
        .deal_damage_amount_with_kind(
            TargetRef::Permanent {
                instance_id: "test-impenetrable-dragon".to_string(),
            },
            3,
            "noncombat-source",
            false,
        )
        .expect("noncombat damage creates the trigger");
    assert_eq!(engine.state.stack.len(), 1);
    engine
        .resolve_top_stack(&mut EmeritusDecisionProvider)
        .expect("the damage-count token trigger resolves");
    assert_eq!(
        engine.state.players[0]
            .battlefield
            .iter()
            .filter(|card| type_line_contains(&card.definition.type_line, "Treasure"))
            .count(),
        4,
        "one Treasure came from the Hall and three from the damage amount"
    );
}

#[test]
fn parsed_multiplayer_control_and_dynamic_fixed_mana_mutate_live_state() {
    let control = parse_oracle_card(OracleCardParseRequest {
        card_name: "Test Burglaring".to_string(),
        type_line: "Sorcery".to_string(),
        mana_cost: Some("{4}{U}{U}".to_string()),
        oracle_text: Some(
            "For each opponent, gain control of up to one target artifact that player controls."
                .to_string(),
        ),
        layout: None,
        faces: Vec::new(),
    });
    let control_rule = control.abilities[0]
        .rule
        .clone()
        .expect("the multiplayer control spell parses");
    let control_stack = StackObject {
        id: "stack:test-burglaring".to_string(),
        controller: "player-0".to_string(),
        card: test_instance(
            "test-burglaring",
            test_definition("test-burglaring", "Sorcery"),
            "player-0",
        ),
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: Some("spellAbility".to_string()),
        ability_rule: Some(control_rule.clone()),
        decisions: BTreeMap::new(),
        targets: BTreeMap::from([
            (
                "controlTargets:0".to_string(),
                TargetRef::Permanent {
                    instance_id: "opponent-artifact-a".to_string(),
                },
            ),
            (
                "controlTargets:1".to_string(),
                TargetRef::Permanent {
                    instance_id: "opponent-artifact-b".to_string(),
                },
            ),
        ]),
    };
    let mut engine = test_engine(3);
    engine.state.players[1].battlefield.push(test_instance(
        "opponent-artifact-a",
        test_definition("opponent-artifact-a", "Artifact"),
        "player-1",
    ));
    engine.state.players[2].battlefield.push(test_instance(
        "opponent-artifact-b",
        test_definition("opponent-artifact-b", "Artifact Creature - Golem"),
        "player-2",
    ));
    engine
        .execute_effects(
            &control_rule["effects"],
            &control_stack,
            &mut BTreeMap::new(),
            &mut BTreeMap::new(),
            &mut EmeritusDecisionProvider,
        )
        .expect("both selected permanents change controller");
    assert!(engine.state.players[1].battlefield.is_empty());
    assert!(engine.state.players[2].battlefield.is_empty());
    assert_eq!(engine.state.players[0].battlefield.len(), 2);

    let mana = parse_oracle_card(OracleCardParseRequest {
        card_name: "Test Desire".to_string(),
        type_line: "Sorcery".to_string(),
        mana_cost: Some("{2}{R}".to_string()),
        oracle_text: Some("Add {R} for each artifact your opponents control.".to_string()),
        layout: None,
        faces: Vec::new(),
    });
    let mana_rule = mana.abilities[0]
        .rule
        .clone()
        .expect("the dynamic fixed-mana spell parses");
    let mana_stack = StackObject {
        id: "stack:test-desire".to_string(),
        controller: "player-0".to_string(),
        card: test_instance(
            "test-desire",
            test_definition("test-desire", "Sorcery"),
            "player-0",
        ),
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: Some("spellAbility".to_string()),
        ability_rule: Some(mana_rule.clone()),
        decisions: BTreeMap::new(),
        targets: BTreeMap::new(),
    };
    engine.state.players[1].battlefield = vec![
        test_instance(
            "counted-artifact-a",
            test_definition("counted-artifact-a", "Artifact"),
            "player-1",
        ),
        test_instance(
            "uncounted-creature",
            test_definition("uncounted-creature", "Creature"),
            "player-1",
        ),
    ];
    engine.state.players[2].battlefield = vec![
        test_instance(
            "counted-artifact-b",
            test_definition("counted-artifact-b", "Artifact Creature"),
            "player-2",
        ),
        test_instance(
            "counted-artifact-c",
            test_definition("counted-artifact-c", "Artifact - Clue"),
            "player-2",
        ),
    ];
    engine
        .execute_effects(
            &mana_rule["effects"],
            &mana_stack,
            &mut BTreeMap::new(),
            &mut BTreeMap::new(),
            &mut EmeritusDecisionProvider,
        )
        .expect("the current opposing artifact count produces fixed red mana");
    assert_eq!(engine.state.players[0].mana_pool.len(), 3);
    assert!(
        engine.state.players[0]
            .mana_pool
            .iter()
            .all(|mana| mana.symbol == "R")
    );
}

#[test]
fn parsed_alternative_cast_and_land_entry_events_share_one_live_effect() {
    let parsed = parse_oracle_card(OracleCardParseRequest {
        card_name: "Test Necklace".to_string(),
        type_line: "Artifact".to_string(),
        mana_cost: Some("{2}".to_string()),
        oracle_text: Some(
            "Whenever you cast a green spell and whenever a Forest you control enters, put a +1/+1 counter on target creature you control."
                .to_string(),
        ),
        layout: None,
        faces: Vec::new(),
    });
    let rule = parsed.abilities[0]
        .rule
        .clone()
        .expect("the alternative-event trigger parses");
    let mut necklace_definition = test_definition("test-necklace", "Artifact");
    necklace_definition.rules = vec![rule];
    let necklace = test_instance("test-necklace", necklace_definition, "player-0");
    let creature = test_instance(
        "necklace-target",
        test_definition("necklace-target", "Creature - Dwarf"),
        "player-0",
    );
    let mut engine = test_engine(2);
    engine.state.players[0].battlefield = vec![necklace, creature];

    let mut green_spell = test_definition("green-spell", "Sorcery");
    green_spell.mana_cost = "{G}".to_string();
    engine.enqueue_spell_cast_triggers("player-0", &green_spell, &BTreeMap::new());
    assert_eq!(engine.state.stack.len(), 1);
    engine
        .resolve_top_stack(&mut EmeritusDecisionProvider)
        .expect("the green-spell branch resolves");
    assert_eq!(
        engine.state.players[0].battlefield[1].counters.get("+1/+1"),
        Some(&1)
    );

    let forest = test_instance(
        "entering-forest",
        test_definition("entering-forest", "Land - Forest"),
        "player-0",
    );
    engine.state.players[0].battlefield.push(forest.clone());
    engine.enqueue_enter_battlefield_triggers(&forest);
    assert_eq!(engine.state.stack.len(), 1);
    engine
        .resolve_top_stack(&mut EmeritusDecisionProvider)
        .expect("the Forest-entry branch resolves");
    assert_eq!(
        engine.state.players[0].battlefield[1].counters.get("+1/+1"),
        Some(&2)
    );
}

#[test]
fn life_loss_trigger_mills_the_triggering_player_by_the_actual_amount() {
    let mut engine = test_engine(2);
    let mut source_definition = test_definition("life-loss-observer", "Creature - Horror");
    source_definition.rules = vec![json!({
        "kind": "triggeredAbility",
        "source": { "kind": "self" },
        "event": { "kind": "lifeLost", "player": { "kind": "eachPlayer" } },
        "effects": [{
            "kind": "mill",
            "player": { "kind": "triggeringPlayer" },
            "count": { "kind": "decisionResult", "decisionId": "lifeLostAmount" },
        }],
    })];
    engine.state.players[0].battlefield.push(test_instance(
        "life-loss-observer",
        source_definition,
        "player-0",
    ));
    engine.state.players[1].library = (0..6)
        .map(|index| {
            let id = format!("mill-target-{index}");
            test_instance(&id, test_definition(&id, "Basic Land - Island"), "player-1")
        })
        .collect();
    engine.state.players[1].graveyard.clear();

    engine
        .lose_life("player-1", 3, "test-source")
        .expect("the player loses life and creates the trigger");
    assert_eq!(engine.state.stack.len(), 1);
    engine
        .resolve_top_stack(&mut EmeritusDecisionProvider)
        .expect("the linked mill trigger resolves");

    assert_eq!(engine.state.players[1].life, 17);
    assert_eq!(engine.state.players[1].library.len(), 3);
    assert_eq!(engine.state.players[1].graveyard.len(), 3);
    assert_eq!(engine.state.players[0].graveyard.len(), 0);
}

#[test]
fn optional_hand_discard_binds_the_draw_and_story_damage_amount() {
    let mut engine = test_engine(3);
    engine.state.players[0].hand = (0..3)
        .map(|index| {
            let id = format!("discarded-hand-{index}");
            test_instance(&id, test_definition(&id, "Creature"), "player-0")
        })
        .collect();
    engine.state.players[0].library = (0..6)
        .map(|index| {
            let id = format!("replacement-draw-{index}");
            test_instance(&id, test_definition(&id, "Basic Land - Plains"), "player-0")
        })
        .collect();
    engine.state.players[0].graveyard.clear();
    engine.state.rule_modifiers.push(json!({
        "kind": "enduringStory",
        "playerId": "player-0",
    }));
    let stack_object = StackObject {
        id: "stack:optional-hand-discard".to_string(),
        controller: "player-0".to_string(),
        card: test_instance(
            "optional-hand-discard",
            test_definition("optional-hand-discard", "Creature - Dwarf"),
            "player-0",
        ),
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: Some("triggeredAbility".to_string()),
        ability_rule: None,
        decisions: BTreeMap::new(),
        targets: BTreeMap::new(),
    };

    engine
        .execute_effects(
            &json!([{
                "kind": "optionalAction",
                "player": { "kind": "controllerOf", "object": { "kind": "self" } },
                "action": {
                    "kind": "discardHand",
                    "player": { "kind": "controllerOf", "object": { "kind": "self" } },
                    "bindCountAs": "discardedHandCount",
                },
                "onPerformed": [
                    {
                        "kind": "drawCards",
                        "player": { "kind": "controllerOf", "object": { "kind": "self" } },
                        "count": { "kind": "boundValue", "id": "discardedHandCount" },
                    },
                    {
                        "kind": "conditionalEffect",
                        "condition": {
                            "kind": "hasEnduringStory",
                            "player": { "kind": "controllerOf", "object": { "kind": "self" } },
                        },
                        "then": [{
                            "kind": "dealDamageToEachOpponent",
                            "amount": { "kind": "boundValue", "id": "discardedHandCount" },
                        }],
                        "else": [],
                    },
                ],
            }]),
            &stack_object,
            &mut BTreeMap::new(),
            &mut BTreeMap::new(),
            &mut EmeritusDecisionProvider,
        )
        .expect("the optional discard, linked draw, and damage resolve");

    assert_eq!(engine.state.players[0].hand.len(), 3);
    assert_eq!(engine.state.players[0].graveyard.len(), 3);
    assert_eq!(engine.state.players[0].library.len(), 3);
    assert_eq!(engine.state.players[1].life, 17);
    assert_eq!(engine.state.players[2].life, 17);
}

#[test]
fn optional_sacrifice_binds_last_known_power_before_moving_the_card() {
    let mut engine = test_engine(2);
    let source = test_instance(
        "counter-source",
        test_definition("counter-source", "Creature"),
        "player-0",
    );
    let mut sacrifice_definition = test_definition("large-sacrifice", "Creature");
    sacrifice_definition.power = Some("4".to_string());
    sacrifice_definition.toughness = Some("4".to_string());
    engine.state.players[0].battlefield.extend([
        source.clone(),
        test_instance("large-sacrifice", sacrifice_definition, "player-0"),
    ]);
    let stack_object = StackObject {
        id: "stack:linked-sacrifice".to_string(),
        controller: "player-0".to_string(),
        card: source,
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: Some("triggeredAbility".to_string()),
        ability_rule: None,
        decisions: BTreeMap::new(),
        targets: BTreeMap::new(),
    };

    engine
        .execute_effects(
            &json!([{
                "kind": "optionalAction",
                "player": { "kind": "controllerOf", "object": { "kind": "self" } },
                "action": {
                    "kind": "sacrificePermanents",
                    "player": { "kind": "controllerOf", "object": { "kind": "self" } },
                    "where": { "kind": "cardTypeContains", "value": "Creature" },
                    "count": { "kind": "integer", "value": 1 },
                    "excludeSource": true,
                    "bindPowerAs": "sacrificedPermanentPower",
                },
                "onPerformed": [{
                    "kind": "putCounters",
                    "permanent": { "kind": "self" },
                    "counter": "+1/+1",
                    "count": { "kind": "boundValue", "id": "sacrificedPermanentPower" },
                }],
            }]),
            &stack_object,
            &mut BTreeMap::new(),
            &mut BTreeMap::new(),
            &mut EmeritusDecisionProvider,
        )
        .expect("the sacrifice and linked counters resolve");

    assert!(
        engine.state.players[0]
            .graveyard
            .iter()
            .any(|card| card.instance_id == "large-sacrifice")
    );
    let source = engine.state.players[0]
        .battlefield
        .iter()
        .find(|card| card.instance_id == "counter-source")
        .expect("the source remains on the battlefield");
    assert_eq!(source.counters.get("+1/+1"), Some(&4));
}

#[test]
fn recent_opponent_graveyard_cards_enter_with_replaced_characteristics() {
    let mut engine = test_engine(3);
    let first = test_instance(
        "recent-creature-a",
        test_definition("recent-creature-a", "Legendary Creature - Elf"),
        "player-1",
    );
    let second = test_instance(
        "recent-creature-b",
        test_definition("recent-creature-b", "Creature - Goblin"),
        "player-2",
    );
    engine.state.players[1].battlefield.push(first);
    engine.state.players[2].battlefield.push(second);
    engine
        .move_permanent_to_graveyard("recent-creature-a", "destroyed")
        .expect("the first opponent creature dies this turn");
    engine
        .move_permanent_to_graveyard("recent-creature-b", "destroyed")
        .expect("the second opponent creature dies this turn");
    let stack_object = StackObject {
        id: "stack:mass-recent-return".to_string(),
        controller: "player-0".to_string(),
        card: test_instance(
            "mass-recent-return",
            test_definition("mass-recent-return", "Sorcery"),
            "player-0",
        ),
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: None,
        ability_rule: None,
        decisions: BTreeMap::new(),
        targets: BTreeMap::new(),
    };
    let granted_ability = json!({
        "kind": "activatedAbility",
        "source": { "kind": "self" },
        "costs": [{ "kind": "payMana", "manaCost": "{2}" }],
        "effects": [{
            "kind": "gainLife",
            "player": { "kind": "controllerOf", "object": { "kind": "self" } },
            "amount": { "kind": "integer", "value": 3 },
        }],
    });

    engine
        .execute_effects(
            &json!([{
                "kind": "returnRecentGraveyardCards",
                "player": {
                    "kind": "opponentsOf",
                    "player": { "kind": "controllerOf", "object": { "kind": "self" } },
                },
                "controller": { "kind": "controllerOf", "object": { "kind": "self" } },
                "where": { "kind": "cardTypeContains", "value": "Creature" },
                "all": true,
                "tapped": false,
                "enterAs": {
                    "types": ["Artifact"],
                    "subtypes": ["Food"],
                    "retainSupertypes": true,
                    "grantAbilities": [granted_ability],
                },
            }]),
            &stack_object,
            &mut BTreeMap::new(),
            &mut BTreeMap::new(),
            &mut EmeritusDecisionProvider,
        )
        .expect("both recent opponent cards return under the spell controller's control");

    assert!(engine.state.players[1].graveyard.is_empty());
    assert!(engine.state.players[2].graveyard.is_empty());
    let returned = engine.state.players[0]
        .battlefield
        .iter()
        .filter(|card| card.instance_id.starts_with("recent-creature-"))
        .collect::<Vec<_>>();
    assert_eq!(returned.len(), 2);
    assert!(returned.iter().all(|card| card.controller == "player-0"));
    assert!(returned.iter().all(|card| {
        card.definition
            .rules
            .iter()
            .any(|rule| value_kind(rule) == Some("activatedAbility"))
    }));
    assert_eq!(
        returned[0].definition.type_line,
        "Legendary Artifact - Food"
    );
    assert_eq!(returned[1].definition.type_line, "Artifact - Food");
}

#[test]
fn dredge_replaces_each_draw_only_when_the_full_mill_is_possible() {
    struct ChooseDredge;
    impl DecisionProvider for ChooseDredge {
        fn choose(
            &mut self,
            _state: &GameState,
            request: &EngineDecisionRequest,
        ) -> Result<usize, EngineError> {
            request
                .options
                .iter()
                .position(|action| {
                    action
                        .decisions
                        .get("dredgeSource")
                        .and_then(Value::as_str)
                        .is_some()
                })
                .ok_or_else(|| EngineError::new("expected a legal dredge replacement"))
        }
    }

    let mut engine = test_engine(2);
    engine.state.players[0].hand.clear();
    engine.state.players[0].graveyard.clear();
    engine.state.players[0].library = (0..4)
        .map(|index| {
            test_instance(
                &format!("library-{index}"),
                test_definition(&format!("library-{index}"), "Basic Land - Forest"),
                "player-0",
            )
        })
        .collect();
    let mut dredge_definition = test_definition("dredge-card", "Sorcery");
    dredge_definition.rules.push(json!({
        "kind": "keywordAbility",
        "source": { "kind": "self" },
        "ability": { "kind": "dredge", "count": { "kind": "integer", "value": 3 } },
    }));
    engine.state.players[0].graveyard.push(test_instance(
        "dredge-card",
        dredge_definition.clone(),
        "player-0",
    ));

    engine
        .draw_cards_with_replacements("player-0", 1, &mut ChooseDredge)
        .expect("a legal dredge replaces the draw");

    assert_eq!(engine.state.players[0].library.len(), 1);
    assert_eq!(engine.state.players[0].hand.len(), 1);
    assert_eq!(engine.state.players[0].hand[0].instance_id, "dredge-card");
    assert_eq!(engine.state.players[0].graveyard.len(), 3);
    assert!(engine.state.events.iter().any(|event| {
        event.kind == "drawReplacedWithDredge"
            && event.card_instance_id.as_deref() == Some("dredge-card")
    }));
    assert!(
        !engine
            .state
            .events
            .iter()
            .any(|event| event.kind == "cardDrawn")
    );

    engine.state.players[0].hand.clear();
    engine.state.players[0].library = (0..2)
        .map(|index| {
            test_instance(
                &format!("short-library-{index}"),
                test_definition(&format!("short-library-{index}"), "Basic Land - Forest"),
                "player-0",
            )
        })
        .collect();
    engine.state.players[0].graveyard.clear();
    engine.state.players[0].graveyard.push(test_instance(
        "dredge-card-short",
        dredge_definition,
        "player-0",
    ));
    engine
        .draw_cards_with_replacements("player-0", 1, &mut EmeritusDecisionProvider)
        .expect("an unavailable dredge falls back to the normal draw");
    assert_eq!(engine.state.players[0].library.len(), 1);
    assert_eq!(engine.state.players[0].hand.len(), 1);
    assert_eq!(
        engine.state.players[0].graveyard[0].instance_id,
        "dredge-card-short"
    );
}

#[test]
fn died_source_and_top_cards_return_as_one_shuffled_library_pile() {
    let mut engine = test_engine(2);
    engine.state.players[0].library = (0..8)
        .map(|index| {
            test_instance(
                &format!("pile-library-{index}"),
                test_definition(&format!("pile-library-{index}"), "Basic Land - Forest"),
                "player-0",
            )
        })
        .collect();
    engine.state.players[0].graveyard.clear();
    engine.state.players[0].battlefield.clear();
    let mut source_definition = test_definition("pile-source", "Creature - Test");
    source_definition.rules.push(json!({
        "kind": "triggeredAbility",
        "source": { "kind": "self" },
        "event": { "kind": "permanentDied", "object": { "kind": "self" } },
        "effects": [{
            "kind": "exileDiedSourceAndTopCardsAsShuffledLibraryPile",
            "player": { "kind": "controllerOf", "object": { "kind": "self" } },
            "count": { "kind": "integer", "value": 6 },
            "faceDown": true,
            "destination": "libraryTop",
        }],
    }));
    engine.state.players[0].battlefield.push(test_instance(
        "pile-source",
        source_definition,
        "player-0",
    ));

    engine
        .move_permanent_to_graveyard("pile-source", "destroyed")
        .expect("the source dies and creates its trigger");
    assert_eq!(engine.state.stack.len(), 1);
    engine
        .resolve_top_stack(&mut EmeritusDecisionProvider)
        .expect("the shuffled pile trigger resolves");

    assert_eq!(engine.state.players[0].library.len(), 9);
    assert!(engine.state.players[0].graveyard.is_empty());
    let top_pile = engine.state.players[0].library[2..]
        .iter()
        .map(|card| card.instance_id.as_str())
        .collect::<BTreeSet<_>>();
    let expected = [
        "pile-source",
        "pile-library-2",
        "pile-library-3",
        "pile-library-4",
        "pile-library-5",
        "pile-library-6",
        "pile-library-7",
    ]
    .into_iter()
    .collect::<BTreeSet<_>>();
    assert_eq!(top_pile, expected);
    assert!(
        engine.state.players[0]
            .library
            .iter()
            .all(|card| card.flags.get("faceDown") != Some(&true))
    );
}

