#[test]
fn escalate_repeats_the_shared_cost_for_each_extra_selected_mode() {
    let mut engine = test_engine(2);
    engine.state.players[0].hand = (1..=3)
        .map(|index| {
            test_instance(
                &format!("escalate-payment-{index}"),
                test_definition(&format!("escalate-payment-{index}"), "Creature - Test"),
                "player-0",
            )
        })
        .collect();
    let mut definition = test_definition("escalate-spell", "Sorcery");
    definition.rules = vec![
        json!({
            "kind": "keywordAbility",
            "source": { "kind": "self" },
            "ability": {
                "kind": "escalate",
                "cost": { "kind": "discardCard", "where": null },
            },
        }),
        json!({
            "kind": "spellAbility",
            "source": { "kind": "self" },
            "declaration": {
                "kind": "castingDeclaration",
                "decisions": [{
                    "id": "chosenModes",
                    "kind": "chooseModes",
                    "minimum": 1,
                    "maximum": 3,
                    "options": ["mode1", "mode2", "mode3"],
                }],
            },
            "effects": [],
        }),
    ];

    let declarations = engine
        .declarations_for_card(&definition, "player-0")
        .expect("escalate declarations are generated");
    let one_mode = declarations
        .iter()
        .find(|declaration| escalate_payment_count(&declaration.decisions) == 0)
        .expect("choosing one mode remains free");
    assert!(GameEngine::escalate_cost_target_ids(&definition, &one_mode.decisions).is_empty());

    let three_modes = declarations
        .iter()
        .find(|declaration| {
            escalate_payment_count(&declaration.decisions) == 2
                && GameEngine::escalate_cost_target_ids(&definition, &declaration.decisions)
                    .iter()
                    .all(|target_id| declaration.targets.contains_key(target_id))
        })
        .expect("choosing three modes declares two payments")
        .clone();
    let payment_targets = GameEngine::escalate_cost_target_ids(&definition, &three_modes.decisions)
        .into_iter()
        .map(|target_id| three_modes.targets[&target_id].clone())
        .collect::<Vec<_>>();
    assert_eq!(payment_targets.len(), 2);
    assert_ne!(payment_targets[0], payment_targets[1]);

    let action = LegalAction {
        id: "cast:escalate-spell".to_string(),
        kind: ActionKind::CastSpell,
        player_id: "player-0".to_string(),
        label: "Cast escalate spell".to_string(),
        card_instance_id: Some("escalate-spell".to_string()),
        payment_sources: Vec::new(),
        decisions: three_modes.decisions,
        targets: three_modes.targets,
        target_order: three_modes.target_order,
        attacker_id: None,
        blocker_id: None,
    };
    engine
        .apply_escalate_costs(&action, &definition)
        .expect("both escalate discard costs are paid");
    assert_eq!(engine.state.players[0].hand.len(), 1);
    assert_eq!(engine.state.players[0].graveyard.len(), 2);
}

