fn training_setup() -> GameSetup {
    GameSetup {
        opening_hand_size: crate::game_rules::TRAINING_OPENING_HAND_SIZE,
        players: (0..2)
            .map(|player_index| PlayerDeck {
                cards: (0..40)
                    .map(|card_index| {
                        let mut card = test_definition(
                            &format!("training-{player_index}-{card_index}"),
                            "Artifact",
                        );
                        card.is_commander = card_index == 0;
                        card
                    })
                    .collect(),
                id: format!("training-player-{player_index}"),
                name: format!("Training Player {player_index}"),
                starting_life: 20,
            })
            .collect(),
        starting_player: 0,
    }
}

fn training2_setup() -> GameSetup {
    GameSetup {
        opening_hand_size: crate::game_rules::TRAINING2_OPENING_HAND_SIZE,
        players: (0..2)
            .map(|player_index| PlayerDeck {
                cards: (0..61)
                    .map(|card_index| {
                        let mut card = test_definition(
                            &format!("training2-{player_index}-{card_index}"),
                            if card_index == 0 {
                                "Legendary Creature"
                            } else {
                                "Artifact"
                            },
                        );
                        card.is_commander = card_index == 0;
                        card
                    })
                    .collect(),
                id: format!("training2-player-{player_index}"),
                name: format!("Training 2 Player {player_index}"),
                starting_life: 20,
            })
            .collect(),
        starting_player: 0,
    }
}

fn retained_card_ids(engine: &GameEngine, player_index: usize) -> BTreeSet<String> {
    engine.state.players[player_index]
        .library
        .iter()
        .chain(&engine.state.players[player_index].hand)
        .map(|card| card.instance_id.clone())
        .collect()
}

#[test]
fn training_mode_keeps_seeded_twenty_card_decks_and_draws_five() {
    let first = GameEngine::new_with_mode(training_setup(), 73, GameMode::Training).unwrap();
    let repeated = GameEngine::new_with_mode(training_setup(), 73, GameMode::Training).unwrap();
    let different = GameEngine::new_with_mode(training_setup(), 74, GameMode::Training).unwrap();

    for player in &first.state.players {
        assert_eq!(player.life, crate::game_rules::TRAINING_STARTING_LIFE);
        assert_eq!(player.hand.len(), 5);
        assert_eq!(player.library.len(), 15);
        assert!(player.command_zone.is_empty());
    }
    assert!(first.state.commanders.is_empty());
    assert_eq!(
        retained_card_ids(&first, 0),
        retained_card_ids(&repeated, 0)
    );
    assert_ne!(
        retained_card_ids(&first, 0),
        retained_card_ids(&different, 0)
    );
}

#[test]
fn training2_mode_keeps_commander_and_seeded_forty_card_libraries() {
    let first = GameEngine::new_with_mode(training2_setup(), 73, GameMode::Training2).unwrap();
    let repeated = GameEngine::new_with_mode(training2_setup(), 73, GameMode::Training2).unwrap();
    let different = GameEngine::new_with_mode(training2_setup(), 74, GameMode::Training2).unwrap();

    for player in &first.state.players {
        assert_eq!(player.life, crate::game_rules::TRAINING2_STARTING_LIFE);
        assert_eq!(player.hand.len(), 6);
        assert_eq!(player.library.len(), 34);
        assert_eq!(player.command_zone.len(), 1);
        assert!(player.command_zone[0].definition.is_commander);
    }
    assert_eq!(first.state.commanders.len(), 2);
    assert_eq!(
        retained_card_ids(&first, 0),
        retained_card_ids(&repeated, 0)
    );
    assert_ne!(
        retained_card_ids(&first, 0),
        retained_card_ids(&different, 0)
    );
}

struct AlwaysMulliganProvider;

impl DecisionProvider for AlwaysMulliganProvider {
    fn choose(
        &mut self,
        _state: &GameState,
        request: &EngineDecisionRequest,
    ) -> Result<usize, EngineError> {
        request
            .options
            .iter()
            .position(|action| action.kind == ActionKind::TakeMulligan)
            .or_else(|| {
                request
                    .options
                    .iter()
                    .position(|action| action.kind == ActionKind::KeepHand)
            })
            .ok_or_else(|| EngineError::new("mulligan test has no legal choice"))
    }
}

#[test]
fn maximum_mulligans_removes_the_fourth_mulligan_option() {
    let mut engine = GameEngine::new_with_mode(training_setup(), 73, GameMode::Training).unwrap();
    engine
        .run_mulligans(&mut AlwaysMulliganProvider, 3, Some(3))
        .unwrap();
    let mulligans_by_player = engine
        .state
        .events
        .iter()
        .filter(|event| event.kind == "mulliganTaken")
        .fold(BTreeMap::<String, usize>::new(), |mut counts, event| {
            *counts
                .entry(event.player_id.clone().expect("mulligan has a player"))
                .or_default() += 1;
            counts
        });
    assert_eq!(
        mulligans_by_player.values().copied().collect::<Vec<_>>(),
        vec![3, 3]
    );
    assert!(
        engine
            .state
            .events
            .iter()
            .filter(|event| event.kind == "openingHandKept")
            .all(|event| event.detail["mulligans"] == 3)
    );
}

