#[test]
fn split_library_search_moves_one_selected_card_to_each_destination() {
    struct SplitSearchSelectionProvider {
        call_index: usize,
    }

    impl DecisionProvider for SplitSearchSelectionProvider {
        fn choose(
            &mut self,
            _state: &GameState,
            _request: &EngineDecisionRequest,
        ) -> Result<usize, EngineError> {
            Err(EngineError::new("split library search uses card selection"))
        }

        fn choose_card_instance_ids(
            &mut self,
            _state: &GameState,
            request: &EngineDecisionRequest,
        ) -> Result<Vec<String>, EngineError> {
            let Some(DecisionChoice::CardSelection {
                candidate_card_instance_ids,
                minimum,
                maximum,
                ..
            }) = request.choice.as_ref()
            else {
                return Err(EngineError::new("expected split-search card selection"));
            };
            let selection = match self.call_index {
                0 => {
                    assert_eq!((*minimum, *maximum), (0, 2));
                    assert_eq!(
                        candidate_card_instance_ids,
                        &["basic-1".to_string(), "basic-2".to_string()]
                    );
                    vec!["basic-1".to_string(), "basic-2".to_string()]
                }
                1 => {
                    assert_eq!((*minimum, *maximum), (1, 1));
                    assert_eq!(
                        candidate_card_instance_ids,
                        &["basic-1".to_string(), "basic-2".to_string()]
                    );
                    vec!["basic-1".to_string()]
                }
                _ => return Err(EngineError::new("unexpected split-search decision")),
            };
            self.call_index += 1;
            Ok(selection)
        }
    }

    let mut engine = test_engine(2);
    engine.state.players[0].library = vec![
        test_instance(
            "basic-1",
            test_definition("basic-1", "Basic Land - Forest"),
            "player-0",
        ),
        test_instance(
            "other-card",
            test_definition("other-card", "Sorcery"),
            "player-0",
        ),
        test_instance(
            "basic-2",
            test_definition("basic-2", "Basic Land - Island"),
            "player-0",
        ),
    ];
    let source = StackObject {
        id: "stack:split-search".to_string(),
        controller: "player-0".to_string(),
        card: test_instance(
            "search-source",
            test_definition("search-source", "Creature"),
            "player-0",
        ),
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: None,
        ability_rule: None,
        decisions: BTreeMap::new(),
        targets: BTreeMap::new(),
    };
    let effects = json!([
        {
            "kind": "chooseCards",
            "id": "searchedCards",
            "player": { "kind": "abilityController" },
            "minimum": 0,
            "maximum": 2,
            "candidates": {
                "kind": "cards",
                "zone": { "kind": "library", "player": { "kind": "abilityController" } },
                "where": {
                    "kind": "and",
                    "operands": [
                        { "kind": "typeLineContains", "value": "Basic" },
                        { "kind": "cardTypeContains", "value": "Land" },
                    ],
                },
            },
        },
        {
            "kind": "revealCards",
            "cards": { "kind": "decisionResult", "decisionId": "searchedCards" },
        },
        {
            "kind": "chooseCards",
            "id": "battlefieldCard",
            "player": { "kind": "abilityController" },
            "from": { "kind": "decisionResult", "decisionId": "searchedCards" },
            "count": { "kind": "integer", "value": 1 },
        },
        {
            "kind": "moveCards",
            "cards": { "kind": "decisionResult", "decisionId": "battlefieldCard" },
            "to": {
                "kind": "battlefield",
                "player": { "kind": "abilityController" },
                "tapped": true,
            },
        },
        {
            "kind": "moveCards",
            "cards": {
                "kind": "setDifference",
                "left": { "kind": "decisionResult", "decisionId": "searchedCards" },
                "right": { "kind": "decisionResult", "decisionId": "battlefieldCard" },
            },
            "to": { "kind": "hand", "player": { "kind": "abilityController" } },
        },
        {
            "kind": "shuffleZone",
            "zone": { "kind": "library", "player": { "kind": "abilityController" } },
        },
    ]);
    let mut provider = SplitSearchSelectionProvider { call_index: 0 };

    engine
        .execute_effects(
            &effects,
            &source,
            &mut BTreeMap::new(),
            &mut BTreeMap::new(),
            &mut provider,
        )
        .expect("split library search resolves");

    assert_eq!(provider.call_index, 2);
    assert_eq!(
        engine.state.players[0].battlefield[0].instance_id,
        "basic-1"
    );
    assert!(engine.state.players[0].battlefield[0].tapped);
    assert_eq!(engine.state.players[0].hand[0].instance_id, "basic-2");
    assert_eq!(engine.state.players[0].library[0].instance_id, "other-card");
}

