#[test]
fn promised_gift_effect_uses_the_bound_recipient_and_restricts_each_player() {
    let mut engine = test_engine(2);
    let source = StackObject {
        id: "stack:gift".to_string(),
        controller: "player-0".to_string(),
        card: test_instance(
            "gift-source",
            test_definition("gift-source", "Instant"),
            "player-0",
        ),
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: None,
        ability_rule: None,
        decisions: BTreeMap::new(),
        targets: BTreeMap::new(),
    };
    let gift = json!([{
        "kind": "createTokens",
        "controller": { "kind": "boundValue", "id": "giftRecipient" },
        "quantity": { "kind": "integer", "value": 1 },
        "token": { "kind": "namedToken", "name": "Treasure" },
    }]);
    let restriction = json!([{
        "kind": "conditionalEffect",
        "condition": {
            "kind": "selectionNotEmpty",
            "selection": { "kind": "decisionResult", "decisionId": "giftRecipient" },
        },
        "then": [{
            "kind": "restrictPlayerActions",
            "player": { "kind": "eachPlayer" },
            "castSpells": true,
            "activateAbilities": false,
            "duration": { "kind": "untilEndOfCurrentTurn" },
        }],
        "else": [],
    }]);
    let mut provider = EmeritusDecisionProvider;
    let mut bindings = BTreeMap::from([(
        "giftRecipient".to_string(),
        RuntimeBinding::Player("player-1".to_string()),
    )]);
    let mut decisions = BTreeMap::from([(
        "giftRecipient".to_string(),
        Value::String("player-1".to_string()),
    )]);

    engine
        .execute_effects(&gift, &source, &mut bindings, &mut decisions, &mut provider)
        .expect("gift effect resolves for the bound opponent");
    engine
        .execute_effects(
            &restriction,
            &source,
            &mut bindings,
            &mut decisions,
            &mut provider,
        )
        .expect("promised-gift followup resolves");

    assert_eq!(engine.state.players[0].battlefield.len(), 0);
    assert_eq!(engine.state.players[1].battlefield.len(), 1);
    assert_eq!(
        engine.state.players[1].battlefield[0].definition.name,
        "Treasure"
    );
    let restricted_players = engine
        .state
        .rule_modifiers
        .iter()
        .filter(|modifier| value_kind(modifier) == Some("playerActionRestriction"))
        .map(|modifier| modifier["playerId"].as_str().unwrap_or_default())
        .collect::<BTreeSet<_>>();
    assert_eq!(restricted_players, BTreeSet::from(["player-0", "player-1"]));
}

#[test]
fn doppelgang_ends_as_a_draw_before_an_unbounded_object_explosion() {
    let mut engine = test_engine(2);
    engine.state.players[0].battlefield = (0..33)
        .map(|card_index| {
            let id = format!("permanent-{card_index}");
            test_instance(&id, test_definition(&id, "Artifact"), "player-0")
        })
        .collect();
    let stack_object = StackObject {
        id: "stack:doppelgang-limit".to_string(),
        controller: "player-0".to_string(),
        card: test_instance(
            "doppelgang-limit",
            test_definition("doppelgang-limit", "Sorcery"),
            "player-0",
        ),
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: None,
        ability_rule: None,
        decisions: BTreeMap::from([("xValue".to_string(), Value::from(33))]),
        targets: BTreeMap::new(),
    };

    engine
        .resolve_avatar_deck_spell_instruction(
            "doppelgang",
            &stack_object,
            &mut EmeritusDecisionProvider,
        )
        .expect("the simulation limit produces a game result, not an engine error");

    assert_eq!(engine.state.status, GameStatus::Completed);
    assert_eq!(
        engine.state.outcome.as_ref().map(|outcome| &outcome.reason),
        Some(&GameEndReason::SimulationLimit)
    );
    assert!(engine.state.events.iter().any(|event| {
        event.kind == "simulationLimitReached" && event.detail["requested"] == 1_089
    }));
}

fn mana_source(
    instance_id: &str,
    type_line: &str,
    symbols: &str,
    spend_restriction: Option<Value>,
) -> CardInstance {
    let mut definition = test_definition(instance_id, type_line);
    let mut effect = json!({
        "kind": "addMana",
        "player": {
            "kind": "controllerOf",
            "object": { "kind": "self" },
        },
        "mana": symbols,
    });
    if let Some(restriction) = spend_restriction {
        effect["spendRestriction"] = restriction;
    }
    definition.rules = vec![json!({
        "kind": "manaAbility",
        "source": { "kind": "self" },
        "costs": [{
            "kind": "tap",
            "object": { "kind": "self" },
        }],
        "effects": [effect],
    })];
    test_instance(instance_id, definition, "player-0")
}

