#[test]
fn enter_trigger_scry_three_inspects_the_top_three_cards() {
    let mut engine = test_engine(2);
    let mut signal_definition = test_definition("threefold-signal", "Artifact");
    signal_definition.rules = vec![json!({
        "kind": "triggeredAbility",
        "source": { "kind": "self" },
        "event": {
            "kind": "enterBattlefield",
            "object": { "kind": "self" },
        },
        "effects": [{
            "kind": "scry",
            "player": {
                "kind": "controllerOf",
                "object": { "kind": "self" },
            },
            "count": { "kind": "integer", "value": 3 },
        }],
    })];
    let signal = test_instance("threefold-signal", signal_definition, "player-0");
    engine.state.players[0].battlefield = vec![signal.clone()];
    engine.state.players[0].library = [
        "remaining-bottom",
        "remaining-top",
        "scry-third",
        "scry-second",
        "scry-first",
    ]
    .into_iter()
    .map(|id| test_instance(id, test_definition(id, "Sorcery"), "player-0"))
    .collect();

    engine.enqueue_enter_battlefield_triggers(&signal);
    assert_eq!(engine.state.stack.len(), 1);
    engine
        .resolve_top_stack(&mut EmeritusDecisionProvider)
        .expect("the scry trigger resolves");

    let library = engine.state.players[0]
        .library
        .iter()
        .map(|card| card.instance_id.as_str())
        .collect::<Vec<_>>();
    assert_eq!(library.len(), 5);
    assert_eq!(&library[3..], &["remaining-bottom", "remaining-top"]);
    assert_eq!(
        library[..3].iter().copied().collect::<BTreeSet<_>>(),
        BTreeSet::from(["scry-first", "scry-second", "scry-third"])
    );
    assert!(engine.state.events.iter().any(|event| {
        event.kind == "scried"
            && event.card_instance_id.as_deref() == Some("threefold-signal")
            && event.detail["count"] == 3
            && event.detail["moved"] == 3
    }));
}

#[test]
fn connive_draws_discards_and_counters_for_any_canonical_source() {
    let mut engine = test_engine(2);
    let mut operative_definition = test_definition("test-operative", "Creature - Human Rogue");
    operative_definition.rules = vec![json!({
        "kind": "triggeredAbility",
        "source": { "kind": "self" },
        "event": { "kind": "enterBattlefield", "object": { "kind": "self" } },
        "effects": [{
            "kind": "connive",
            "permanent": { "kind": "self" },
            "player": { "kind": "controllerOf", "object": { "kind": "self" } },
        }],
    })];
    let operative = test_instance("test-operative", operative_definition, "player-0");
    engine.state.players[0].battlefield = vec![operative.clone()];
    engine.state.players[0].hand = vec![test_instance(
        "hand-spell",
        test_definition("hand-spell", "Instant"),
        "player-0",
    )];
    engine.state.players[0].library = vec![test_instance(
        "drawn-spell",
        test_definition("drawn-spell", "Sorcery"),
        "player-0",
    )];

    engine.enqueue_enter_battlefield_triggers(&operative);
    engine
        .resolve_top_stack(&mut EmeritusDecisionProvider)
        .expect("the generic connive trigger resolves");

    assert_eq!(engine.state.players[0].hand.len(), 1);
    assert_eq!(engine.state.players[0].graveyard.len(), 1);
    assert_eq!(
        engine.state.players[0].battlefield[0].counters.get("+1/+1"),
        Some(&1)
    );
    assert!(
        engine
            .state
            .events
            .iter()
            .any(|event| { event.kind == "cardDiscarded" && event.detail["reason"] == "connive" })
    );
}

#[test]
fn starfield_shepherd_moves_the_selected_library_card_to_hand() {
    let mut engine = test_engine(2);
    let mut shepherd_definition = test_definition("starfield-shepherd", "Creature - Angel");
    shepherd_definition.rules = vec![json!({
        "kind": "triggeredAbility",
        "source": { "kind": "self" },
        "event": { "kind": "enterBattlefield", "object": { "kind": "self" } },
        "effects": [
            {
                "kind": "chooseCards",
                "id": "cardsToFind",
                "player": { "kind": "controllerOf", "object": { "kind": "self" } },
                "candidates": {
                    "kind": "cards",
                    "zone": {
                        "kind": "library",
                        "player": { "kind": "controllerOf", "object": { "kind": "self" } },
                    },
                    "where": {
                        "kind": "or",
                        "operands": [
                            {
                                "kind": "and",
                                "operands": [
                                    { "kind": "cardTypeContains", "value": "Basic" },
                                    { "kind": "subtypeContains", "value": "Plains" },
                                ],
                            },
                            {
                                "kind": "and",
                                "operands": [
                                    { "kind": "cardTypeContains", "value": "Creature" },
                                    {
                                        "kind": "compare",
                                        "operator": "<=",
                                        "left": { "kind": "manaValueOf", "object": { "kind": "candidate" } },
                                        "right": { "kind": "integer", "value": 1 },
                                    },
                                ],
                            },
                        ],
                    },
                },
                "minimum": 0,
                "maximum": 1,
            },
            {
                "kind": "revealCards",
                "cards": { "kind": "decisionResult", "decisionId": "cardsToFind" },
            },
            {
                "kind": "moveCards",
                "cards": { "kind": "decisionResult", "decisionId": "cardsToFind" },
                "to": {
                    "kind": "hand",
                    "player": { "kind": "controllerOf", "object": { "kind": "self" } },
                },
            },
            {
                "kind": "shuffleZone",
                "zone": {
                    "kind": "library",
                    "player": { "kind": "controllerOf", "object": { "kind": "self" } },
                },
            },
        ],
    })];
    let shepherd = test_instance("starfield-shepherd", shepherd_definition, "player-0");
    let mut valid_creature = test_definition("one-drop", "Creature - Elf");
    valid_creature.mana_cost = "{W}".to_string();
    let mut invalid_creature = test_definition("three-drop", "Creature - Elf");
    invalid_creature.mana_cost = "{2}{W}".to_string();
    engine.state.players[0].battlefield = vec![shepherd.clone()];
    engine.state.players[0].library = vec![
        test_instance("three-drop", invalid_creature, "player-0"),
        test_instance("one-drop", valid_creature, "player-0"),
    ];

    engine.enqueue_enter_battlefield_triggers(&shepherd);
    engine
        .resolve_top_stack(&mut EmeritusDecisionProvider)
        .expect("Starfield Shepherd's search resolves");

    assert!(
        engine.state.players[0]
            .hand
            .iter()
            .any(|card| card.instance_id == "one-drop")
    );
    assert!(
        engine.state.players[0]
            .library
            .iter()
            .all(|card| card.instance_id != "one-drop")
    );
}

#[test]
fn opponent_library_cards_move_across_players_and_keep_linked_permissions() {
    let target_opponent = json!({ "kind": "chosenTarget", "id": "targetOpponent" });
    let controller = json!({ "kind": "controllerOf", "object": { "kind": "self" } });
    let target_declaration = json!({
        "kind": "castingDeclaration",
        "decisions": [{
            "id": "targetOpponent",
            "kind": "target",
            "minimum": 1,
            "maximum": 1,
            "candidates": {
                "kind": "players",
                "where": { "kind": "isOpponentOf", "player": controller.clone() },
            },
        }],
    });

    let mut acquire_engine = test_engine(2);
    let mut acquire_definition = test_definition("generic-acquire", "Creature - Wizard");
    acquire_definition.rules = vec![json!({
        "kind": "triggeredAbility",
        "source": { "kind": "self" },
        "event": { "kind": "enterBattlefield", "object": { "kind": "self" } },
        "declaration": target_declaration.clone(),
        "effects": [
            {
                "kind": "chooseCards",
                "id": "searchedOpponentCard",
                "player": controller.clone(),
                "minimum": 0,
                "maximum": 1,
                "candidates": {
                    "kind": "cards",
                    "zone": { "kind": "library", "player": target_opponent.clone() },
                    "where": { "kind": "cardTypeContains", "value": "Artifact" },
                },
            },
            {
                "kind": "moveCards",
                "cards": { "kind": "decisionResult", "decisionId": "searchedOpponentCard" },
                "to": { "kind": "battlefield", "player": controller.clone(), "tapped": false },
            },
        ],
    })];
    let acquire = test_instance("generic-acquire", acquire_definition, "player-0");
    let stolen_artifact = test_instance(
        "stolen-artifact",
        test_definition("stolen-artifact", "Artifact"),
        "player-1",
    );
    acquire_engine.state.players[0].battlefield = vec![acquire.clone()];
    acquire_engine.state.players[1].library = vec![stolen_artifact];
    acquire_engine.state.stack.push(StackObject {
        id: "stack:generic-acquire".to_string(),
        controller: "player-0".to_string(),
        card: acquire.clone(),
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: Some("triggeredAbility".to_string()),
        ability_rule: acquire.definition.rules.first().cloned(),
        decisions: BTreeMap::new(),
        targets: BTreeMap::from([(
            "targetOpponent".to_string(),
            TargetRef::Player {
                player_id: "player-1".to_string(),
            },
        )]),
    });
    acquire_engine
        .resolve_top_stack(&mut EmeritusDecisionProvider)
        .expect("the cross-player battlefield search resolves");
    let acquired = acquire_engine.state.players[0]
        .battlefield
        .iter()
        .find(|card| card.instance_id == "stolen-artifact")
        .expect("the selected opponent card moved to the controller's battlefield");
    assert_eq!(acquired.owner, "player-1");
    assert_eq!(acquired.controller, "player-0");
    assert!(acquire_engine.state.players[1].library.is_empty());

    let mut grasp_engine = test_engine(2);
    let mut grasp_definition = test_definition("generic-grasp", "Creature - Wizard");
    grasp_definition.rules = vec![json!({
        "kind": "triggeredAbility",
        "source": { "kind": "self" },
        "event": { "kind": "enterBattlefield", "object": { "kind": "self" } },
        "declaration": target_declaration,
        "effects": [
            {
                "kind": "chooseCards",
                "id": "searchedOpponentCard",
                "player": controller.clone(),
                "minimum": 0,
                "maximum": 1,
                "candidates": {
                    "kind": "cards",
                    "zone": { "kind": "library", "player": target_opponent },
                    "where": null,
                },
            },
            {
                "kind": "moveCards",
                "cards": { "kind": "decisionResult", "decisionId": "searchedOpponentCard" },
                "to": { "kind": "exile", "player": { "kind": "chosenTarget", "id": "targetOpponent" }, "faceDown": true },
            },
            {
                "kind": "grantCardPermission",
                "player": controller,
                "cards": { "kind": "decisionResult", "decisionId": "searchedOpponentCard" },
                "permissions": ["lookAt", "play"],
                "play": {
                    "normalTimingApplies": true,
                    "normalCostsApply": true,
                    "castingModifier": { "kind": "none" },
                },
                "duration": { "kind": "whileObjectsRemainInZone", "zone": { "kind": "exile" } },
            },
        ],
    })];
    let grasp = test_instance("generic-grasp", grasp_definition, "player-0");
    grasp_engine.state.players[0].battlefield = vec![grasp.clone()];
    grasp_engine.state.players[1].library = vec![test_instance(
        "grasped-card",
        test_definition("grasped-card", "Sorcery"),
        "player-1",
    )];
    grasp_engine.state.stack.push(StackObject {
        id: "stack:generic-grasp".to_string(),
        controller: "player-0".to_string(),
        card: grasp.clone(),
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: Some("triggeredAbility".to_string()),
        ability_rule: grasp.definition.rules.first().cloned(),
        decisions: BTreeMap::new(),
        targets: BTreeMap::from([(
            "targetOpponent".to_string(),
            TargetRef::Player {
                player_id: "player-1".to_string(),
            },
        )]),
    });
    grasp_engine
        .resolve_top_stack(&mut EmeritusDecisionProvider)
        .expect("the linked face-down exile search resolves");
    assert_eq!(grasp_engine.state.players[1].exile.len(), 1);
    assert_eq!(
        grasp_engine.state.players[1].exile[0].flags.get("faceDown"),
        Some(&true)
    );
    assert!(grasp_engine.state.permissions.iter().any(|permission| {
        permission["cardInstanceId"] == "grasped-card"
            && permission["playerId"] == "player-0"
            && permission["normalCostsApply"] == true
            && permission["spendManaAsAnyType"] == false
    }));
}

#[test]
fn card_choice_uses_the_player_named_by_the_candidate_zone() {
    struct TargetHandProvider {
        choice_was_presented: bool,
    }

    impl DecisionProvider for TargetHandProvider {
        fn choose(
            &mut self,
            _state: &GameState,
            _request: &EngineDecisionRequest,
        ) -> Result<usize, EngineError> {
            Err(EngineError::new(
                "target-hand selection should use the direct card choice",
            ))
        }

        fn choose_card_instance_ids(
            &mut self,
            state: &GameState,
            request: &EngineDecisionRequest,
        ) -> Result<Vec<String>, EngineError> {
            self.choice_was_presented = true;
            assert!(state.rule_modifiers.iter().any(|modifier| {
                modifier["kind"] == "revealedHand" && modifier["playerId"] == "player-1"
            }));
            let Some(DecisionChoice::CardSelection {
                candidate_card_instance_ids,
                minimum,
                maximum,
                ..
            }) = request.choice.as_ref()
            else {
                return Err(EngineError::new("expected a target-hand card choice"));
            };
            assert_eq!((*minimum, *maximum), (1, 1));
            assert_eq!(
                candidate_card_instance_ids,
                &vec!["target-nonland".to_string()]
            );
            Ok(vec!["target-nonland".to_string()])
        }
    }

    let mut engine = test_engine(2);
    engine.state.players[0].hand = vec![test_instance(
        "chooser-nonland",
        test_definition("chooser-nonland", "Instant"),
        "player-0",
    )];
    engine.state.players[1].hand = vec![
        test_instance(
            "target-land",
            test_definition("target-land", "Land"),
            "player-1",
        ),
        test_instance(
            "target-nonland",
            test_definition("target-nonland", "Sorcery"),
            "player-1",
        ),
    ];
    engine.state.stack.push(StackObject {
        id: "stack:target-hand-choice".to_string(),
        controller: "player-0".to_string(),
        card: test_instance(
            "target-hand-source",
            test_definition("target-hand-source", "Sorcery"),
            "player-0",
        ),
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: Some("activatedAbility".to_string()),
        ability_rule: Some(json!({
            "kind": "spellAbility",
            "source": { "kind": "self" },
            "effects": [
                {
                    "kind": "revealHand",
                    "player": { "kind": "chosenTarget", "id": "targetPlayer" },
                    "duration": { "kind": "untilEndOfCurrentTurn" },
                },
                {
                    "kind": "chooseCards",
                    "id": "discardedCard",
                    "player": { "kind": "abilityController" },
                    "minimum": { "kind": "integer", "value": 1 },
                    "maximum": { "kind": "integer", "value": 1 },
                    "candidates": {
                        "kind": "cards",
                        "zone": {
                            "kind": "hand",
                            "player": { "kind": "chosenTarget", "id": "targetPlayer" },
                        },
                        "where": {
                            "kind": "not",
                            "operand": { "kind": "cardTypeContains", "value": "Land" },
                        },
                    },
                },
                {
                    "kind": "moveCards",
                    "cards": { "kind": "decisionResult", "decisionId": "discardedCard" },
                    "to": {
                        "kind": "graveyard",
                        "player": { "kind": "chosenTarget", "id": "targetPlayer" },
                    },
                },
            ],
        })),
        decisions: BTreeMap::new(),
        targets: BTreeMap::from([(
            "targetPlayer".to_string(),
            TargetRef::Player {
                player_id: "player-1".to_string(),
            },
        )]),
    });

    let mut provider = TargetHandProvider {
        choice_was_presented: false,
    };
    engine
        .resolve_top_stack(&mut provider)
        .expect("the targeted hand choice resolves");

    assert!(
        provider.choice_was_presented,
        "choosing from another player's hand must remain explicit even for one legal card"
    );

    assert_eq!(
        engine.state.players[0].hand[0].instance_id,
        "chooser-nonland"
    );
    assert_eq!(engine.state.players[1].hand[0].instance_id, "target-land");
    assert!(
        engine.state.players[1]
            .graveyard
            .iter()
            .any(|card| card.instance_id == "target-nonland")
    );
}

#[test]
fn greatest_hand_wheel_uses_the_pre_discard_maximum_for_every_player() {
    let mut engine = test_engine(2);
    let source = test_instance(
        "generic-wheel",
        test_definition("generic-wheel", "Sorcery"),
        "player-0",
    );
    engine.state.players[0].hand = ["p0-a", "p0-b"]
        .into_iter()
        .map(|id| test_instance(id, test_definition(id, "Instant"), "player-0"))
        .collect();
    engine.state.players[1].hand = ["p1-a", "p1-b", "p1-c", "p1-d"]
        .into_iter()
        .map(|id| test_instance(id, test_definition(id, "Instant"), "player-1"))
        .collect();
    for player_index in 0..2 {
        let owner = format!("player-{player_index}");
        engine.state.players[player_index].library = (0..6)
            .map(|index| {
                let id = format!("{owner}:draw:{index}");
                test_instance(&id, test_definition(&id, "Land"), &owner)
            })
            .collect();
    }
    engine.state.stack.push(StackObject {
        id: "stack:generic-wheel".to_string(),
        controller: "player-0".to_string(),
        card: source,
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: Some("activatedAbility".to_string()),
        ability_rule: Some(json!({
            "kind": "spellAbility",
            "source": { "kind": "self" },
            "effects": [{
                "kind": "discardHandThenDrawEachPlayer",
                "count": { "kind": "greatestHandSize" },
            }],
        })),
        decisions: BTreeMap::new(),
        targets: BTreeMap::new(),
    });

    engine
        .resolve_top_stack(&mut EmeritusDecisionProvider)
        .expect("the greatest-hand wheel resolves");

    assert_eq!(engine.state.players[0].hand.len(), 4);
    assert_eq!(engine.state.players[1].hand.len(), 4);
    assert_eq!(engine.state.players[0].graveyard.len(), 2);
    assert_eq!(engine.state.players[1].graveyard.len(), 4);
}

#[test]
fn protection_quality_prevents_matching_targets_damage_and_blockers() {
    let mut engine = test_engine(2);
    let mut protected_definition = test_definition("protected-angel", "Creature - Angel");
    protected_definition.rules = vec![json!({
        "kind": "staticAbility",
        "source": { "kind": "self" },
        "activeWhile": {
            "kind": "inZone",
            "object": { "kind": "self" },
            "zone": { "kind": "battlefield" },
        },
        "modifiers": [
            { "kind": "grantKeyword", "objects": { "kind": "self" }, "keyword": "flying" },
            { "kind": "grantProtection", "objects": { "kind": "self" }, "from": ["black"] },
        ],
    })];
    let protected = test_instance("protected-angel", protected_definition, "player-0");
    engine.state.players[0].battlefield = vec![protected.clone()];

    let targeted_rule = json!({
        "kind": "spellAbility",
        "source": { "kind": "self" },
        "declaration": {
            "kind": "castingDeclaration",
            "decisions": [{
                "id": "targetCreature",
                "kind": "chooseTargets",
                "minimum": 1,
                "maximum": 1,
                "candidates": {
                    "kind": "permanents",
                    "where": { "kind": "cardTypeContains", "value": "Creature" },
                },
            }],
        },
        "effects": [{
            "kind": "destroyPermanent",
            "permanent": { "kind": "chosenTarget", "id": "targetCreature" },
        }],
    });
    let mut black_spell = test_definition("black-spell", "Instant");
    black_spell.mana_cost = "{B}".to_string();
    black_spell.rules = vec![targeted_rule.clone()];
    assert!(
        engine
            .declarations_for_card(&black_spell, "player-1")
            .expect("black spell declarations evaluate")
            .is_empty()
    );
    let mut red_spell = test_definition("red-spell", "Instant");
    red_spell.mana_cost = "{R}".to_string();
    red_spell.rules = vec![targeted_rule];
    assert_eq!(
        engine
            .declarations_for_card(&red_spell, "player-1")
            .expect("red spell declarations evaluate")
            .len(),
        1
    );

    let mut black_creature_definition = test_definition("black-source", "Creature - Zombie");
    black_creature_definition.mana_cost = "{B}".to_string();
    black_creature_definition.rules = vec![json!({ "kind": "flying" })];
    let black_source = test_instance("black-source", black_creature_definition, "player-1");
    let mut red_creature_definition = test_definition("red-source", "Creature - Goblin");
    red_creature_definition.mana_cost = "{R}".to_string();
    red_creature_definition.rules = vec![json!({ "kind": "flying" })];
    let red_source = test_instance("red-source", red_creature_definition, "player-1");
    engine.state.players[1].battlefield = vec![black_source.clone(), red_source.clone()];

    assert!(!engine.can_block(&black_source, &protected));
    assert!(engine.can_block(&red_source, &protected));
    engine
        .deal_damage(
            TargetRef::Permanent {
                instance_id: protected.instance_id.clone(),
            },
            3,
            &black_source.instance_id,
        )
        .expect("protected damage resolves as prevention");
    assert_eq!(engine.state.players[0].battlefield[0].damage_marked, 0);
}

#[test]
fn generic_control_blink_and_each_player_sacrifice_mutate_the_right_zones() {
    let mut control_engine = test_engine(2);
    let target = test_instance(
        "stolen-permanent",
        test_definition("stolen-permanent", "Artifact"),
        "player-0",
    );
    let source = test_instance(
        "control-source",
        test_definition("control-source", "Creature"),
        "player-1",
    );
    control_engine.state.players[0].battlefield = vec![target.clone()];
    control_engine.state.players[1].battlefield = vec![source.clone()];
    control_engine.state.stack.push(StackObject {
        id: "gain-control".to_string(),
        controller: "player-1".to_string(),
        card: source.clone(),
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: Some("triggeredAbility".to_string()),
        ability_rule: Some(json!({
            "kind": "triggeredAbility",
            "source": { "kind": "self" },
            "event": { "kind": "enterBattlefield", "object": { "kind": "self" } },
            "effects": [{
                "kind": "gainControlPermanent",
                "permanent": { "kind": "chosenTarget", "id": "targetPermanent" },
                "controller": { "kind": "controllerOf", "object": { "kind": "self" } },
            }],
        })),
        decisions: BTreeMap::new(),
        targets: BTreeMap::from([(
            "targetPermanent".to_string(),
            TargetRef::Permanent {
                instance_id: target.instance_id.clone(),
            },
        )]),
    });
    control_engine
        .resolve_top_stack(&mut EmeritusDecisionProvider)
        .expect("indefinite control resolves");
    assert!(control_engine.state.players[0].battlefield.is_empty());
    assert!(
        control_engine.state.players[1]
            .battlefield
            .iter()
            .any(|card| card.instance_id == target.instance_id
                && card.controller == "player-1"
                && card.owner == "player-0")
    );
    assert_eq!(
        control_engine.numeric_expression(
            &json!({
                "kind": "countPermanents",
                "where": Value::Null,
                "ownership": "notOwned",
            }),
            "player-1",
        ),
        Some(1)
    );

    let blink_target = test_instance(
        "blink-target",
        test_definition("blink-target", "Creature"),
        "player-0",
    );
    control_engine.state.players[0].battlefield = vec![blink_target.clone()];
    control_engine.state.stack.push(StackObject {
        id: "blink-control".to_string(),
        controller: "player-1".to_string(),
        card: source,
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: Some("triggeredAbility".to_string()),
        ability_rule: Some(json!({
            "kind": "triggeredAbility",
            "source": { "kind": "self" },
            "event": { "kind": "enterBattlefield", "object": { "kind": "self" } },
            "effects": [{
                "kind": "blinkPermanent",
                "permanent": { "kind": "chosenTarget", "id": "targetPermanent" },
                "controller": { "kind": "controllerOf", "object": { "kind": "self" } },
            }],
        })),
        decisions: BTreeMap::new(),
        targets: BTreeMap::from([(
            "targetPermanent".to_string(),
            TargetRef::Permanent {
                instance_id: blink_target.instance_id.clone(),
            },
        )]),
    });
    control_engine
        .resolve_top_stack(&mut EmeritusDecisionProvider)
        .expect("blink under the ability controller resolves");
    assert!(
        control_engine.state.players[1]
            .battlefield
            .iter()
            .any(|card| card.instance_id == blink_target.instance_id
                && card.controller == "player-1"
                && card.owner == "player-0")
    );

    let mut sacrifice_engine = test_engine(2);
    let sacrifice_source = test_instance(
        "sacrifice-source",
        test_definition("sacrifice-source", "Creature"),
        "player-0",
    );
    sacrifice_engine.state.players[0].battlefield = vec![sacrifice_source.clone()];
    sacrifice_engine.state.players[1].battlefield = vec![test_instance(
        "opponent-creature",
        test_definition("opponent-creature", "Creature"),
        "player-1",
    )];
    sacrifice_engine.state.stack.push(StackObject {
        id: "each-sacrifice".to_string(),
        controller: "player-0".to_string(),
        card: sacrifice_source,
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: Some("triggeredAbility".to_string()),
        ability_rule: Some(json!({
            "kind": "triggeredAbility",
            "source": { "kind": "self" },
            "event": { "kind": "enterBattlefield", "object": { "kind": "self" } },
            "effects": [{
                "kind": "sacrificePermanentsEachPlayer",
                "scope": "allPlayers",
                "controller": { "kind": "controllerOf", "object": { "kind": "self" } },
                "where": { "kind": "cardTypeContains", "value": "Creature" },
                "count": { "kind": "integer", "value": 1 },
            }],
        })),
        decisions: BTreeMap::new(),
        targets: BTreeMap::new(),
    });
    sacrifice_engine
        .resolve_top_stack(&mut EmeritusDecisionProvider)
        .expect("each player sacrifice resolves");
    assert!(
        sacrifice_engine
            .state
            .players
            .iter()
            .all(|player| player.battlefield.is_empty() && player.graveyard.len() == 1)
    );
}

#[test]
fn repeated_mass_blink_reuses_the_selected_permanents_each_iteration() {
    let mut engine = test_engine(2);
    let first = test_instance(
        "mass-blink-first",
        test_definition("mass-blink-first", "Creature"),
        "player-0",
    );
    let second = test_instance(
        "mass-blink-second",
        test_definition("mass-blink-second", "Artifact Creature"),
        "player-0",
    );
    engine.state.players[0]
        .battlefield
        .extend([first.clone(), second.clone()]);
    let stack_object = StackObject {
        id: "stack:mass-blink".to_string(),
        controller: "player-0".to_string(),
        card: test_instance(
            "mass-blink-source",
            test_definition("mass-blink-source", "Sorcery"),
            "player-0",
        ),
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: Some("spellAbility".to_string()),
        ability_rule: None,
        decisions: BTreeMap::new(),
        targets: BTreeMap::new(),
    };
    let mut decisions = BTreeMap::from([(
        "blinkPermanents".to_string(),
        json!([first.instance_id, second.instance_id]),
    )]);

    engine
        .execute_effect(
            &json!({
                "kind": "blinkPermanents",
                "objects": {
                    "kind": "decisionResult",
                    "decisionId": "blinkPermanents",
                },
                "repeat": { "kind": "integer", "value": 2 },
            }),
            None,
            &stack_object,
            &mut BTreeMap::new(),
            &mut decisions,
            &mut EmeritusDecisionProvider,
        )
        .expect("each selected permanent blinks twice");

    assert_eq!(engine.state.players[0].battlefield.len(), 2);
    assert!(engine.state.players[0].exile.is_empty());
    assert_eq!(
        engine
            .state
            .events
            .iter()
            .filter(|event| event.kind == "permanentBlinked")
            .count(),
        4
    );
}

#[test]
fn echo_is_due_after_entry_then_is_paid_or_sacrificed_only_once() {
    let echo_rule = json!({
        "kind": "triggeredAbility",
        "source": { "kind": "self" },
        "event": {
            "kind": "stepBegan",
            "step": "upkeep",
            "player": { "kind": "controllerOf", "object": { "kind": "self" } },
        },
        "condition": { "kind": "sourceNeedsEcho" },
        "effects": [{ "kind": "payManaOrSacrificeSource", "manaCost": "{W}" }],
    });

    let mut paid_engine = test_engine(2);
    let mut paid_definition = test_definition("paid-echo", "Creature - Spirit");
    paid_definition.rules = vec![echo_rule.clone()];
    let mut paid_echo = test_instance("paid-echo", paid_definition, "player-0");
    paid_engine
        .apply_enter_replacements(&mut paid_echo, &mut EmeritusDecisionProvider)
        .expect("echo entry state is installed");
    paid_engine.state.players[0].battlefield.push(paid_echo);
    paid_engine.state.players[0].mana_pool.push(FloatingMana {
        symbol: "W".to_string(),
        spend_restriction: None,
    });
    paid_engine.enqueue_step_triggers("upkeep");
    assert_eq!(paid_engine.state.stack.len(), 1);
    paid_engine
        .resolve_top_stack(&mut EmeritusDecisionProvider)
        .expect("echo payment resolves");
    assert!(paid_engine.permanent_position("paid-echo").is_some());
    assert!(paid_engine.state.players[0].mana_pool.is_empty());
    paid_engine.enqueue_step_triggers("upkeep");
    assert!(paid_engine.state.stack.is_empty());

    let mut declined_engine = test_engine(2);
    let mut declined_definition = test_definition("declined-echo", "Creature - Spirit");
    declined_definition.rules = vec![echo_rule];
    let mut declined_echo = test_instance("declined-echo", declined_definition, "player-0");
    declined_engine
        .apply_enter_replacements(&mut declined_echo, &mut EmeritusDecisionProvider)
        .expect("echo entry state is installed");
    declined_engine.state.players[0]
        .battlefield
        .push(declined_echo);
    declined_engine.enqueue_step_triggers("upkeep");
    declined_engine
        .resolve_top_stack(&mut EmeritusDecisionProvider)
        .expect("declined echo resolves");
    assert!(
        declined_engine
            .permanent_position("declined-echo")
            .is_none()
    );
    assert!(
        declined_engine.state.players[0]
            .graveyard
            .iter()
            .any(|card| card.instance_id == "declined-echo")
    );
}

#[test]
fn yenna_aura_copy_uses_composed_untap_and_scry_effects() {
    let mut engine = test_engine(2);
    let mut yenna = test_instance(
        "yenna",
        test_definition("yenna", "Legendary Creature - Elf Druid"),
        "player-0",
    );
    yenna.tapped = true;
    let mut aura_definition = test_definition("rancor", "Enchantment - Aura");
    aura_definition.rules = vec![json!({
        "kind": "keywordAbility",
        "source": { "kind": "self" },
        "ability": {
            "kind": "enchant",
            "where": { "kind": "cardTypeContains", "value": "Creature" },
        },
    })];
    let mut aura = test_instance("rancor", aura_definition, "player-0");
    aura.attached_to = Some("aura-bearer".to_string());
    let bearer = test_instance(
        "aura-bearer",
        test_definition("aura-bearer", "Creature - Human"),
        "player-0",
    );
    engine.state.players[0].battlefield = vec![yenna.clone(), bearer, aura];
    engine.state.players[0].library = ["scry-one", "scry-two"]
        .into_iter()
        .map(|id| test_instance(id, test_definition(id, "Sorcery"), "player-0"))
        .collect();
    engine.state.stack.push(StackObject {
        id: "stack:yenna".to_string(),
        controller: "player-0".to_string(),
        card: yenna,
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: Some("activatedAbility".to_string()),
        ability_rule: Some(json!({
            "kind": "activatedAbility",
            "source": { "kind": "self" },
            "effects": [
                {
                    "kind": "createModifiedTokenCopy",
                    "object": { "kind": "chosenTarget", "id": "targetEnchantment" },
                    "removeLegendary": true,
                },
                {
                    "kind": "conditionalEffect",
                    "condition": {
                        "kind": "objectMatchesFilter",
                        "object": { "kind": "chosenTarget", "id": "targetEnchantment" },
                        "where": { "kind": "subtypeContains", "value": "Aura" },
                    },
                    "then": [
                        {
                            "kind": "untapPermanent",
                            "permanent": { "kind": "self" },
                        },
                        {
                            "kind": "scry",
                            "player": {
                                "kind": "controllerOf",
                                "object": { "kind": "self" },
                            },
                            "count": { "kind": "integer", "value": 2 },
                        },
                    ],
                    "else": [],
                },
            ],
        })),
        decisions: BTreeMap::new(),
        targets: BTreeMap::from([(
            "targetEnchantment".to_string(),
            TargetRef::Permanent {
                instance_id: "rancor".to_string(),
            },
        )]),
    });

    engine
        .resolve_top_stack(&mut EmeritusDecisionProvider)
        .expect("Yenna's Aura-copy ability resolves");

    assert!(!engine.state.players[0].battlefield[0].tapped);
    assert!(engine.state.players[0].battlefield.iter().any(|card| {
        card.definition.is_token && card.definition.name == "rancor" && card.attached_to.is_some()
    }));
    assert!(engine.state.events.iter().any(|event| {
        event.kind == "scried"
            && event.card_instance_id.as_deref() == Some("yenna")
            && event.detail["count"] == 2
    }));
}

#[test]
fn commander_starts_in_command_zone_and_accumulates_cast_tax() {
    let mut engine = test_commander_engine();
    engine.state.step = GameStep::PrecombatMain;
    engine.state.players[0].land_plays_remaining = 1;

    assert_eq!(engine.state.players[0].command_zone.len(), 1);
    assert_eq!(engine.state.commanders[0].casts_from_command_zone, 0);
    assert!(
        engine.state.players[0]
            .library
            .iter()
            .chain(&engine.state.players[0].hand)
            .all(|card| card.definition.name != "Test Commander")
    );

    let first_cast = engine
        .legal_priority_actions(0)
        .into_iter()
        .find(|action| {
            action.kind == ActionKind::CastSpell
                && action.decisions["castSourceZone"] == "commandZone"
        })
        .expect("the commander can be cast from the command zone without tax");
    engine
        .apply_priority_action(&first_cast, &mut EmeritusDecisionProvider)
        .expect("the first commander cast succeeds");
    assert_eq!(engine.state.commanders[0].casts_from_command_zone, 1);

    let commander = engine
        .state
        .stack
        .pop()
        .expect("commander is on the stack")
        .card;
    engine.state.players[0].command_zone.push(commander);
    engine.commander_last_zones.insert(
        engine.state.commanders[0].card_instance_id.clone(),
        "commandZone".to_string(),
    );
    engine.state.players[0].battlefield = vec![
        test_instance(
            "tax-plains-1",
            test_definition("tax-plains-1", "Basic Land - Plains"),
            "player-0",
        ),
        test_instance(
            "tax-plains-2",
            test_definition("tax-plains-2", "Basic Land - Plains"),
            "player-0",
        ),
    ];

    let taxed_cast = engine
        .legal_priority_actions(0)
        .into_iter()
        .find(|action| {
            action.kind == ActionKind::CastSpell
                && action.decisions["castSourceZone"] == "commandZone"
        })
        .expect("two generic mana make the taxed commander cast legal");
    assert_eq!(taxed_cast.payment_sources.len(), 2);
    assert!(taxed_cast.label.contains("commander tax {2}"));
}

#[test]
fn black_phyrexian_mana_prefers_black_mana_and_falls_back_to_two_life() {
    let requirement =
        parse_mana_requirement("{W}{U}{B/P}{R}{G}").expect("the Phyrexian mana cost parses");

    assert_eq!(
        phyrexian_life_payment(
            &["W", "U", "R", "G"].map(|symbol| (symbol.to_string(), false)),
            &requirement,
            40,
        ),
        Some(2)
    );
    assert_eq!(
        phyrexian_life_payment(
            &["W", "U", "B", "R", "G"].map(|symbol| (symbol.to_string(), false)),
            &requirement,
            40,
        ),
        Some(0)
    );
}

#[test]
fn snow_cost_requires_mana_produced_by_a_snow_source() {
    let requirement =
        parse_mana_requirement("{1}{S}").expect("the snow mana cost parses generically");
    assert_eq!(requirement.snow, 1);
    assert_eq!(requirement.generic, 1);
    assert_eq!(
        phyrexian_life_payment(
            &[("G".to_string(), false), ("C".to_string(), false)],
            &requirement,
            20,
        ),
        None
    );
    assert_eq!(
        phyrexian_life_payment(
            &[("G".to_string(), false), ("C".to_string(), true)],
            &requirement,
            20,
        ),
        Some(0)
    );
}

#[test]
fn omnath_can_pay_black_phyrexian_mana_with_two_life_from_the_command_zone() {
    let mut engine = test_commander_engine();
    engine.state.step = GameStep::PrecombatMain;
    engine.state.active_player = 0;
    let commander = engine.state.players[0]
        .command_zone
        .first_mut()
        .expect("the commander starts in the command zone");
    commander.definition.name = "Omnath, Locus of All".to_string();
    commander.definition.mana_cost = "{W}{U}{B/P}{R}{G}".to_string();
    assert_eq!(
        card_color_symbols(&commander.definition),
        BTreeSet::from([
            "W".to_string(),
            "U".to_string(),
            "B".to_string(),
            "R".to_string(),
            "G".to_string(),
        ])
    );
    engine.state.players[0].battlefield = vec![
        commander_color_mana_source("command-tower", "Land"),
        commander_color_mana_source("arcane-signet", "Artifact"),
        test_instance(
            "forest",
            test_definition("forest", "Basic Land - Forest"),
            "player-0",
        ),
        test_instance(
            "island",
            test_definition("island", "Basic Land - Island"),
            "player-0",
        ),
    ];

    let cast = engine
        .legal_priority_actions(0)
        .into_iter()
        .find(|action| {
            action.kind == ActionKind::CastSpell
                && action.card_instance_id.as_deref()
                    == engine.state.commanders[0].card_instance_id.as_str().into()
        })
        .expect("four colored sources and two life make Omnath castable");
    assert_eq!(cast.payment_sources.len(), 4);
    assert!(
        cast.decisions["manaPayment"]
            .as_array()
            .is_some_and(|payments| {
                payments.iter().any(|payment| {
                    value_kind(payment) == Some("phyrexianManaPayment") && payment["lifePaid"] == 2
                })
            }),
        "unexpected Omnath payment: {cast:?}"
    );

    engine
        .apply_priority_action(&cast, &mut EmeritusDecisionProvider)
        .expect("Omnath is cast after paying two life for black Phyrexian mana");

    assert_eq!(engine.state.players[0].life, 38);
    assert!(
        engine.state.players[0]
            .battlefield
            .iter()
            .all(|permanent| permanent.tapped)
    );
    assert_eq!(engine.state.stack.len(), 1);
    assert_eq!(
        engine.state.stack[0].card.definition.name,
        "Omnath, Locus of All"
    );
    assert!(engine.state.events.iter().any(|event| {
        event.kind == "lifePaid"
            && event.card_instance_id.as_deref()
                == Some(engine.state.commanders[0].card_instance_id.as_str())
            && event.detail["amount"] == 2
            && event.detail["reason"] == "phyrexianMana"
    }));
}

#[test]
fn commander_owner_can_move_it_back_to_command_zone() {
    let mut engine = test_commander_engine();
    let commander = engine.state.players[0]
        .command_zone
        .pop()
        .expect("commander starts in its command zone");
    let commander_id = commander.instance_id.clone();
    engine.state.players[0].graveyard.push(commander);

    engine
        .resolve_commander_zone_choices(&mut EmeritusDecisionProvider)
        .expect("commander zone choice resolves");

    assert!(
        engine.state.players[0]
            .command_zone
            .iter()
            .any(|card| card.instance_id == commander_id)
    );
    assert!(
        engine.state.players[0]
            .graveyard
            .iter()
            .all(|card| card.instance_id != commander_id)
    );
}

#[test]
fn twenty_one_combat_damage_from_one_commander_eliminates_a_player() {
    let mut engine = test_commander_engine();
    let mut commander = engine.state.players[0]
        .command_zone
        .pop()
        .expect("commander starts in its command zone");
    commander.definition.power = Some("21".to_string());
    commander.definition.toughness = Some("21".to_string());
    let commander_id = commander.instance_id.clone();
    engine.state.players[0].battlefield.push(commander);
    let attacks = BTreeMap::from([(
        commander_id.clone(),
        AttackAssignment {
            defender: TargetRef::Player {
                player_id: "player-1".to_string(),
            },
            defending_player_id: "player-1".to_string(),
        },
    )]);

    engine
        .resolve_combat_damage(&attacks, &BTreeMap::new(), &BTreeMap::new())
        .expect("commander combat damage resolves");

    assert_eq!(engine.state.players[1].life, 19);
    assert_eq!(engine.state.players[1].commander_damage[0].amount, 21);
    assert_eq!(
        engine.state.outcome.as_ref().map(|outcome| &outcome.reason),
        Some(&GameEndReason::CommanderDamage)
    );
}

