#[test]
fn reflecting_pool_derives_unique_types_without_recursive_bootstrap() {
    let mut engine = test_engine(2);
    engine.state.players[0].battlefield =
        vec![reflecting_pool("pool-a"), reflecting_pool("pool-b")];
    let pool = engine.state.players[0].battlefield[0].clone();
    assert!(
        engine
            .mana_choices_for_permanent(&pool, None, true, true)
            .is_empty(),
        "Reflecting Pools alone cannot bootstrap a mana type"
    );

    engine.state.players[0].battlefield.extend([
        mana_source("island", "Basic Land - Island", "{U}", None),
        mana_source("wastes", "Basic Land - Wastes", "{C}", None),
    ]);
    let choices = engine
        .mana_choices_for_permanent(&pool, None, true, true)
        .into_iter()
        .map(|choice| choice.symbols)
        .collect::<Vec<_>>();

    assert_eq!(choices, vec![vec!["U".to_string()], vec!["C".to_string()]]);
    let second_pool = engine.state.players[0].battlefield[1].clone();
    assert_eq!(
        engine
            .mana_choices_for_permanent(&second_pool, None, true, true)
            .into_iter()
            .map(|choice| choice.symbols)
            .collect::<Vec<_>>(),
        choices
    );
}

#[test]
fn enchanted_land_mana_triggers_are_folded_into_the_mana_action() {
    let mut engine = test_engine(2);
    let land = mana_source("forest", "Land", "{G}", None);
    let mut aura_definition = test_definition("fertile-ground", "Enchantment - Aura");
    aura_definition.rules = vec![json!({
        "kind": "triggeredAbility",
        "source": { "kind": "self" },
        "event": {
            "kind": "attachedPermanentManaAbilityActivated",
            "object": { "kind": "self" },
        },
        "effects": [{
            "kind": "addMana",
            "player": {
                "kind": "controllerOf",
                "object": { "kind": "triggeringPermanent" },
            },
            "mana": { "kind": "chooseColor", "amount": { "kind": "integer", "value": 1 } },
        }],
    })];
    let mut aura = test_instance("fertile-ground", aura_definition, "player-0");
    aura.attached_to = Some("forest".to_string());
    engine.state.players[0].battlefield = vec![land, aura];

    let choices = engine
        .mana_choices_for_permanent(&engine.state.players[0].battlefield[0], None, true, true)
        .into_iter()
        .map(|choice| choice.symbols)
        .collect::<Vec<_>>();
    assert_eq!(choices.len(), 5);
    assert!(
        choices
            .iter()
            .all(|symbols| symbols.len() == 2 && symbols[0] == "G")
    );
    assert!(
        choices
            .iter()
            .any(|symbols| symbols == &vec!["G".to_string(), "W".to_string()])
    );

    let action = engine
        .legal_priority_actions(0)
        .into_iter()
        .find(|action| {
            action.card_instance_id.as_deref() == Some("forest")
                && action.decisions["manaProduced"] == json!(["G", "U"])
        })
        .expect("the combined green-blue mana action is legal");
    engine
        .apply_priority_action(&action, &mut RandomAi::seeded(1))
        .expect("the enchanted land mana action resolves");
    assert_eq!(
        engine.state.players[0]
            .mana_pool
            .iter()
            .map(|mana| mana.symbol.as_str())
            .collect::<Vec<_>>(),
        vec!["G", "U"]
    );
    assert!(engine.state.stack.is_empty());
}

#[test]
fn continuous_power_bonus_updates_topiary_lecturer_stats_and_mana() {
    let mut engine = test_engine(2);
    let mut lecturer_definition = test_definition("topiary-lecturer", "Creature - Elf Druid");
    lecturer_definition.power = Some("1".to_string());
    lecturer_definition.toughness = Some("2".to_string());
    lecturer_definition.rules = vec![json!({
        "kind": "manaAbility",
        "source": { "kind": "self" },
        "costs": [{ "kind": "tap", "object": { "kind": "self" } }],
        "effects": [{
            "kind": "addMana",
            "player": { "kind": "controllerOf", "object": { "kind": "self" } },
            "mana": {
                "kind": "fixedMana",
                "symbol": "G",
                "amount": { "kind": "powerOf", "object": { "kind": "self" } },
            },
        }],
    })];
    let lecturer = test_instance("topiary-lecturer", lecturer_definition, "player-0");

    let mut aura_definition = test_definition("plus-one-aura", "Enchantment - Aura");
    aura_definition.rules = vec![json!({
        "kind": "staticAbility",
        "source": { "kind": "self" },
        "activeWhile": {
            "kind": "inZone",
            "object": { "kind": "self" },
            "zone": { "kind": "battlefield" },
        },
        "modifiers": [{
            "kind": "modifyPowerToughness",
            "objects": { "kind": "attachedPermanent", "attachment": { "kind": "self" } },
            "power": { "kind": "integer", "value": 1 },
            "toughness": { "kind": "integer", "value": 1 },
        }],
    })];
    let mut aura = test_instance("plus-one-aura", aura_definition, "player-0");
    aura.attached_to = Some("topiary-lecturer".to_string());
    engine.state.players[0].battlefield = vec![lecturer, aura];

    let stats = GameEngine::effective_power_toughness(&engine.state);
    assert_eq!(stats["topiary-lecturer"].current_power, 2);
    assert_eq!(stats["topiary-lecturer"].current_toughness, 3);

    let lecturer = &engine.state.players[0].battlefield[0];
    let choices = engine.mana_choices_for_permanent(lecturer, None, true, true);
    assert!(choices.iter().any(|choice| choice.symbols == ["G", "G"]));
}

#[test]
fn exotic_orchard_requires_colors_from_opposing_lands_on_the_battlefield() {
    let mut engine = test_engine(3);
    engine.state.players[0].battlefield = vec![exotic_orchard("orchard")];

    assert!(
        engine
            .legal_priority_actions(0)
            .iter()
            .all(|action| action.card_instance_id.as_deref() != Some("orchard")),
        "Exotic Orchard cannot activate before an opposing land could produce a color"
    );

    let mut opposing_rock = mana_source("mana-rock", "Artifact", "{U}", None);
    opposing_rock.owner = "player-1".to_string();
    opposing_rock.controller = "player-1".to_string();
    engine.state.players[1].battlefield = vec![opposing_rock];
    assert!(
        engine
            .legal_priority_actions(0)
            .iter()
            .all(|action| action.card_instance_id.as_deref() != Some("orchard")),
        "a nonland mana source does not satisfy Exotic Orchard's Oracle text"
    );

    let mut island = mana_source("island", "Basic Land - Island", "{U}", None);
    island.owner = "player-1".to_string();
    island.controller = "player-1".to_string();
    engine.state.players[1].battlefield.push(island);
    let mut mountain = mana_source("mountain", "Basic Land - Mountain", "{R}", None);
    mountain.owner = "player-2".to_string();
    mountain.controller = "player-2".to_string();
    let mut wastes = mana_source("wastes", "Basic Land - Wastes", "{C}", None);
    wastes.owner = "player-2".to_string();
    wastes.controller = "player-2".to_string();
    engine.state.players[2].battlefield = vec![mountain, wastes];

    let produced = engine
        .legal_priority_actions(0)
        .into_iter()
        .filter(|action| action.card_instance_id.as_deref() == Some("orchard"))
        .map(|action| action.decisions["manaProduced"].clone())
        .collect::<Vec<_>>();
    assert_eq!(produced, vec![json!(["U"]), json!(["R"])]);
}

#[test]
fn reflecting_pool_activates_and_pays_from_a_tapped_lands_mana_type() {
    let mut engine = test_engine(2);
    let mut island = mana_source("island", "Basic Land - Island", "{U}", None);
    island.tapped = true;
    engine.state.players[0].battlefield = vec![reflecting_pool("pool"), island];
    let mana_action = engine
        .legal_priority_actions(0)
        .into_iter()
        .find(|action| {
            action.card_instance_id.as_deref() == Some("pool")
                && action.decisions["manaProduced"] == json!(["U"])
        })
        .expect("Reflecting Pool can produce blue from a tapped Island");

    engine
        .apply_priority_action(&mana_action, &mut RandomAi::seeded(1))
        .expect("Reflecting Pool mana ability resolves");
    assert_eq!(engine.state.players[0].mana_pool[0].symbol, "U");

    let mut payment_engine = test_engine(2);
    let mut swamp = mana_source("swamp", "Basic Land - Swamp", "{B}", None);
    swamp.tapped = true;
    payment_engine.state.players[0].battlefield = vec![reflecting_pool("payment-pool"), swamp];
    let mut spell = test_definition("black-spell", "Instant");
    spell.mana_cost = "{B}".to_string();
    spell.rules = vec![json!({
        "kind": "spellAbility",
        "source": { "kind": "self" },
        "effects": [{
            "kind": "gainLife",
            "player": {
                "kind": "controllerOf",
                "object": { "kind": "self" }
            },
            "amount": { "kind": "integer", "value": 1 }
        }]
    })];
    payment_engine.state.players[0].hand = vec![test_instance("black-spell", spell, "player-0")];
    payment_engine.state.step = GameStep::PrecombatMain;
    payment_engine.state.active_player = 0;
    let cast = payment_engine
        .legal_priority_actions(0)
        .into_iter()
        .find(|action| {
            action.kind == ActionKind::CastSpell
                && action.card_instance_id.as_deref() == Some("black-spell")
        })
        .expect("Reflecting Pool can pay for a black spell");
    assert_eq!(cast.payment_sources, vec!["payment-pool".to_string()]);

    payment_engine
        .apply_priority_action(&cast, &mut RandomAi::seeded(1))
        .expect("spell is cast with Reflecting Pool");
    assert!(payment_engine.state.players[0].battlefield[0].tapped);
    assert_eq!(payment_engine.state.stack.len(), 1);
    assert_eq!(
        payment_engine.state.stack[0].card.instance_id,
        "black-spell"
    );
}

#[test]
fn impossible_payment_with_many_flexible_sources_is_pruned() {
    let mut engine = test_engine(2);
    engine.state.players[0].battlefield = (0..18)
        .map(|index| city_of_brass(&format!("city-{index}")))
        .collect();
    let impossible_cost = std::iter::repeat_n("{W}", 19).collect::<String>();
    let started = Instant::now();

    let payment = engine.payment_for_mana_costs(0, &[impossible_cost], &BTreeSet::new(), None);

    assert!(payment.is_none());
    assert!(
        started.elapsed() < Duration::from_secs(2),
        "an impossible flexible payment should be rejected without combinatorial search"
    );
}

#[test]
fn city_of_brass_mana_activation_puts_its_damage_trigger_on_the_stack() {
    let mut engine = test_engine(2);
    engine.state.players[0].battlefield = vec![city_of_brass("city")];
    let action = engine
        .legal_priority_actions(0)
        .into_iter()
        .find(|action| {
            action.card_instance_id.as_deref() == Some("city")
                && action.decisions.get("manaAbility") == Some(&Value::Bool(true))
        })
        .expect("City of Brass mana ability is legal");

    engine
        .apply_priority_action(&action, &mut RandomAi::seeded(1))
        .expect("City of Brass produces mana");

    assert!(engine.state.players[0].battlefield[0].tapped);
    assert_eq!(engine.state.players[0].mana_pool[0].symbol, "W");
    assert_eq!(engine.state.stack.len(), 1);
    assert_eq!(
        engine.state.stack[0].ability_kind.as_deref(),
        Some("triggeredAbility")
    );
    engine
        .resolve_top_stack(&mut RandomAi::seeded(1))
        .expect("City of Brass damage trigger resolves");
    assert_eq!(engine.state.players[0].life, 19);
}

#[test]
fn city_of_brass_payment_trigger_is_above_the_spell() {
    let mut engine = test_engine(2);
    let mut spell = test_definition("white-spell", "Instant");
    spell.mana_cost = "{W}".to_string();
    spell.rules = vec![json!({
        "kind": "spellAbility",
        "source": { "kind": "self" },
        "effects": [{
            "kind": "gainLife",
            "player": {
                "kind": "controllerOf",
                "object": { "kind": "self" }
            },
            "amount": { "kind": "integer", "value": 1 }
        }]
    })];
    engine.state.players[0].hand = vec![test_instance("white-spell", spell, "player-0")];
    engine.state.players[0].battlefield = vec![city_of_brass("city")];
    engine.state.step = GameStep::PrecombatMain;
    engine.state.active_player = 0;
    let action = engine
        .legal_priority_actions(0)
        .into_iter()
        .find(|action| {
            action.kind == ActionKind::CastSpell
                && action.card_instance_id.as_deref() == Some("white-spell")
        })
        .expect("City of Brass can pay for the spell");

    engine
        .apply_priority_action(&action, &mut RandomAi::seeded(1))
        .expect("spell is cast using City of Brass");

    assert_eq!(engine.state.stack.len(), 2);
    assert_eq!(engine.state.stack[0].card.instance_id, "white-spell");
    assert_eq!(
        engine.state.stack[1].ability_kind.as_deref(),
        Some("triggeredAbility")
    );
    engine
        .resolve_top_stack(&mut RandomAi::seeded(1))
        .expect("City of Brass trigger resolves before the spell");
    assert_eq!(engine.state.players[0].life, 19);
    assert_eq!(engine.state.stack.len(), 1);
    assert_eq!(engine.state.stack[0].card.instance_id, "white-spell");
}

