#[test]
fn parsed_first_creature_reduction_and_flash_stop_after_the_first_cast() {
    let parsed = parse_oracle_card(OracleCardParseRequest {
        card_name: "Test Sage".to_string(),
        type_line: "Creature - Wizard".to_string(),
        mana_cost: Some("{2}{G}{U}".to_string()),
        oracle_text: Some(
            "The first creature spell you cast each turn costs {2} less to cast and can be cast as though it had flash."
                .to_string(),
        ),
        layout: None,
        faces: Vec::new(),
    });
    let rules = parsed
        .abilities
        .into_iter()
        .filter_map(|ability| ability.rule)
        .collect::<Vec<_>>();
    assert_eq!(rules.len(), 1);
    assert!(rule_is_executable(&rules[0]));

    let mut sage = test_definition("test-sage", "Creature - Wizard");
    sage.rules = rules;
    let mut first = test_definition("first-creature", "Creature - Elf");
    first.mana_cost = "{2}{G}".to_string();
    let mut second = test_definition("second-creature", "Creature - Dwarf");
    second.mana_cost = "{2}{G}".to_string();
    let mut engine = test_engine(2);
    engine.state.active_player = 1;
    engine.state.step = GameStep::PrecombatMain;
    engine.state.players[0].battlefield = vec![
        test_instance("test-sage", sage, "player-0"),
        mana_source("forest", "Basic Land - Forest", "{G}", None),
    ];
    engine.state.players[0].hand = vec![
        test_instance("first-creature", first, "player-0"),
        test_instance("second-creature", second, "player-0"),
    ];

    let first_cast = engine
        .legal_priority_actions(0)
        .into_iter()
        .find(|action| {
            action.kind == ActionKind::CastSpell
                && action.card_instance_id.as_deref() == Some("first-creature")
        })
        .expect("the first creature has flash and costs two less");
    assert_eq!(first_cast.payment_sources, vec!["forest".to_string()]);
    engine
        .apply_priority_action(&first_cast, &mut EmeritusDecisionProvider)
        .expect("cast the reduced first creature during an opponent's turn");

    assert!(engine.legal_priority_actions(0).iter().all(|action| {
        action.kind != ActionKind::CastSpell
            || action.card_instance_id.as_deref() != Some("second-creature")
    }));
}

#[test]
fn parsed_reveal_threshold_moves_the_creature_to_battlefield_or_hand() {
    let parsed = parse_oracle_card(OracleCardParseRequest {
        card_name: "Test Parting".to_string(),
        type_line: "Enchantment".to_string(),
        mana_cost: Some("{3}{G}".to_string()),
        oracle_text: Some(
            "Whenever a nontoken creature you control dies, reveal cards from the top of your library until you reveal a creature card. If its mana value is less than or equal to the number of lands you control, put it onto the battlefield. Otherwise, put it into your hand. Put the rest on the bottom of your library in a random order. This ability triggers only once each turn."
                .to_string(),
        ),
        layout: None,
        faces: Vec::new(),
    });
    let rule = parsed.abilities[0]
        .rule
        .clone()
        .expect("the conditional reveal trigger parses");
    assert!(rule_is_executable(&rule));
    assert_eq!(rule["triggerLimit"]["kind"], "onceEachTurn");

    let resolve_with_lands = |land_count: usize| {
        let mut engine = test_engine(2);
        engine.state.players[0].battlefield = (0..land_count)
            .map(|index| mana_source(&format!("land-{index}"), "Basic Land - Forest", "{G}", None))
            .collect();
        let mut creature = test_definition("revealed-creature", "Creature - Elf");
        creature.mana_cost = "{2}{G}".to_string();
        engine.state.players[0].library = vec![
            test_instance(
                "revealed-rest",
                test_definition("revealed-rest", "Sorcery"),
                "player-0",
            ),
            test_instance("revealed-creature", creature, "player-0"),
        ];
        let trigger = StackObject {
            id: format!("stack:parting-{land_count}"),
            controller: "player-0".to_string(),
            card: test_instance(
                "test-parting",
                test_definition("test-parting", "Enchantment"),
                "player-0",
            ),
            cant_be_countered: false,
            exile_on_leave_stack: false,
            ability_kind: Some("triggeredAbility".to_string()),
            ability_rule: Some(rule.clone()),
            decisions: BTreeMap::new(),
            targets: BTreeMap::new(),
        };
        engine
            .execute_effects(
                &rule["effects"],
                &trigger,
                &mut BTreeMap::new(),
                &mut BTreeMap::new(),
                &mut EmeritusDecisionProvider,
            )
            .expect("resolve the conditional revealed-card destination");
        engine
    };

    let enough_lands = resolve_with_lands(3);
    assert!(
        enough_lands
            .permanent_position("revealed-creature")
            .is_some()
    );
    assert!(
        enough_lands.state.players[0]
            .hand
            .iter()
            .all(|card| card.instance_id != "revealed-creature")
    );

    let too_few_lands = resolve_with_lands(2);
    assert!(
        too_few_lands
            .permanent_position("revealed-creature")
            .is_none()
    );
    assert!(
        too_few_lands.state.players[0]
            .hand
            .iter()
            .any(|card| card.instance_id == "revealed-creature")
    );
}

#[test]
fn parsed_conditional_source_sacrifice_only_creates_the_reward_after_sacrifice() {
    let parsed = parse_oracle_card(OracleCardParseRequest {
        card_name: "Test Mountain".to_string(),
        type_line: "Enchantment - Saga".to_string(),
        mana_cost: Some("{3}{R}".to_string()),
        oracle_text: Some(
            "I, II, III, IV — Create a Treasure token. Then if you control four or more Treasures, sacrifice this Saga. If you do, create a 6/6 red Dragon creature token with flying."
                .to_string(),
        ),
        layout: None,
        faces: Vec::new(),
    });
    let rule = parsed
        .abilities
        .iter()
        .filter_map(|ability| ability.rule.as_ref())
        .find(|rule| rule["event"]["kind"] == "sagaChapterReached")
        .cloned()
        .expect("the Saga chapter parses");
    assert!(rule_is_executable(&rule));

    let resolve_with_existing_treasures = |treasure_count: usize| {
        let mut engine = test_engine(2);
        let source = test_instance(
            "test-mountain",
            test_definition("test-mountain", "Enchantment - Saga"),
            "player-0",
        );
        engine.state.players[0].battlefield.push(source.clone());
        engine.state.players[0]
            .battlefield
            .extend((0..treasure_count).map(|index| {
                let mut definition = test_definition("Treasure", "Artifact - Treasure");
                definition.is_token = true;
                test_instance(&format!("treasure-{index}"), definition, "player-0")
            }));
        let trigger = StackObject {
            id: format!("stack:mountain-{treasure_count}"),
            controller: "player-0".to_string(),
            card: source,
            cant_be_countered: false,
            exile_on_leave_stack: false,
            ability_kind: Some("triggeredAbility".to_string()),
            ability_rule: Some(rule.clone()),
            decisions: BTreeMap::new(),
            targets: BTreeMap::new(),
        };
        engine
            .execute_effects(
                &rule["effects"],
                &trigger,
                &mut BTreeMap::new(),
                &mut BTreeMap::new(),
                &mut EmeritusDecisionProvider,
            )
            .expect("resolve the conditional source sacrifice");
        engine
    };

    let threshold_reached = resolve_with_existing_treasures(3);
    assert!(
        threshold_reached
            .permanent_position("test-mountain")
            .is_none()
    );
    assert!(
        threshold_reached.state.players[0]
            .graveyard
            .iter()
            .any(|card| card.instance_id == "test-mountain")
    );
    assert!(
        threshold_reached.state.players[0]
            .battlefield
            .iter()
            .any(|card| {
                card.definition
                    .type_line
                    .split_whitespace()
                    .any(|word| word == "Dragon")
                    && card.definition.power.as_deref() == Some("6")
                    && card.definition.toughness.as_deref() == Some("6")
            })
    );

    let threshold_missed = resolve_with_existing_treasures(2);
    assert!(
        threshold_missed
            .permanent_position("test-mountain")
            .is_some()
    );
    assert!(
        threshold_missed.state.players[0]
            .battlefield
            .iter()
            .all(|card| {
                !card
                    .definition
                    .type_line
                    .split_whitespace()
                    .any(|word| word == "Dragon")
            })
    );
}

#[test]
fn petrified_hamlet_stores_a_land_name_and_applies_both_static_modifiers() {
    let trigger_rule = json!({
        "kind": "triggeredAbility",
        "source": { "kind": "self" },
        "event": {
            "kind": "enterBattlefield",
            "object": { "kind": "self" },
        },
        "effects": [{
            "kind": "chooseCardName",
            "id": "chosenLandName",
            "player": {
                "kind": "controllerOf",
                "object": { "kind": "self" },
            },
            "where": {
                "kind": "cardTypeContains",
                "value": "Land",
            },
            "persistOn": { "kind": "self" },
        }],
    });
    let stored_name = json!({
        "kind": "storedDecision",
        "object": { "kind": "self" },
        "decisionId": "chosenLandName",
    });
    let prohibit_rule = json!({
        "kind": "staticAbility",
        "source": { "kind": "self" },
        "activeWhile": {
            "kind": "inZone",
            "object": { "kind": "self" },
            "zone": { "kind": "battlefield" },
        },
        "modifiers": [{
            "kind": "prohibitActivation",
            "abilities": {
                "kind": "activatedAbilities",
                "sourceWhere": {
                    "kind": "nameEquals",
                    "value": stored_name.clone(),
                },
                "where": {
                    "kind": "not",
                    "operand": { "kind": "isManaAbility" },
                },
            },
        }],
    });
    let grant_rule = json!({
        "kind": "staticAbility",
        "source": { "kind": "self" },
        "activeWhile": {
            "kind": "inZone",
            "object": { "kind": "self" },
            "zone": { "kind": "battlefield" },
        },
        "modifiers": [{
            "kind": "grantAbility",
            "objects": {
                "kind": "permanents",
                "where": {
                    "kind": "and",
                    "operands": [
                        {
                            "kind": "cardTypeContains",
                            "value": "Land",
                        },
                        {
                            "kind": "nameEquals",
                            "value": stored_name,
                        },
                    ],
                },
            },
            "ability": {
                "kind": "manaAbility",
                "costs": [{
                    "kind": "tap",
                    "object": { "kind": "abilitySource" },
                }],
                "effects": [{
                    "kind": "addMana",
                    "player": {
                        "kind": "controllerOf",
                        "object": { "kind": "abilitySource" },
                    },
                    "mana": "{C}",
                }],
            },
        }],
    });
    assert!(triggered_rule_supported(&trigger_rule));
    assert!(battlefield_static_rule_supported(&prohibit_rule));
    assert!(battlefield_static_rule_supported(&grant_rule));

    let nonmana_rule = json!({
        "kind": "activatedAbility",
        "source": { "kind": "self" },
        "costs": [{
            "kind": "tap",
            "object": { "kind": "self" },
        }],
        "effects": [{
            "kind": "gainLife",
            "player": {
                "kind": "controllerOf",
                "object": { "kind": "self" },
            },
            "amount": { "kind": "integer", "value": 1 },
        }],
    });
    let mut hamlet_definition = test_definition("petrified-hamlet", "Land");
    hamlet_definition.name = "Petrified Hamlet".to_string();
    hamlet_definition.rules = vec![trigger_rule.clone(), prohibit_rule, grant_rule];
    let mut island_definition = test_definition("island", "Basic Land - Island");
    island_definition.name = "Island".to_string();
    island_definition.rules = vec![nonmana_rule.clone()];
    let mut mountain_definition = test_definition("mountain", "Basic Land - Mountain");
    mountain_definition.name = "Mountain".to_string();
    mountain_definition.rules = vec![nonmana_rule];

    let mut engine = test_engine(2);
    engine.state.players[0].battlefield = vec![
        test_instance("petrified-hamlet", hamlet_definition, "player-0"),
        test_instance("island", island_definition, "player-0"),
        test_instance("mountain", mountain_definition, "player-0"),
    ];
    let source = engine.state.players[0].battlefield[0].clone();
    let stack_object = StackObject {
        id: "stack:hamlet-trigger".to_string(),
        controller: "player-0".to_string(),
        card: source,
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: Some("triggeredAbility".to_string()),
        ability_rule: Some(trigger_rule.clone()),
        decisions: BTreeMap::new(),
        targets: BTreeMap::new(),
    };
    engine
        .execute_effects(
            &trigger_rule["effects"],
            &stack_object,
            &mut BTreeMap::new(),
            &mut BTreeMap::new(),
            &mut IslandNameDecisionProvider,
        )
        .expect("choose Island");
    let hamlet = &engine.state.players[0].battlefield[0];
    assert_eq!(
        stored_decision_value(&hamlet.definition, "chosenLandName"),
        Some("Island")
    );

    let island_choices = engine.mana_choices_for_permanent(
        &engine.state.players[0].battlefield[1],
        None,
        true,
        true,
    );
    assert!(island_choices.iter().any(|choice| choice.symbols == ["U"]));
    assert!(island_choices.iter().any(|choice| choice.symbols == ["C"]));
    let actions = engine.legal_priority_actions(0);
    assert!(actions.iter().all(|action| {
        action.kind != ActionKind::ActivateAbility
            || action.card_instance_id.as_deref() != Some("island")
            || action.decisions.get("manaAbility") == Some(&Value::Bool(true))
    }));
    assert!(actions.iter().any(|action| {
        action.kind == ActionKind::ActivateAbility
            && action.card_instance_id.as_deref() == Some("mountain")
            && action.decisions.get("manaAbility") != Some(&Value::Bool(true))
    }));
}

#[test]
fn negate_targets_and_counters_only_a_noncreature_spell() {
    let mut engine = test_engine(2);
    let mut negate = test_definition("negate", "Instant");
    negate.name = "Negate".to_string();
    negate.mana_cost = "{1}{U}".to_string();
    negate.rules = vec![json!({
        "kind": "spellAbility",
        "source": { "kind": "self" },
        "declaration": {
            "kind": "castingDeclaration",
            "decisions": [{
                "id": "targetSpell",
                "kind": "chooseTargets",
                "minimum": 1,
                "maximum": 1,
                "candidates": {
                    "kind": "spells",
                    "where": {
                        "kind": "not",
                        "operand": {
                            "kind": "cardTypeContains",
                            "value": "Creature",
                        },
                    },
                },
            }],
        },
        "effects": [{
            "kind": "counterSpell",
            "spell": {
                "kind": "chosenTarget",
                "id": "targetSpell",
            },
        }],
    })];
    engine.state.players[0].hand = vec![test_instance("negate", negate, "player-0")];
    engine.state.players[0].battlefield = vec![
        mana_source("island-1", "Basic Land - Island", "{U}", None),
        mana_source("island-2", "Basic Land - Island", "{U}", None),
    ];
    let creature_spell = test_instance(
        "creature-spell",
        test_definition("creature-spell", "Creature"),
        "player-1",
    );
    let instant_spell = test_instance(
        "instant-spell",
        test_definition("instant-spell", "Instant"),
        "player-1",
    );
    let mut alexios_definition = test_definition(
        "alexios-deimos-of-kosmos",
        "Legendary Creature - Human Berserker",
    );
    alexios_definition.name = "Alexios, Deimos of Kosmos".to_string();
    engine.state.stack = vec![
        StackObject {
            id: "stack:alexios-trigger".to_string(),
            controller: "player-1".to_string(),
            card: test_instance("alexios", alexios_definition, "player-1"),
            cant_be_countered: false,
            exile_on_leave_stack: false,
            ability_kind: Some("triggeredAbility".to_string()),
            ability_rule: None,
            decisions: BTreeMap::new(),
            targets: BTreeMap::new(),
        },
        StackObject {
            id: "stack:creature".to_string(),
            controller: "player-1".to_string(),
            card: creature_spell,
            cant_be_countered: false,
            exile_on_leave_stack: false,
            ability_kind: None,
            ability_rule: None,
            decisions: BTreeMap::new(),
            targets: BTreeMap::new(),
        },
        StackObject {
            id: "stack:instant".to_string(),
            controller: "player-1".to_string(),
            card: instant_spell,
            cant_be_countered: false,
            exile_on_leave_stack: false,
            ability_kind: None,
            ability_rule: None,
            decisions: BTreeMap::new(),
            targets: BTreeMap::new(),
        },
    ];

    let actions = engine.legal_priority_actions(0);
    let negate_actions = actions
        .iter()
        .filter(|action| {
            action.kind == ActionKind::CastSpell
                && action.card_instance_id.as_deref() == Some("negate")
        })
        .cloned()
        .collect::<Vec<_>>();
    assert_eq!(negate_actions.len(), 1);
    assert_eq!(
        negate_actions[0].targets.get("targetSpell"),
        Some(&TargetRef::StackObject {
            stack_id: "stack:instant".to_string(),
        })
    );
    engine
        .apply_priority_action(&negate_actions[0], &mut RandomAi::seeded(1))
        .expect("cast Negate");
    engine
        .resolve_top_stack(&mut RandomAi::seeded(1))
        .expect("resolve Negate");

    assert_eq!(engine.state.stack.len(), 2);
    assert_eq!(engine.state.stack[0].id, "stack:alexios-trigger");
    assert_eq!(engine.state.stack[1].id, "stack:creature");
    assert!(
        engine.state.players[1]
            .graveyard
            .iter()
            .any(|card| card.instance_id == "instant-spell")
    );
}

#[test]
fn counter_spell_effect_cannot_counter_a_triggered_ability() {
    let mut engine = test_engine(2);
    let triggered_ability = StackObject {
        id: "stack:alexios-trigger".to_string(),
        controller: "player-1".to_string(),
        card: test_instance(
            "alexios",
            test_definition(
                "alexios-deimos-of-kosmos",
                "Legendary Creature - Human Berserker",
            ),
            "player-1",
        ),
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: Some("triggeredAbility".to_string()),
        ability_rule: None,
        decisions: BTreeMap::new(),
        targets: BTreeMap::new(),
    };
    engine.state.stack.push(triggered_ability);
    let counter = StackObject {
        id: "stack:counterspell".to_string(),
        controller: "player-0".to_string(),
        card: test_instance(
            "counterspell",
            test_definition("counterspell", "Instant"),
            "player-0",
        ),
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: None,
        ability_rule: None,
        decisions: BTreeMap::new(),
        targets: BTreeMap::from([(
            "targetSpell".to_string(),
            TargetRef::StackObject {
                stack_id: "stack:alexios-trigger".to_string(),
            },
        )]),
    };

    engine
        .execute_effects(
            &json!([{
                "kind": "counterSpell",
                "spell": { "kind": "chosenTarget", "id": "targetSpell" },
            }]),
            &counter,
            &mut BTreeMap::new(),
            &mut BTreeMap::new(),
            &mut RandomAi::seeded(1),
        )
        .expect("resolve Counterspell");

    assert_eq!(engine.state.stack.len(), 1);
    assert_eq!(engine.state.stack[0].id, "stack:alexios-trigger");
    assert!(engine.state.players[1].graveyard.is_empty());
}

#[test]
fn treasure_token_has_and_executes_its_intrinsic_mana_ability() {
    let mut engine = test_engine(2);
    let treasure_definition = compile_named_token_definition("Treasure")
        .expect("token catalog loads")
        .expect("Treasure definition compiles");
    engine.state.players[0].battlefield =
        vec![test_instance("treasure", treasure_definition, "player-0")];
    assert!(mana_rule_supported(
        &engine.state.players[0].battlefield[0].definition.rules[0]
    ));
    assert_eq!(
        engine
            .mana_choices_for_permanent(&engine.state.players[0].battlefield[0], None, true, true,)
            .len(),
        5
    );

    let action = engine
        .legal_priority_actions(0)
        .into_iter()
        .find(|action| {
            action.kind == ActionKind::ActivateAbility
                && action.card_instance_id.as_deref() == Some("treasure")
                && action.decisions.get("manaProduced") == Some(&json!(["W"]))
        })
        .expect("white Treasure mana action");
    engine
        .apply_priority_action(&action, &mut RandomAi::seeded(1))
        .expect("activate Treasure");

    assert!(engine.state.players[0].battlefield.is_empty());
    assert!(engine.state.players[0].graveyard.is_empty());
    assert_eq!(engine.state.players[0].mana_pool[0].symbol, "W");
    assert!(
        engine
            .state
            .events
            .iter()
            .any(|event| event.kind == "tokenCeasedToExist")
    );
}

#[test]
fn parsed_eldrazi_token_keeps_and_executes_its_embedded_mana_ability() {
    let parsed = parse_oracle_card(OracleCardParseRequest {
        card_name: "Test Spawn Maker".to_string(),
        type_line: "Sorcery".to_string(),
        mana_cost: Some("{2}{C}".to_string()),
        oracle_text: Some(
            "Create a 0/1 colorless Eldrazi Spawn creature token. It has \"Sacrifice this token: Add {C}.\""
                .to_string(),
        ),
        layout: None,
        faces: Vec::new(),
    });
    let rule = parsed.abilities[0]
        .rule
        .as_ref()
        .expect("token creation parses canonically");
    let create_token = &rule["effects"][0];

    let mut engine = test_engine(2);
    let stack_object = StackObject {
        id: "stack:test-spawn-maker".to_string(),
        controller: "player-0".to_string(),
        card: test_instance(
            "test-spawn-maker",
            test_definition("test-spawn-maker", "Sorcery"),
            "player-0",
        ),
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: None,
        ability_rule: None,
        decisions: BTreeMap::new(),
        targets: BTreeMap::new(),
    };
    engine
        .create_tokens(
            create_token,
            &stack_object,
            &BTreeMap::new(),
            &BTreeMap::new(),
        )
        .expect("create parsed Eldrazi Spawn token");

    let spawn = &engine.state.players[0].battlefield[0];
    assert_eq!(spawn.definition.name, "Eldrazi Spawn Token");
    assert_eq!(spawn.definition.rules[0]["kind"], "manaAbility");
    let spawn_id = spawn.instance_id.clone();
    let action = engine
        .legal_priority_actions(0)
        .into_iter()
        .find(|action| {
            action.kind == ActionKind::ActivateAbility
                && action.card_instance_id.as_deref() == Some(spawn_id.as_str())
        })
        .expect("the parsed Spawn mana ability is legal");
    engine
        .apply_priority_action(&action, &mut RandomAi::seeded(1))
        .expect("sacrifice Spawn for colorless mana");

    assert!(engine.state.players[0].battlefield.is_empty());
    assert_eq!(engine.state.players[0].mana_pool[0].symbol, "C");
}

#[test]
fn clue_token_uses_its_parsed_catalog_ability_to_draw_a_card() {
    let mut engine = test_engine(2);
    let clue_definition = compile_named_token_definition("Clue")
        .expect("token catalog loads")
        .expect("Clue definition compiles");
    engine.state.players[0].battlefield = vec![
        test_instance("clue", clue_definition, "player-0"),
        mana_source("wastes-1", "Basic Land - Wastes", "{C}", None),
        mana_source("wastes-2", "Basic Land - Wastes", "{C}", None),
    ];
    engine.state.players[0].hand.clear();
    engine.state.players[0].library = vec![test_instance(
        "clue-drawn-card",
        test_definition("clue-drawn-card", "Instant"),
        "player-0",
    )];

    let action = engine
        .legal_priority_actions(0)
        .into_iter()
        .find(|action| {
            action.kind == ActionKind::ActivateAbility
                && action.card_instance_id.as_deref() == Some("clue")
        })
        .expect("Clue activation is legal");
    engine
        .apply_priority_action(&action, &mut RandomAi::seeded(1))
        .expect("pay and sacrifice Clue");
    assert!(
        engine.state.players[0]
            .battlefield
            .iter()
            .all(|card| card.instance_id != "clue")
    );

    engine
        .resolve_top_stack(&mut RandomAi::seeded(1))
        .expect("resolve Clue draw");
    assert_eq!(
        engine.state.players[0].hand[0].instance_id,
        "clue-drawn-card"
    );
}

#[test]
fn created_blood_token_uses_catalog_oracle_and_executes_all_of_its_costs() {
    let mut engine = test_engine(2);
    engine.state.step = GameStep::PrecombatMain;
    engine.state.players[0].battlefield =
        vec![mana_source("wastes", "Basic Land - Wastes", "{C}", None)];
    engine.state.players[0].hand = vec![test_instance(
        "discarded-card",
        test_definition("discarded-card", "Sorcery"),
        "player-0",
    )];
    engine.state.players[0].library = vec![test_instance(
        "drawn-card",
        test_definition("drawn-card", "Instant"),
        "player-0",
    )];
    let mut source_definition = test_definition("blood-source", "Sorcery");
    source_definition.rules.push(json!({
        "kind": "rulesMarker",
        "text": "Source-linked token definitions",
        "relatedTokenOracle": [{
            "name": "blood",
            "typeLine": "Token Artifact - Blood Source Linked",
            "oracleText": "{1}, {T}, Discard a card, Sacrifice this token: Draw a card.",
            "manaCost": "",
        }],
    }));
    let stack_object = StackObject {
        id: "stack:create-blood".to_string(),
        controller: "player-0".to_string(),
        card: test_instance("blood-source", source_definition, "player-0"),
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: None,
        ability_rule: None,
        decisions: BTreeMap::new(),
        targets: BTreeMap::new(),
    };
    engine
        .create_tokens(
            &json!({
                "kind": "createTokens",
                "controller": { "kind": "controllerOf", "object": { "kind": "self" } },
                "quantity": { "kind": "integer", "value": 1 },
                "token": { "kind": "namedToken", "name": "Blood" },
            }),
            &stack_object,
            &BTreeMap::new(),
            &BTreeMap::new(),
        )
        .expect("create Blood token");

    let blood = engine.state.players[0]
        .battlefield
        .iter()
        .find(|card| card.definition.name == "Blood")
        .expect("Blood is on the battlefield");
    let blood_id = blood.instance_id.clone();
    assert!(blood.definition.type_line.contains("Artifact"));
    assert!(blood.definition.type_line.contains("Source Linked"));
    assert_eq!(blood.definition.rules[0]["effects"][0]["kind"], "drawCards");
    assert!(
        blood.definition.rules[0]["costs"]
            .as_array()
            .is_some_and(|costs| { costs.iter().any(|cost| cost["kind"] == "discardCard") })
    );

    let action = engine
        .legal_priority_actions(0)
        .into_iter()
        .find(|action| {
            action.kind == ActionKind::ActivateAbility
                && action.card_instance_id.as_deref() == Some(blood_id.as_str())
        })
        .expect("Blood activation is legal");
    engine
        .apply_priority_action(&action, &mut RandomAi::seeded(1))
        .expect("pay Blood activation costs");
    assert!(
        engine.state.players[0]
            .battlefield
            .iter()
            .all(|card| card.instance_id != blood_id)
    );
    assert!(
        engine.state.players[0]
            .graveyard
            .iter()
            .any(|card| card.instance_id == "discarded-card")
    );
    assert!(engine.state.players[0].hand.is_empty());

    engine
        .resolve_top_stack(&mut RandomAi::seeded(1))
        .expect("resolve Blood draw");
    assert_eq!(engine.state.players[0].hand[0].instance_id, "drawn-card");
}

