#[test]
fn self_dies_trigger_fires_only_when_its_source_dies() {
    let mut engine = test_engine(2);
    let mut sage_definition = test_definition("infestation-sage", "Creature - Elf Warlock");
    sage_definition.power = Some("1".to_string());
    sage_definition.toughness = Some("1".to_string());
    sage_definition.rules = vec![json!({
        "kind": "triggeredAbility",
        "source": { "kind": "self" },
        "event": {
            "kind": "permanentDied",
            "object": { "kind": "self" }
        },
        "effects": [{
            "kind": "createTokens",
            "controller": {
                "kind": "controllerOf",
                "object": { "kind": "self" }
            },
            "quantity": { "kind": "integer", "value": 1 },
            "token": {
                "types": ["Creature"],
                "subtypes": ["Insect"],
                "colors": ["Black", "Green"],
                "power": 1,
                "toughness": 1,
                "abilities": [{ "kind": "flying" }]
            }
        }]
    })];
    engine.state.stack.push(StackObject {
        id: "stack:infestation-sage".to_string(),
        controller: "player-0".to_string(),
        card: test_instance("infestation-sage", sage_definition, "player-0"),
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: None,
        ability_rule: None,
        decisions: BTreeMap::new(),
        targets: BTreeMap::new(),
    });

    engine
        .resolve_top_stack(&mut EmeritusDecisionProvider)
        .expect("Infestation Sage resolves");

    assert!(engine.state.stack.is_empty());
    assert_eq!(engine.state.players[0].battlefield.len(), 1);
    assert_eq!(
        engine.state.players[0]
            .battlefield
            .iter()
            .filter(|card| card.definition.is_token)
            .count(),
        0,
        "a permanentDied trigger must not fire as an enter-battlefield trigger"
    );

    engine.state.players[0].battlefield.push(test_instance(
        "other-creature",
        test_definition("other-creature", "Creature - Rat"),
        "player-0",
    ));
    engine
        .move_permanent_to_graveyard("other-creature", "destroyed")
        .expect("another creature dies");
    assert!(
        engine.state.stack.is_empty(),
        "a self permanentDied trigger must not fire for another permanent"
    );

    engine
        .move_permanent_to_graveyard("infestation-sage", "destroyed")
        .expect("Infestation Sage dies");
    assert_eq!(engine.state.stack.len(), 1);
    engine
        .resolve_top_stack(&mut EmeritusDecisionProvider)
        .expect("Infestation Sage death trigger resolves");

    let insects = engine.state.players[0]
        .battlefield
        .iter()
        .filter(|card| card.definition.is_token && card.definition.type_line.contains("Insect"))
        .count();
    assert_eq!(insects, 1);
}

