#[test]
fn another_land_play_trigger_ignores_its_source_but_observes_a_later_land() {
    let mut engine = test_engine(2);
    engine.state.step = GameStep::PrecombatMain;
    engine.state.active_player = 0;
    engine.state.players[0].hand.clear();

    let mut watcher_definition = test_definition("land-watcher", "Land");
    watcher_definition.rules = vec![json!({
        "kind": "triggeredAbility",
        "source": { "kind": "self" },
        "event": {
            "kind": "landPlayed",
            "player": {
                "kind": "controllerOf",
                "object": { "kind": "self" }
            },
            "excludeSource": true
        },
        "effects": [{
            "kind": "sacrificePermanent",
            "permanent": { "kind": "self" }
        }]
    })];
    engine.state.players[0].hand = vec![
        test_instance("land-watcher", watcher_definition, "player-0"),
        test_instance(
            "later-land",
            test_definition("later-land", "Basic Land - Forest"),
            "player-0",
        ),
    ];

    let play_watcher = engine
        .legal_priority_actions(0)
        .into_iter()
        .find(|action| action.card_instance_id.as_deref() == Some("land-watcher"))
        .expect("the trigger-bearing land can be played");
    engine
        .apply_priority_action(&play_watcher, &mut EmeritusDecisionProvider)
        .expect("the trigger-bearing land is played");

    assert!(engine.state.stack.is_empty());
    assert!(
        engine.state.players[0]
            .battlefield
            .iter()
            .any(|card| card.instance_id == "land-watcher")
    );

    engine.state.turn_number += 1;
    let play_later_land = engine
        .legal_priority_actions(0)
        .into_iter()
        .find(|action| action.card_instance_id.as_deref() == Some("later-land"))
        .expect("the later land can be played on the next turn");
    engine
        .apply_priority_action(&play_later_land, &mut EmeritusDecisionProvider)
        .expect("the later land is played");

    assert_eq!(engine.state.stack.len(), 1);
    engine
        .resolve_top_stack(&mut EmeritusDecisionProvider)
        .expect("the land-play trigger resolves");
    assert!(
        !engine.state.players[0]
            .battlefield
            .iter()
            .any(|card| card.instance_id == "land-watcher")
    );
    assert!(
        engine.state.players[0]
            .graveyard
            .iter()
            .any(|card| card.instance_id == "land-watcher")
    );
}

#[test]
fn power_of_a_chosen_target_is_evaluated_during_resolution() {
    let mut engine = test_engine(2);
    engine.state.step = GameStep::PrecombatMain;
    let mut creature_definition = test_definition("creature", "Creature - Giant");
    creature_definition.power = Some("3".to_string());
    creature_definition.toughness = Some("3".to_string());
    let creature = test_instance("creature", creature_definition, "player-0");
    let mut bulk_up_definition = test_definition("bulk-up", "Instant");
    bulk_up_definition.name = "Bulk Up".to_string();
    bulk_up_definition.rules = vec![json!({
        "kind": "spellAbility",
        "source": { "kind": "self" },
        "declaration": {
            "kind": "castingDeclaration",
            "decisions": [{
                "id": "targetCreature",
                "kind": "chooseTargets",
                "minimum": 1,
                "maximum": 1,
                "candidates": {
                    "kind": "permanents",
                    "where": { "kind": "cardTypeContains", "value": "Creature" }
                }
            }]
        },
        "effects": [{
            "kind": "modifyPowerToughness",
            "object": { "kind": "chosenTarget", "id": "targetCreature" },
            "power": {
                "kind": "powerOf",
                "object": { "kind": "chosenTarget", "id": "targetCreature" }
            },
            "toughness": { "kind": "integer", "value": 0 },
            "duration": { "kind": "untilEndOfCurrentTurn" }
        }]
    })];
    engine.state.players[0].battlefield = vec![creature];
    engine.state.players[0].hand = vec![test_instance("bulk-up", bulk_up_definition, "player-0")];

    let action = engine
        .legal_priority_actions(0)
        .into_iter()
        .find(|action| {
            action.kind == ActionKind::CastSpell
                && action.card_instance_id.as_deref() == Some("bulk-up")
                && action.targets["targetCreature"]
                    == TargetRef::Permanent {
                        instance_id: "creature".to_string(),
                    }
        })
        .expect("Bulk Up can target the creature");
    engine
        .apply_priority_action(&action, &mut EmeritusDecisionProvider)
        .expect("Bulk Up is cast");
    engine
        .resolve_top_stack(&mut EmeritusDecisionProvider)
        .expect("Bulk Up resolves");

    let creature = &engine.state.players[0].battlefield[0];
    assert_eq!(creature.power_modifier, 3);
    assert_eq!(engine.current_power(creature), 6);
}

