#[test]
fn day_of_judgment_casts_without_targets_and_destroys_every_players_creatures() {
    let mut engine = test_engine(3);
    let mut judgment = test_definition("day-of-judgment", "Sorcery");
    judgment.name = "Day of Judgment".to_string();
    judgment.mana_cost = "{2}{W}{W}".to_string();
    judgment.rules = vec![json!({
        "kind": "spellAbility",
        "source": { "kind": "self" },
        "effects": [{
            "kind": "destroyPermanent",
            "permanent": {
                "kind": "eachPermanent",
                "where": { "kind": "cardTypeContains", "value": "Creature" },
            },
        }],
    })];
    engine.state.players[0].hand = vec![test_instance("judgment", judgment, "player-0")];
    engine.state.players[0].mana_pool = ["W", "W", "C", "C"]
        .iter()
        .map(|symbol| FloatingMana {
            spend_restriction: None,
            symbol: (*symbol).to_string(),
        })
        .collect();
    engine.state.step = GameStep::PrecombatMain;
    engine.state.active_player = 0;

    let action = engine
        .legal_priority_actions(0)
        .into_iter()
        .find(|action| {
            action.kind == ActionKind::CastSpell
                && action.card_instance_id.as_deref() == Some("judgment")
        })
        .expect("Day of Judgment is castable with no creatures and enough mana");
    assert!(action.targets.is_empty());
    assert!(action.target_order.is_empty());

    for player_index in 0..3 {
        let player_id = format!("player-{player_index}");
        engine.state.players[player_index].battlefield = vec![test_instance(
            &format!("creature-{player_index}"),
            test_definition(&format!("creature-{player_index}"), "Creature"),
            &player_id,
        )];
    }
    let mut provider = EmeritusDecisionProvider;
    engine
        .apply_priority_action(&action, &mut provider)
        .expect("Day of Judgment is cast");
    engine
        .resolve_top_stack(&mut provider)
        .expect("Day of Judgment resolves");

    assert!(
        engine
            .state
            .players
            .iter()
            .all(|player| player.battlefield.is_empty())
    );
    for player_index in 0..3 {
        assert!(
            engine.state.players[player_index]
                .graveyard
                .iter()
                .any(|card| card.instance_id == format!("creature-{player_index}"))
        );
    }
    assert!(
        engine.state.players[0]
            .graveyard
            .iter()
            .any(|card| card.instance_id == "judgment")
    );
}

