#[test]
fn variable_combat_bonus_uses_cast_x_and_grants_both_keywords() {
    let mut engine = test_engine(2);
    let mut confrontation = test_definition("frantic-confrontation", "Instant");
    confrontation.name = "Frantic Confrontation".to_string();
    confrontation.mana_cost = "{X}{R}".to_string();
    confrontation.rules = vec![json!({
        "kind": "spellAbility",
        "source": { "kind": "self" },
        "declaration": {
            "kind": "castingDeclaration",
            "decisions": [
                {
                    "id": "xValue",
                    "kind": "chooseNumber",
                    "minimum": 0,
                },
                {
                    "id": "targetCreature",
                    "kind": "chooseTargets",
                    "minimum": 1,
                    "maximum": 1,
                    "candidates": {
                        "kind": "permanents",
                        "controller": { "kind": "controllerOf", "object": { "kind": "self" } },
                        "where": { "kind": "cardTypeContains", "value": "Creature" },
                    },
                },
            ],
        },
        "effects": [
            {
                "kind": "modifyPowerToughness",
                "object": { "kind": "chosenTarget", "id": "targetCreature" },
                "power": { "kind": "decisionResult", "decisionId": "xValue" },
                "toughness": 0,
                "duration": { "kind": "untilEndOfCurrentTurn" },
            },
            {
                "kind": "grantKeyword",
                "object": { "kind": "chosenTarget", "id": "targetCreature" },
                "keyword": "firstStrike",
                "duration": { "kind": "untilEndOfCurrentTurn" },
            },
            {
                "kind": "grantKeyword",
                "object": { "kind": "chosenTarget", "id": "targetCreature" },
                "keyword": "trample",
                "duration": { "kind": "untilEndOfCurrentTurn" },
            },
        ],
    })];
    engine.state.players[0].hand = vec![test_instance(
        "frantic-confrontation",
        confrontation,
        "player-0",
    )];
    engine.state.players[0].battlefield = vec![test_instance(
        "target-creature",
        test_definition("target-creature", "Creature"),
        "player-0",
    )];
    engine.state.players[0].mana_pool = ["R", "C", "C"]
        .iter()
        .map(|symbol| FloatingMana {
            spend_restriction: None,
            symbol: (*symbol).to_string(),
        })
        .collect();

    let actions = engine.legal_priority_actions(0);
    let action = actions
        .iter()
        .find(|action| {
            action.kind == ActionKind::CastSpell
                && action.card_instance_id.as_deref() == Some("frantic-confrontation")
                && action.decisions.get("xValue") == Some(&Value::from(2))
        })
        .cloned()
        .unwrap_or_else(|| panic!("Frantic Confrontation actions: {actions:#?}"));
    let mut provider = EmeritusDecisionProvider;
    engine
        .apply_priority_action(&action, &mut provider)
        .expect("Frantic Confrontation is cast");
    engine
        .resolve_top_stack(&mut provider)
        .expect("Frantic Confrontation resolves");

    let target = engine.state.players[0]
        .battlefield
        .iter()
        .find(|card| card.instance_id == "target-creature")
        .expect("target creature remains on the battlefield");
    assert_eq!(engine.current_power(target), 4);
    assert!(engine.permanent_has_keyword(target, "firstStrike"));
    assert!(engine.permanent_has_keyword(target, "trample"));
}

#[test]
fn creature_entered_during_combat_trigger_ignores_main_phase_entries() {
    let mut engine = test_engine(2);
    let mut blue_spirit = test_definition("the-blue-spirit", "Creature - Spirit");
    blue_spirit.rules = vec![json!({
        "kind": "triggeredAbility",
        "source": { "kind": "self" },
        "event": {
            "kind": "permanentEntered",
            "player": { "kind": "controllerOf", "object": { "kind": "self" } },
            "where": {
                "kind": "and",
                "operands": [
                    { "kind": "cardTypeContains", "value": "Creature" },
                    { "kind": "not", "operand": { "kind": "isToken" } },
                ],
            },
            "duringCombat": true,
        },
        "effects": [{
            "kind": "drawCards",
            "player": { "kind": "controllerOf", "object": { "kind": "self" } },
            "count": 1,
        }],
    })];
    engine.state.players[0].battlefield =
        vec![test_instance("the-blue-spirit", blue_spirit, "player-0")];
    engine.state.players[0].library = vec![test_instance(
        "drawn-card",
        test_definition("drawn-card", "Sorcery"),
        "player-0",
    )];
    let entrant = test_instance(
        "entering-creature",
        test_definition("entering-creature", "Creature"),
        "player-0",
    );

    engine.state.step = GameStep::PrecombatMain;
    engine.enqueue_enter_battlefield_triggers(&entrant);
    assert!(engine.state.stack.is_empty());

    engine.state.step = GameStep::DeclareAttackers;
    engine.enqueue_enter_battlefield_triggers(&entrant);
    assert_eq!(engine.state.stack.len(), 1);
    engine
        .resolve_top_stack(&mut EmeritusDecisionProvider)
        .expect("combat entry trigger resolves");
    assert!(
        engine.state.players[0]
            .hand
            .iter()
            .any(|card| card.instance_id == "drawn-card")
    );
}

fn prepare_spell_rule() -> Value {
    json!({
        "kind": "prepareSpell",
        "spell": {
            "id": "ancestral-recall",
            "name": "Ancestral Recall",
            "typeLine": "Instant",
            "manaCost": "{U}",
            "rules": [{
                "kind": "spellAbility",
                "source": { "kind": "self" },
                "declaration": {
                    "kind": "castingDeclaration",
                    "decisions": [{
                        "id": "targetPlayer",
                        "kind": "chooseTargets",
                        "minimum": 1,
                        "maximum": 1,
                        "candidates": { "kind": "players" }
                    }]
                },
                "effects": [{
                    "kind": "drawCards",
                    "player": { "kind": "chosenTarget", "id": "targetPlayer" },
                    "count": 3
                }]
            }]
        }
    })
}

fn emeritus_definition(include_attack_trigger: bool) -> CardDefinition {
    let mut rules = vec![
        json!({
            "kind": "replacementEffect",
            "source": { "kind": "self" },
            "event": {
                "kind": "wouldEnterBattlefield",
                "object": { "kind": "self" }
            },
            "replacement": [{
                "kind": "setPrepared",
                "object": { "kind": "self" },
                "value": true
            }]
        }),
        prepare_spell_rule(),
    ];
    if include_attack_trigger {
        rules.push(json!({
            "kind": "triggeredAbility",
            "source": { "kind": "self" },
            "event": {
                "kind": "declaredAttacker",
                "object": { "kind": "self" }
            },
            "effects": [{
                "kind": "optionalAction",
                "player": {
                    "kind": "controllerOf",
                    "object": { "kind": "self" }
                },
                "action": {
                    "kind": "exileCards",
                    "count": 8,
                    "from": {
                        "kind": "graveyard",
                        "player": {
                            "kind": "controllerOf",
                            "object": { "kind": "self" }
                        }
                    }
                },
                "onPerformed": [{
                    "kind": "setPrepared",
                    "object": { "kind": "self" },
                    "value": true
                }]
            }]
        }));
    }
    CardDefinition {
        mana_cost: "{0}".to_string(),
        name: "Emeritus of Ideation".to_string(),
        power: Some("5".to_string()),
        rules,
        toughness: Some("5".to_string()),
        ..test_definition("emeritus-of-ideation", "Creature - Human Wizard")
    }
}

/// Feature: Casting a preparation permanent never declares the linked spell's target.
#[test]
fn preparation_permanent_cast_creates_a_separate_prepared_spell_copy() {
    let mut engine = test_engine(2);
    let emeritus = test_instance("emeritus", emeritus_definition(false), "player-0");
    engine.state.players[0].hand = vec![emeritus.clone()];
    engine.state.players[0].battlefield = vec![test_instance(
        "island",
        test_definition("island", "Basic Land - Island"),
        "player-0",
    )];

    let declarations = engine
        .declarations_for_card(&emeritus.definition, "player-0")
        .expect("the permanent declaration is executable");
    assert_eq!(declarations.len(), 1);
    assert!(declarations[0].targets.is_empty());

    let cast = LegalAction {
        id: "cast:hand:emeritus:0".to_string(),
        kind: ActionKind::CastSpell,
        player_id: "player-0".to_string(),
        label: "Cast Emeritus of Ideation from hand".to_string(),
        card_instance_id: Some("emeritus".to_string()),
        payment_sources: Vec::new(),
        decisions: BTreeMap::from([
            (
                "castSourceZone".to_string(),
                Value::String("hand".to_string()),
            ),
            ("manaPayment".to_string(), Value::Array(Vec::new())),
        ]),
        targets: BTreeMap::new(),
        target_order: Vec::new(),
        attacker_id: None,
        blocker_id: None,
    };
    let mut provider = EmeritusDecisionProvider;
    engine
        .apply_priority_action(&cast, &mut provider)
        .expect("the permanent is cast");
    assert!(engine.state.stack[0].targets.is_empty());
    engine
        .resolve_top_stack(&mut provider)
        .expect("the permanent resolves");

    let permanent = engine.state.players[0]
        .battlefield
        .iter()
        .find(|card| card.instance_id == "emeritus")
        .expect("Emeritus is on the battlefield");
    assert_eq!(permanent.flags.get("prepared"), Some(&true));
    let prepared_copy = engine.state.players[0]
        .exile
        .iter()
        .find(|card| card.definition.name == "Ancestral Recall")
        .expect("the prepare spell copy is in exile");
    assert!(is_spell_copy(prepared_copy));
    let prepared_copy_id = prepared_copy.instance_id.clone();

    let prepared_casts = engine
        .legal_priority_actions(0)
        .into_iter()
        .filter(|action| {
            action.kind == ActionKind::CastSpell
                && action.card_instance_id.as_deref() == Some(prepared_copy_id.as_str())
        })
        .collect::<Vec<_>>();
    assert_eq!(prepared_casts.len(), 2);
    assert!(
        prepared_casts
            .iter()
            .all(|action| action.targets.contains_key("targetPlayer"))
    );
    let cast_copy = prepared_casts
        .into_iter()
        .find(|action| {
            action.targets.get("targetPlayer")
                == Some(&TargetRef::Player {
                    player_id: "player-0".to_string(),
                })
        })
        .expect("the prepare spell can target its controller");
    engine
        .apply_priority_action(&cast_copy, &mut provider)
        .expect("the prepare spell copy is cast");

    let permanent = engine.state.players[0]
        .battlefield
        .iter()
        .find(|card| card.instance_id == "emeritus")
        .expect("Emeritus remains on the battlefield");
    assert_eq!(permanent.flags.get("prepared"), Some(&false));
    assert!(
        engine.state.players[0]
            .exile
            .iter()
            .all(|card| card.instance_id != prepared_copy_id)
    );
    assert_eq!(
        engine
            .state
            .stack
            .last()
            .map(|object| object.card.definition.name.as_str()),
        Some("Ancestral Recall")
    );
}

/// Feature: Emeritus pays its optional eight-card attack instruction during trigger resolution.
#[test]
fn emeritus_attack_trigger_exiles_exactly_eight_then_prepares() {
    let mut engine = test_engine(2);
    let emeritus = test_instance("emeritus", emeritus_definition(true), "player-0");
    engine.state.players[0].battlefield = vec![emeritus];
    engine.state.players[0].graveyard = (0..8)
        .map(|index| {
            test_instance(
                &format!("graveyard-card-{index}"),
                test_definition(&format!("graveyard-card-{index}"), "Sorcery"),
                "player-0",
            )
        })
        .collect();

    engine
        .run_combat(&mut EmeritusDecisionProvider)
        .expect("combat and the attack trigger resolve");

    let permanent = engine.state.players[0]
        .battlefield
        .iter()
        .find(|card| card.instance_id == "emeritus")
        .expect("Emeritus survives combat");
    assert_eq!(permanent.flags.get("prepared"), Some(&true));
    assert!(engine.state.players[0].graveyard.is_empty());
    assert_eq!(
        engine.state.players[0]
            .exile
            .iter()
            .filter(|card| !is_spell_copy(card))
            .count(),
        8
    );
    assert!(
        engine.state.players[0]
            .exile
            .iter()
            .any(|card| card.definition.name == "Ancestral Recall")
    );
    assert!(
        engine
            .state
            .events
            .iter()
            .any(|event| event.kind == "cardsExiled")
    );
}

#[test]
fn prepared_spell_permission_follows_the_permanents_current_controller() {
    let mut engine = test_engine(2);
    let mut emeritus = test_instance("emeritus", emeritus_definition(false), "player-0");
    emeritus.flags.insert("prepared".to_string(), true);
    engine.state.players[0].battlefield = vec![emeritus];
    engine
        .ensure_prepared_spell_copy("emeritus")
        .expect("prepared spell copy is created");
    let copy_id = engine.state.players[0].exile[0].instance_id.clone();
    engine.state.players[0].mana_pool.push(FloatingMana {
        spend_restriction: None,
        symbol: "U".to_string(),
    });

    assert!(engine.legal_priority_actions(0).iter().any(|action| {
        action.kind == ActionKind::CastSpell
            && action.card_instance_id.as_deref() == Some(copy_id.as_str())
    }));

    let mut controlled = engine.state.players[0].battlefield.remove(0);
    controlled.controller = "player-1".to_string();
    engine.state.players[1].battlefield.push(controlled);
    engine.state.players[1].mana_pool.push(FloatingMana {
        spend_restriction: None,
        symbol: "U".to_string(),
    });

    assert!(engine.legal_priority_actions(0).iter().all(|action| {
        action.kind != ActionKind::CastSpell
            || action.card_instance_id.as_deref() != Some(copy_id.as_str())
    }));
    assert!(engine.legal_priority_actions(1).iter().any(|action| {
        action.kind == ActionKind::CastSpell
            && action.card_instance_id.as_deref() == Some(copy_id.as_str())
    }));
}

#[test]
fn prepared_spell_copy_ceases_while_phased_out_and_returns_on_phase_in() {
    let mut engine = test_engine(2);
    let mut emeritus = test_instance("emeritus", emeritus_definition(false), "player-0");
    emeritus.flags.insert("prepared".to_string(), true);
    engine.state.players[0].battlefield = vec![emeritus];
    engine
        .ensure_prepared_spell_copy("emeritus")
        .expect("prepared spell copy is created");
    assert_eq!(engine.state.players[0].exile.len(), 1);

    engine.phase_out_permanent("emeritus");
    assert!(engine.state.players[0].exile.is_empty());
    assert!(
        engine
            .state
            .permissions
            .iter()
            .all(|permission| { value_kind(permission) != Some("preparedSpellPermission") })
    );
    assert_eq!(
        engine.state.players[0].battlefield[0].flags.get("prepared"),
        Some(&true)
    );

    engine
        .start_turn(&mut RandomAi::seeded(1))
        .expect("prepared permanent phases in");
    assert_eq!(engine.state.players[0].exile.len(), 1);
    assert!(engine.state.permissions.iter().any(|permission| {
        value_kind(permission) == Some("preparedSpellPermission")
            && permission["sourceCardInstanceId"].as_str() == Some("emeritus")
    }));
}

