/// Feature: Tablet's milled card stays playable through the end step and expires in cleanup.
#[test]
fn tablet_permission_survives_until_the_current_turn_cleanup() {
    let mut engine = test_engine(2);
    let mut milled_instant = test_definition("milled-instant", "Instant");
    milled_instant.rules = vec![json!({
        "kind": "spellAbility",
        "source": { "kind": "self" },
        "effects": [{
            "kind": "gainLife",
            "player": { "kind": "abilityController" },
            "amount": 1
        }]
    })];
    let mut tablet_definition = test_definition("tablet-of-discovery", "Artifact");
    tablet_definition.rules = vec![json!({
        "kind": "triggeredAbility",
        "source": { "kind": "self" },
        "event": {
            "kind": "enterBattlefield",
            "object": { "kind": "self" }
        },
        "effects": [{
            "kind": "mill",
            "player": {
                "kind": "controllerOf",
                "object": { "kind": "self" }
            },
            "count": 1,
            "bind": "milledCards"
        }, {
            "kind": "grantPermission",
            "player": {
                "kind": "controllerOf",
                "object": { "kind": "self" }
            },
            "action": {
                "kind": "play",
                "card": {
                    "kind": "singleBoundObject",
                    "binding": "milledCards"
                },
                "normalTimingApplies": true,
                "normalCostsApply": true
            },
            "duration": { "kind": "untilEndOfCurrentTurn" }
        }]
    })];
    let tablet = test_instance("tablet", tablet_definition, "player-0");
    let trigger_rule = tablet.definition.rules[0].clone();
    engine.state.players[0].battlefield = vec![tablet.clone()];
    engine.state.players[0].library =
        vec![test_instance("milled-card", milled_instant, "player-0")];
    engine.put_triggered_ability_on_stack(&tablet, trigger_rule);
    engine
        .resolve_top_stack(&mut EmeritusDecisionProvider)
        .expect("Tablet's trigger resolves");

    let playable_from_graveyard = |engine: &GameEngine| {
        engine.legal_priority_actions(0).iter().any(|action| {
            action.kind == ActionKind::CastSpell
                && action.card_instance_id.as_deref() == Some("milled-card")
                && action.decisions["castSourceZone"] == "graveyard"
        })
    };
    assert!(playable_from_graveyard(&engine));

    engine.transition_to_step(GameStep::EndStep);
    assert!(playable_from_graveyard(&engine));
    assert_eq!(engine.state.permissions.len(), 1);

    engine
        .cleanup(&mut EmeritusDecisionProvider)
        .expect("cleanup expires current-turn permissions");
    assert!(engine.state.permissions.is_empty());
    assert!(!playable_from_graveyard(&engine));
}

