#[test]
fn conspire_taps_two_matching_creatures_and_copies_the_spell() {
    let mut engine = test_engine(2);
    engine.state.step = GameStep::PrecombatMain;
    let mut spell = test_definition("conspired-spell", "Sorcery");
    spell.mana_cost = "{R}".to_string();
    spell.rules = vec![
        json!({
            "kind": "keywordAbility",
            "source": { "kind": "self" },
            "ability": { "kind": "conspire" },
        }),
        json!({
            "kind": "spellAbility",
            "source": { "kind": "self" },
            "effects": [{
                "kind": "drawCards",
                "player": {
                    "kind": "controllerOf",
                    "object": { "kind": "self" },
                },
                "count": { "kind": "integer", "value": 1 },
            }],
        }),
    ];
    engine.state.players[0].hand = vec![test_instance("conspired-spell", spell, "player-0")];
    for instance_id in ["red-a", "red-b"] {
        let mut creature = test_definition(instance_id, "Creature - Goblin");
        creature.mana_cost = "{R}".to_string();
        engine.state.players[0]
            .battlefield
            .push(test_instance(instance_id, creature, "player-0"));
    }
    engine.state.players[0].mana_pool.push(FloatingMana {
        symbol: "R".to_string(),
        spend_restriction: None,
    });
    let action = engine
        .legal_priority_actions(0)
        .into_iter()
        .find(|action| {
            action.kind == ActionKind::CastSpell
                && action
                    .decisions
                    .get("conspireCreatures:0")
                    .and_then(Value::as_array)
                    .is_some_and(|creatures| creatures.len() == 2)
        })
        .expect("paid conspire cast is legal");

    engine
        .apply_priority_action(&action, &mut EmeritusDecisionProvider)
        .expect("conspired spell is cast");

    assert!(
        engine.state.players[0]
            .battlefield
            .iter()
            .all(|creature| creature.tapped)
    );
    assert_eq!(engine.state.stack.len(), 2);
    engine
        .resolve_top_stack(&mut EmeritusDecisionProvider)
        .expect("conspire trigger resolves");
    assert_eq!(
        engine
            .state
            .stack
            .iter()
            .filter(|object| object.ability_rule.is_none())
            .count(),
        2
    );
    assert!(
        engine
            .state
            .stack
            .iter()
            .any(|object| is_spell_copy(&object.card))
    );
}

