#[test]
fn earthbent_land_returns_tapped_after_it_is_exiled() {
    let mut engine = test_engine(2);
    let land = test_instance(
        "earthbend-land",
        test_definition("earthbend-land", "Land"),
        "player-0",
    );
    engine.state.players[0].battlefield = vec![land];
    let source = StackObject {
        id: "stack:earthbend".to_string(),
        controller: "player-0".to_string(),
        card: test_instance(
            "earthbend-source",
            test_definition("earthbend-source", "Sorcery"),
            "player-0",
        ),
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: None,
        ability_rule: None,
        decisions: BTreeMap::new(),
        targets: BTreeMap::from([(
            "earthbendLand".to_string(),
            TargetRef::Permanent {
                instance_id: "earthbend-land".to_string(),
            },
        )]),
    };
    engine
        .execute_effects(
            &json!([{
                "kind": "earthbend",
                "land": { "kind": "chosenTarget", "id": "earthbendLand" },
                "candidates": {
                    "kind": "permanents",
                    "controller": {
                        "kind": "controllerOf",
                        "object": { "kind": "self" },
                    },
                    "where": { "kind": "cardTypeContains", "value": "Land" },
                },
                "quantity": { "kind": "integer", "value": 3 },
            }]),
            &source,
            &mut BTreeMap::new(),
            &mut BTreeMap::new(),
            &mut EmeritusDecisionProvider,
        )
        .expect("earthbend resolves");
    engine
        .exile_permanent("earthbend-land")
        .expect("earthbent land is exiled");

    let returned = engine.state.players[0]
        .battlefield
        .iter()
        .find(|permanent| permanent.instance_id == "earthbend-land")
        .expect("earthbent land returned");
    assert!(returned.tapped);
    assert_eq!(returned.definition.type_line, "Land");
    assert!(engine.state.players[0].exile.is_empty());
}

