#[test]
fn flying_creature_cannot_be_blocked_without_flying_or_reach() {
    let engine = test_engine(2);
    let mut attacker_definition = test_definition("avatar-aang", "Creature - Avatar");
    attacker_definition.rules = vec![json!({
        "kind": "keywordAbilityGroup",
        "source": { "kind": "self" },
        "abilities": [
            { "kind": "flying" },
            {
                "kind": "firebending",
                "quantity": { "kind": "integer", "value": 2 },
            },
        ],
    })];
    let attacker = test_instance("avatar-aang", attacker_definition, "player-0");
    let blocker = test_instance(
        "ground-blocker",
        test_definition("ground-blocker", "Creature"),
        "player-1",
    );
    let mut reach_definition = test_definition("reach-blocker", "Creature");
    reach_definition.rules = vec![json!({
        "kind": "keywordAbility",
        "source": { "kind": "self" },
        "ability": { "kind": "reach" },
    })];
    let reach_blocker = test_instance("reach-blocker", reach_definition, "player-1");

    assert!(!engine.can_block(&blocker, &attacker));
    assert!(engine.can_block(&reach_blocker, &attacker));
}

