#[test]
fn boundless_realms_keeps_maximum_size_search_choices_available() {
    let mut engine = test_engine(2);
    engine.state.step = GameStep::PrecombatMain;
    engine.state.players[0].battlefield = (0..5)
        .map(|index| {
            let id = format!("controlled-land-{index}");
            test_instance(&id, test_definition(&id, "Land"), "player-0")
        })
        .collect();
    engine.state.players[0].library = (0..8)
        .map(|index| {
            let id = format!("basic-land-{index}");
            test_instance(&id, test_definition(&id, "Basic Land - Forest"), "player-0")
        })
        .chain(std::iter::once(test_instance(
            "nonbasic-land",
            test_definition("nonbasic-land", "Land"),
            "player-0",
        )))
        .collect();
    let mut boundless_realms = test_definition("boundless-realms", "Sorcery");
    boundless_realms.name = "Boundless Realms".to_string();
    boundless_realms.mana_cost = "{6}{G}".to_string();
    boundless_realms.rules = vec![json!({
        "kind": "spellAbility",
        "source": { "kind": "self" },
        "effects": [{
            "kind": "resolveSpellInstruction",
            "operation": "boundlessRealms"
        }]
    })];
    engine.state.players[0].hand = vec![test_instance(
        "boundless-realms",
        boundless_realms,
        "player-0",
    )];
    engine.state.players[0].mana_pool = ["G", "C", "C", "C", "C", "C", "C"]
        .into_iter()
        .map(|symbol| FloatingMana {
            symbol: symbol.to_string(),
            spend_restriction: None,
        })
        .collect();

    let action = engine
        .legal_priority_actions(0)
        .into_iter()
        .find(|action| {
            action.kind == ActionKind::CastSpell
                && action.card_instance_id.as_deref() == Some("boundless-realms")
        })
        .expect("Boundless Realms is castable with seven mana");
    engine
        .apply_priority_action(&action, &mut EmeritusDecisionProvider)
        .expect("Boundless Realms is put on the stack");
    engine
        .resolve_top_stack(&mut EmeritusDecisionProvider)
        .expect("Boundless Realms resolves");

    let fetched = engine.state.players[0]
        .battlefield
        .iter()
        .filter(|card| card.instance_id.starts_with("basic-land-"))
        .collect::<Vec<_>>();
    assert_eq!(fetched.len(), 5);
    assert!(fetched.iter().all(|card| card.tapped));
    assert_eq!(engine.state.players[0].library.len(), 4);
    assert!(
        engine.state.players[0]
            .library
            .iter()
            .any(|card| card.instance_id == "nonbasic-land")
    );
    assert_eq!(
        engine.state.players[0].graveyard[0].definition.name,
        "Boundless Realms"
    );
}

