#[test]
fn teamwork_uses_any_creature_combination_meeting_the_power_threshold() {
    let mut engine = test_engine(2);
    engine.state.step = GameStep::PrecombatMain;
    engine.state.active_player = 0;

    let mut spell = test_definition("teamwork-spell", "Sorcery");
    spell.mana_cost = "{0}".to_string();
    spell.rules = vec![
        json!({
            "kind": "spellAbility",
            "source": { "kind": "self" },
            "effects": [],
        }),
        json!({
            "kind": "keywordAbility",
            "source": { "kind": "self" },
            "ability": { "kind": "teamwork", "minimumPower": 2 },
        }),
    ];
    engine.state.players[0].hand = vec![test_instance("teamwork-spell", spell, "player-0")];

    let mut scout = test_definition("team-scout", "Creature - Scout");
    scout.power = Some("1".to_string());
    scout.toughness = Some("1".to_string());
    let mut hero = test_definition("team-hero", "Creature - Hero");
    hero.power = Some("2".to_string());
    hero.toughness = Some("2".to_string());
    engine.state.players[0].battlefield = vec![
        test_instance("team-scout", scout, "player-0"),
        test_instance("team-hero", hero, "player-0"),
    ];

    let action = engine
        .legal_priority_actions(0)
        .into_iter()
        .find(|action| {
            action.card_instance_id.as_deref() == Some("teamwork-spell")
                && action.decisions["teamworkCreatures:1"] == json!(["team-hero"])
        })
        .expect("the two-power creature can pay teamwork 2 by itself");
    assert!(action.payment_sources.is_empty());

    engine
        .apply_priority_action(&action, &mut EmeritusDecisionProvider)
        .expect("teamwork spell is cast");

    assert!(!engine.state.players[0].battlefield[0].tapped);
    assert!(engine.state.players[0].battlefield[1].tapped);
    assert!(engine.state.events.iter().any(|event| {
        event.kind == "permanentTapped" && event.card_instance_id.as_deref() == Some("team-hero")
    }));
}

#[test]
fn miracle_offers_the_first_drawn_card_at_its_alternative_cost() {
    let mut engine = test_engine(2);
    engine.state.step = GameStep::Draw;
    engine.state.active_player = 0;
    engine.state.players[0].hand.clear();
    engine.state.players[0].library.clear();
    engine.state.players[0].mana_pool = vec![FloatingMana {
        symbol: "W".to_string(),
        spend_restriction: None,
    }];

    let mut terminus = test_definition("terminus", "Sorcery");
    terminus.name = "Terminus".to_string();
    terminus.mana_cost = "{4}{W}{W}".to_string();
    terminus.rules = vec![
        json!({
            "kind": "spellAbility",
            "source": { "kind": "self" },
            "effects": [{
                "kind": "gainLife",
                "player": { "kind": "controllerOf", "object": { "kind": "self" } },
                "amount": { "kind": "integer", "value": 1 },
            }],
        }),
        json!({
            "kind": "keywordAbility",
            "source": { "kind": "self" },
            "ability": {
                "kind": "miracle",
                "cost": { "kind": "payMana", "manaCost": "{W}" },
            },
        }),
    ];
    engine.state.players[0]
        .library
        .push(test_instance("terminus", terminus, "player-0"));

    engine.draw_cards("player-0", 1).expect("card is drawn");
    assert!(engine.state.stack.iter().any(|object| {
        object
            .ability_rule
            .as_ref()
            .is_some_and(|rule| rule["effects"][0]["operation"] == "miracleCastDrawnCard")
    }));

    engine
        .resolve_top_stack(&mut CastSpellDecisionProvider)
        .expect("miracle trigger resolves");
    assert!(engine.state.players[0].hand.is_empty());
    assert!(engine.state.players[0].mana_pool.is_empty());
    assert!(
        engine.state.stack.iter().any(|object| {
            object.card.instance_id == "terminus" && object.ability_rule.is_none()
        })
    );
    assert!(engine.state.events.iter().any(|event| {
        event.kind == "cardRevealed"
            && event.card_instance_id.as_deref() == Some("terminus")
            && event.detail["reason"] == "miracle"
    }));
}

