#[test]
fn enduring_story_attack_tax_only_applies_after_the_story_is_gained() {
    let mut engine = test_engine(2);
    let mut tax_definition = test_definition("story-tax", "Legendary Creature - Dwarf");
    tax_definition.rules = vec![json!({
        "kind": "staticAbility",
        "source": { "kind": "self" },
        "activeWhile": {
            "kind": "inZone",
            "object": { "kind": "self" },
            "zone": { "kind": "battlefield" },
        },
        "modifiers": [{
            "kind": "attackTax",
            "protectedPlayer": { "kind": "abilityController" },
            "amount": { "kind": "integer", "value": 1 },
            "condition": {
                "kind": "hasEnduringStory",
                "player": { "kind": "abilityController" },
            },
        }],
    })];
    engine.state.players[0].battlefield =
        vec![test_instance("story-tax", tax_definition, "player-0")];
    let mut attacker = test_instance(
        "attacker",
        test_definition("attacker", "Creature - Soldier"),
        "player-1",
    );
    attacker.summoning_sick = false;
    engine.state.players[1].battlefield = vec![attacker];
    engine.state.active_player = 1;

    let attacks_player_zero = |actions: &[LegalAction]| {
        actions.iter().any(|action| {
            action.attacker_id.as_deref() == Some("attacker")
                && matches!(
                    action.targets.get("defender"),
                    Some(TargetRef::Player { player_id }) if player_id == "player-0"
                )
        })
    };
    assert!(attacks_player_zero(
        &engine.legal_attacker_actions(&BTreeSet::new())
    ));

    engine.state.rule_modifiers.push(json!({
        "kind": "enduringStory",
        "playerId": "player-0",
    }));
    assert!(!attacks_player_zero(
        &engine.legal_attacker_actions(&BTreeSet::new())
    ));

    engine.state.players[1].mana_pool.push(FloatingMana {
        symbol: "C".to_string(),
        spend_restriction: None,
    });
    assert!(attacks_player_zero(
        &engine.legal_attacker_actions(&BTreeSet::new())
    ));
}

#[test]
fn enduring_story_alternative_cost_only_applies_to_the_first_equip_activation() {
    let mut engine = test_engine(2);
    engine.state.step = GameStep::PrecombatMain;
    engine.state.active_player = 0;

    let mut story_definition = test_definition("story-smith", "Legendary Creature - Dwarf");
    story_definition.rules = vec![json!({
        "kind": "staticAbility",
        "source": { "kind": "self" },
        "activeWhile": {
            "kind": "inZone",
            "object": { "kind": "self" },
            "zone": { "kind": "battlefield" },
        },
        "modifiers": [{
            "kind": "firstActivatedAbilityAlternativeCost",
            "player": { "kind": "abilityController" },
            "abilityKind": "equip",
            "cost": { "kind": "payMana", "manaCost": "{0}" },
            "condition": {
                "kind": "hasEnduringStory",
                "player": { "kind": "abilityController" },
            },
        }],
    })];
    let mut equipment_definition = test_definition("training-axe", "Artifact - Equipment");
    equipment_definition.rules = vec![json!({
        "kind": "keywordAbility",
        "source": { "kind": "self" },
        "ability": {
            "kind": "equip",
            "costs": [{ "kind": "payMana", "manaCost": "{2}" }],
        },
    })];
    engine.state.players[0].battlefield = vec![
        test_instance("story-smith", story_definition, "player-0"),
        test_instance("training-axe", equipment_definition, "player-0"),
        test_instance(
            "equip-target",
            test_definition("equip-target", "Creature - Soldier"),
            "player-0",
        ),
    ];

    let equip_actions = |engine: &GameEngine| {
        engine
            .legal_priority_actions(0)
            .into_iter()
            .filter(|action| {
                action.kind == ActionKind::ActivateAbility
                    && action.card_instance_id.as_deref() == Some("training-axe")
            })
            .collect::<Vec<_>>()
    };
    assert!(equip_actions(&engine).is_empty());

    engine.state.rule_modifiers.push(json!({
        "kind": "enduringStory",
        "playerId": "player-0",
    }));
    let action = equip_actions(&engine)
        .into_iter()
        .find(|action| {
            action.targets.get("equipTarget")
                == Some(&TargetRef::Permanent {
                    instance_id: "equip-target".to_string(),
                })
                && action.decisions.get("firstActivatedAbilityAlternativeCost")
                    == Some(&Value::Bool(true))
        })
        .expect("the first equip activation has the free story alternative");
    assert!(action.payment_sources.is_empty());
    engine
        .apply_priority_action(&action, &mut RandomAi::seeded(1))
        .expect("activate equip for the alternative cost");
    assert!(engine.state.events.iter().any(|event| {
        event.turn_number == engine.state.turn_number
            && event.kind == "equipAbilityPutOnStack"
            && event.player_id.as_deref() == Some("player-0")
    }));
    engine
        .resolve_top_stack(&mut RandomAi::seeded(1))
        .expect("resolve the first equip activation");
    let (equipment_player, equipment_index) = engine
        .permanent_position("training-axe")
        .expect("equipment remains on the battlefield");
    assert_eq!(
        engine.state.players[equipment_player].battlefield[equipment_index]
            .attached_to
            .as_deref(),
        Some("equip-target")
    );

    engine.state.players[0].mana_pool.extend([
        FloatingMana {
            symbol: "C".to_string(),
            spend_restriction: None,
        },
        FloatingMana {
            symbol: "C".to_string(),
            spend_restriction: None,
        },
    ]);
    let later_actions = equip_actions(&engine);
    assert!(!later_actions.is_empty());
    assert!(later_actions.iter().all(|action| {
        action
            .decisions
            .get("firstActivatedAbilityAlternativeCost")
            .is_none()
    }));
}

#[test]
fn draw_threshold_combat_trigger_buffs_only_another_controlled_creature() {
    let parsed = parse_oracle_card(OracleCardParseRequest {
        card_name: "Test Toymaker".to_string(),
        type_line: "Creature - Dwarf Citizen".to_string(),
        mana_cost: Some("{2}{W}".to_string()),
        oracle_text: Some(
            "At the beginning of combat on your turn, if you've drawn two or more cards this turn, another target creature you control gets +3/+0 and gains first strike until end of turn."
                .to_string(),
        ),
        layout: None,
        faces: Vec::new(),
    });
    let rule = parsed.abilities[0]
        .rule
        .clone()
        .expect("draw-threshold combat trigger parses canonically");
    assert!(rule_is_executable(&rule));

    let mut source_definition = test_definition("test-toymaker", "Creature - Dwarf Citizen");
    source_definition.rules = vec![rule];
    let mut engine = test_engine(2);
    engine.state.active_player = 0;
    engine.state.players[0].battlefield = vec![
        test_instance("test-toymaker", source_definition, "player-0"),
        test_instance(
            "another-creature",
            test_definition("another-creature", "Creature - Soldier"),
            "player-0",
        ),
    ];

    engine.enqueue_step_triggers("beginCombat");
    assert!(engine.state.stack.is_empty());
    for _ in 0..2 {
        engine.record_event("cardDrawn", Some("player-0".to_string()), None, json!({}));
    }
    engine.enqueue_step_triggers("beginCombat");
    assert_eq!(engine.state.stack.len(), 1);
    engine
        .resolve_top_stack(&mut EmeritusDecisionProvider)
        .expect("resolve the draw-threshold combat trigger");

    let source = &engine.state.players[0].battlefield[0];
    let target = &engine.state.players[0].battlefield[1];
    assert_eq!(engine.current_power(source), 2);
    assert_eq!(engine.current_power(target), 5);
    assert!(engine.permanent_has_keyword(target, "firstStrike"));
}

#[test]
fn target_qualified_reduction_is_applied_after_spell_targets_are_declared() {
    let parsed = parse_oracle_card(OracleCardParseRequest {
        card_name: "Test Magnificent End".to_string(),
        type_line: "Instant".to_string(),
        mana_cost: Some("{3}{W}".to_string()),
        oracle_text: Some(
            "This spell costs {3} less to cast if it targets a tapped creature.\nTest Magnificent End deals 5 damage to target creature."
                .to_string(),
        ),
        layout: None,
        faces: Vec::new(),
    });
    let rules = parsed
        .abilities
        .iter()
        .map(|ability| {
            ability
                .rule
                .clone()
                .unwrap_or_else(|| panic!("unsupported ability: {}", ability.source.text))
        })
        .collect::<Vec<_>>();
    assert!(rules.iter().all(rule_is_executable));

    let mut spell_definition = test_definition("test-magnificent-end", "Instant");
    spell_definition.name = "Test Magnificent End".to_string();
    spell_definition.mana_cost = "{3}{W}".to_string();
    spell_definition.rules = rules;
    let mut tapped = test_instance(
        "tapped-target",
        test_definition("tapped-target", "Creature - Giant"),
        "player-1",
    );
    tapped.tapped = true;
    let untapped = test_instance(
        "untapped-target",
        test_definition("untapped-target", "Creature - Giant"),
        "player-1",
    );
    let mut engine = test_engine(2);
    engine.state.step = GameStep::PrecombatMain;
    engine.state.active_player = 0;
    engine.state.players[0].hand = vec![test_instance(
        "test-magnificent-end",
        spell_definition,
        "player-0",
    )];
    engine.state.players[0].mana_pool = vec![FloatingMana {
        symbol: "W".to_string(),
        spend_restriction: None,
    }];
    engine.state.players[1].battlefield = vec![tapped, untapped];

    let actions = engine
        .legal_priority_actions(0)
        .into_iter()
        .filter(|action| {
            action.kind == ActionKind::CastSpell
                && action.card_instance_id.as_deref() == Some("test-magnificent-end")
        })
        .collect::<Vec<_>>();
    assert!(!actions.is_empty());
    assert!(actions.iter().all(|action| {
        action.targets.get("targetPermanent")
            == Some(&TargetRef::Permanent {
                instance_id: "tapped-target".to_string(),
            })
    }));
    engine
        .apply_priority_action(&actions[0], &mut EmeritusDecisionProvider)
        .expect("cast using the target-qualified reduction");
    engine
        .resolve_top_stack(&mut EmeritusDecisionProvider)
        .expect("resolve the reduced spell");
    assert!(engine.permanent_position("tapped-target").is_none());
    assert!(engine.permanent_position("untapped-target").is_some());
}

#[test]
fn source_power_characteristic_counts_only_its_controllers_permanents() {
    let mut engine = test_engine(2);
    let mut garrison_definition = test_definition("esgaroth-garrison", "Creature - Human Soldier");
    garrison_definition.power = Some("*".to_string());
    garrison_definition.toughness = Some("4".to_string());
    garrison_definition.rules = vec![json!({
        "kind": "staticAbility",
        "source": { "kind": "self" },
        "activeWhile": {
            "kind": "inZone",
            "object": { "kind": "self" },
            "zone": { "kind": "battlefield" },
        },
        "modifiers": [{
            "kind": "modifyPowerToughness",
            "objects": { "kind": "self" },
            "power": {
                "kind": "countPermanents",
                "player": { "kind": "abilityController" },
                "where": { "kind": "cardTypeContains", "value": "Creature" },
            },
            "toughness": { "kind": "integer", "value": 0 },
        }],
    })];
    engine.state.players[0].battlefield.push(test_instance(
        "esgaroth-garrison",
        garrison_definition,
        "player-0",
    ));
    for index in 0..2 {
        engine.state.players[0].battlefield.push(test_instance(
            &format!("friendly-creature-{index}"),
            test_definition(&format!("friendly-creature-{index}"), "Creature - Test"),
            "player-0",
        ));
    }
    engine.state.players[1].battlefield.push(test_instance(
        "opposing-creature",
        test_definition("opposing-creature", "Creature - Test"),
        "player-1",
    ));

    let garrison = &engine.state.players[0].battlefield[0];
    assert_eq!(engine.current_power(garrison), 3);
    assert_eq!(engine.current_toughness(garrison), 4);
}

#[test]
fn opponent_second_draw_creates_a_token_and_grouped_players_each_draw() {
    let mut engine = test_engine(4);
    let mut splendor_definition = test_definition("gleaming-splendor", "Enchantment");
    splendor_definition.rules = vec![json!({
        "kind": "triggeredAbility",
        "source": { "kind": "self" },
        "event": {
            "kind": "cardDrawn",
            "opponentOfSourceController": true,
            "drawOrdinal": { "kind": "integer", "value": 2 },
        },
        "effects": [{
            "kind": "createTokens",
            "controller": { "kind": "abilityController" },
            "quantity": { "kind": "integer", "value": 1 },
            "token": { "kind": "namedToken", "name": "Treasure" },
        }],
    })];
    let splendor = test_instance("gleaming-splendor", splendor_definition, "player-0");
    engine.state.players[0].battlefield.push(splendor.clone());
    let mut provider = EmeritusDecisionProvider;
    engine
        .draw_cards_with_replacements("player-1", 1, &mut provider)
        .expect("opponent draws the first card");
    assert!(engine.state.stack.is_empty());
    engine
        .draw_cards_with_replacements("player-1", 1, &mut provider)
        .expect("opponent draws the second card");
    assert_eq!(engine.state.stack.len(), 1);
    engine
        .resolve_top_stack(&mut provider)
        .expect("the ordinal draw trigger resolves");
    assert!(
        engine.state.players[0]
            .battlefield
            .iter()
            .any(|permanent| { permanent.definition.name.eq_ignore_ascii_case("Treasure") })
    );

    let initial_hands = engine
        .state
        .players
        .iter()
        .map(|player| player.hand.len())
        .collect::<Vec<_>>();
    let stack_object = StackObject {
        id: "stack:grouped-player-draw".to_string(),
        controller: "player-0".to_string(),
        card: splendor,
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: Some("activatedAbility".to_string()),
        ability_rule: None,
        decisions: BTreeMap::new(),
        targets: BTreeMap::from([
            (
                "targetPlayers:0".to_string(),
                TargetRef::Player {
                    player_id: "player-0".to_string(),
                },
            ),
            (
                "targetPlayers:1".to_string(),
                TargetRef::Player {
                    player_id: "player-2".to_string(),
                },
            ),
        ]),
    };
    engine
        .execute_effect(
            &json!({
                "kind": "drawCards",
                "player": { "kind": "chosenTargets", "id": "targetPlayers" },
                "count": { "kind": "integer", "value": 1 },
            }),
            None,
            &stack_object,
            &mut BTreeMap::new(),
            &mut BTreeMap::new(),
            &mut provider,
        )
        .expect("each selected player draws");
    assert_eq!(engine.state.players[0].hand.len(), initial_hands[0] + 1);
    assert_eq!(engine.state.players[2].hand.len(), initial_hands[2] + 1);
    assert_eq!(engine.state.players[3].hand.len(), initial_hands[3]);
}

