#[test]
fn graveyard_activation_enforces_sorcery_timing_and_unearth_exile_rules() {
    let mut engine = test_engine(2);
    engine.state.step = GameStep::DeclareAttackers;
    let mut definition = test_definition("unearth-creature", "Creature - Zombie");
    definition.rules = vec![json!({
        "kind": "activatedAbility",
        "source": { "kind": "self" },
        "activationZone": "graveyard",
        "activationCondition": { "kind": "sorceryTiming" },
        "costs": [{ "kind": "payMana", "manaCost": "{1}{B}" }],
        "effects": [{
            "kind": "returnAbilitySourceFromGraveyard",
            "tapped": false,
            "grantKeywords": ["haste"],
            "exileAtNextEndStep": true,
            "exileIfLeavesBattlefield": true,
        }],
    })];
    engine.state.players[0].graveyard =
        vec![test_instance("unearth-creature", definition, "player-0")];
    engine.state.players[0].battlefield = vec![
        mana_source("swamp-a", "Basic Land - Swamp", "{B}", None),
        mana_source("swamp-b", "Basic Land - Swamp", "{B}", None),
    ];

    assert!(
        engine
            .legal_priority_actions(0)
            .iter()
            .all(|action| { action.card_instance_id.as_deref() != Some("unearth-creature") })
    );
    engine.state.step = GameStep::PrecombatMain;
    let action = engine
        .legal_priority_actions(0)
        .into_iter()
        .find(|action| {
            action.kind == ActionKind::ActivateAbility
                && action.card_instance_id.as_deref() == Some("unearth-creature")
        })
        .expect("unearth is offered at sorcery timing");
    engine
        .apply_priority_action(&action, &mut RandomAi::seeded(1))
        .expect("activate unearth");
    engine
        .resolve_top_stack(&mut RandomAi::seeded(1))
        .expect("resolve unearth");

    let unearthed = engine.state.players[0]
        .battlefield
        .iter()
        .find(|card| card.instance_id == "unearth-creature")
        .expect("source returned to the battlefield");
    assert!(engine.permanent_has_keyword(unearthed, "haste"));
    assert!(engine.state.rule_modifiers.iter().any(|modifier| {
        value_kind(modifier) == Some("exileAtEndStep")
            && modifier["cardInstanceId"] == "unearth-creature"
    }));

    engine
        .return_permanent_to_hand("unearth-creature")
        .expect("attempt to return unearthed permanent");
    assert!(
        engine.state.players[0]
            .hand
            .iter()
            .all(|card| card.instance_id != "unearth-creature")
    );
    assert!(
        engine.state.players[0]
            .exile
            .iter()
            .any(|card| card.instance_id == "unearth-creature")
    );
    assert!(engine.state.rule_modifiers.iter().all(|modifier| {
        modifier["cardInstanceId"].as_str() != Some("unearth-creature")
            || !matches!(
                value_kind(modifier),
                Some("exileIfLeavesBattlefield" | "exileAtEndStep")
            )
    }));
}

#[test]
fn conditional_combat_keywords_follow_turn_and_attacking_alone_state() {
    let mut engine = test_engine(2);
    let mut adventurer_definition = test_definition("adventurer", "Creature - Human Knight");
    adventurer_definition.rules = vec![json!({
        "kind": "staticAbility",
        "source": { "kind": "self" },
        "activeWhile": {
            "kind": "inZone",
            "object": { "kind": "self" },
            "zone": { "kind": "battlefield" },
        },
        "modifiers": [{
            "kind": "grantKeyword",
            "objects": { "kind": "self" },
            "keyword": "firstStrike",
            "condition": {
                "kind": "duringControllerTurn",
                "player": { "kind": "controllerOf", "object": { "kind": "self" } },
            },
        }],
    })];
    let mut malison_definition = test_definition("malison", "Creature - Snake Rogue");
    malison_definition.rules = vec![json!({
        "kind": "staticAbility",
        "source": { "kind": "self" },
        "activeWhile": {
            "kind": "inZone",
            "object": { "kind": "self" },
            "zone": { "kind": "battlefield" },
        },
        "modifiers": [{
            "kind": "cantBeBlocked",
            "object": { "kind": "self" },
            "condition": { "kind": "sourceAttackingAlone" },
        }],
    })];
    let adventurer = test_instance("adventurer", adventurer_definition, "player-0");
    let malison = test_instance("malison", malison_definition, "player-0");
    let companion = test_instance(
        "companion",
        test_definition("companion", "Creature - Soldier"),
        "player-0",
    );
    let blocker = test_instance(
        "blocker",
        test_definition("blocker", "Creature - Soldier"),
        "player-1",
    );
    engine.state.players[0].battlefield = vec![adventurer, malison, companion];
    engine.state.players[1].battlefield = vec![blocker.clone()];

    assert!(engine.permanent_has_keyword(&engine.state.players[0].battlefield[0], "firstStrike"));
    engine.state.active_player = 1;
    assert!(!engine.permanent_has_keyword(&engine.state.players[0].battlefield[0], "firstStrike"));

    engine.state.active_player = 0;
    engine.state.combat.attackers = vec![DeclaredAttacker {
        attacker_id: "malison".to_string(),
        defender: TargetRef::Player {
            player_id: "player-1".to_string(),
        },
        defending_player_id: "player-1".to_string(),
    }];
    assert!(!engine.can_block(&blocker, &engine.state.players[0].battlefield[1]));

    engine.state.combat.attackers.push(DeclaredAttacker {
        attacker_id: "companion".to_string(),
        defender: TargetRef::Player {
            player_id: "player-1".to_string(),
        },
        defending_player_id: "player-1".to_string(),
    });
    assert!(engine.can_block(&blocker, &engine.state.players[0].battlefield[1]));
}

#[test]
fn sokrates_can_activate_during_an_opponents_combat_and_prevent_damage() {
    let mut engine = test_engine(2);
    engine.state.active_player = 1;
    engine.state.step = GameStep::DeclareBlockers;
    let mut sokrates_definition = test_definition("sokrates", "Legendary Creature - Human Advisor");
    sokrates_definition.rules = vec![json!({
        "kind": "activatedAbility",
        "source": { "kind": "self" },
        "costs": [{ "kind": "tap", "object": { "kind": "self" } }],
        "declaration": {
            "kind": "castingDeclaration",
            "decisions": [{
                "kind": "chooseTargets",
                "id": "targetCreature",
                "minimum": 1,
                "maximum": 1,
                "candidates": {
                    "kind": "permanents",
                    "where": { "kind": "cardTypeContains", "value": "Creature" },
                },
            }],
        },
        "effects": [{
            "kind": "installSokratesDialogue",
            "permanent": { "kind": "chosenTarget", "id": "targetCreature" },
            "duration": { "kind": "untilEndOfCurrentTurn" },
        }],
    })];
    let mut sokrates = test_instance("sokrates", sokrates_definition, "player-0");
    sokrates.summoning_sick = false;
    let mut attacker_definition = test_definition("attacker", "Creature - Giant");
    attacker_definition.power = Some("6".to_string());
    attacker_definition.toughness = Some("6".to_string());
    let attacker = test_instance("attacker", attacker_definition, "player-1");
    engine.state.players[0].battlefield = vec![sokrates];
    engine.state.players[1].battlefield = vec![attacker];
    let action = engine
        .legal_priority_actions(0)
        .into_iter()
        .find(|action| {
            action.kind == ActionKind::ActivateAbility
                && action.card_instance_id.as_deref() == Some("sokrates")
                && action.targets.get("targetCreature")
                    == Some(&TargetRef::Permanent {
                        instance_id: "attacker".to_string(),
                    })
        })
        .expect("Sokrates activation is legal at instant speed during opponent combat");
    let hand_sizes = [
        engine.state.players[0].hand.len(),
        engine.state.players[1].hand.len(),
    ];

    engine
        .apply_priority_action(&action, &mut EmeritusDecisionProvider)
        .expect("Sokrates activates");
    engine
        .resolve_top_stack(&mut EmeritusDecisionProvider)
        .expect("Sokrates ability resolves");
    assert!(
        engine.state.rule_modifiers.iter().any(|modifier| {
            value_kind(modifier) == Some("sokratesDialogue")
                && modifier["cardInstanceId"] == "attacker"
        }),
        "Sokrates modifier was not installed on the selected attacker: {:?}",
        engine.state.rule_modifiers,
    );
    engine
        .deal_damage_amount_with_kind(
            TargetRef::Player {
                player_id: "player-0".to_string(),
            },
            6,
            "attacker",
            true,
        )
        .expect("combat damage event resolves");

    assert!(engine.state.players[0].battlefield[0].tapped);
    assert_eq!(engine.state.players[0].life, 20);
    assert_eq!(engine.state.players[0].hand.len(), hand_sizes[0] + 3);
    assert_eq!(engine.state.players[1].hand.len(), hand_sizes[1] + 3);
}

#[test]
fn class_level_requirement_controls_permanent_rules_and_intrinsic_keywords() {
    let engine = test_engine(2);
    let mut definition = test_definition("test-class", "Enchantment - Class");
    let level_two_keyword = json!({
        "kind": "keywordAbility",
        "source": { "kind": "self" },
        "minimumClassLevel": 2,
        "ability": { "kind": "flying" },
    });
    definition.rules = vec![level_two_keyword.clone()];
    let mut class = test_instance("test-class", definition, "player-0");

    assert!(!engine.rule_active_for_source(&class, &level_two_keyword));
    assert!(!engine.permanent_has_keyword(&class, "flying"));

    class.counters.insert("classLevel".to_string(), 2);
    assert!(engine.rule_active_for_source(&class, &level_two_keyword));
    assert!(engine.permanent_has_keyword(&class, "flying"));
}

#[test]
fn linked_exchange_targets_and_resolution_share_one_player() {
    let mut engine = test_engine(2);
    for player_index in 0..2 {
        let player_id = format!("player-{player_index}");
        let permanent_id = format!("artifact-{player_index}");
        engine.state.players[player_index]
            .battlefield
            .push(test_instance(
                &permanent_id,
                test_definition(&permanent_id, "Artifact"),
                &player_id,
            ));
        let graveyard_id = format!("graveyard-artifact-{player_index}");
        engine.state.players[player_index]
            .graveyard
            .push(test_instance(
                &graveyard_id,
                test_definition(&graveyard_id, "Artifact Creature"),
                &player_id,
            ));
    }
    let rule = json!({
        "kind": "activatedAbility",
        "source": { "kind": "self" },
        "costs": [{ "kind": "tap", "object": { "kind": "self" } }],
        "declaration": {
            "kind": "castingDeclaration",
            "decisions": [
                {
                    "kind": "chooseTargets",
                    "id": "targetPermanent",
                    "minimum": 1,
                    "maximum": 1,
                    "candidates": {
                        "kind": "permanents",
                        "where": { "kind": "cardTypeContains", "value": "Artifact" },
                    },
                },
                {
                    "kind": "chooseTargets",
                    "id": "targetGraveyardCard",
                    "minimum": 1,
                    "maximum": 1,
                    "candidates": {
                        "kind": "cards",
                        "zone": { "kind": "anyGraveyard" },
                        "where": { "kind": "cardTypeContains", "value": "Artifact" },
                    },
                    "selectionConstraint": {
                        "kind": "zoneOwnerMatchesTargetController",
                        "zone": "graveyard",
                        "targetId": "targetPermanent",
                    },
                },
            ],
        },
        "effects": [{
            "kind": "exchangePermanentWithGraveyardCard",
            "permanent": { "kind": "chosenTarget", "id": "targetPermanent" },
            "card": { "kind": "chosenTarget", "id": "targetGraveyardCard" },
        }],
    });
    let declarations = engine
        .declarations_for_activated_rule(&rule, "player-0", "exchange-source")
        .expect("linked target declarations are executable");
    assert_eq!(declarations.len(), 2);
    assert!(declarations.iter().all(|declaration| {
        let TargetRef::Permanent { instance_id } = &declaration.targets["targetPermanent"] else {
            return false;
        };
        let TargetRef::Card {
            instance_id: graveyard_id,
        } = &declaration.targets["targetGraveyardCard"]
        else {
            return false;
        };
        let (player_index, card_index) = engine.permanent_position(instance_id).unwrap();
        engine.state.players[player_index].battlefield[card_index].controller
            == engine
                .card_zone_owner_id(graveyard_id, "graveyard")
                .unwrap()
    }));

    let stack_object = StackObject {
        id: "stack:linked-exchange".to_string(),
        controller: "player-0".to_string(),
        card: test_instance(
            "exchange-source",
            test_definition("exchange-source", "Artifact Creature"),
            "player-0",
        ),
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: Some("activatedAbility".to_string()),
        ability_rule: Some(rule.clone()),
        decisions: BTreeMap::new(),
        targets: BTreeMap::from([
            (
                "targetPermanent".to_string(),
                TargetRef::Permanent {
                    instance_id: "artifact-1".to_string(),
                },
            ),
            (
                "targetGraveyardCard".to_string(),
                TargetRef::Card {
                    instance_id: "graveyard-artifact-1".to_string(),
                },
            ),
        ]),
    };
    engine
        .execute_effects(
            &rule["effects"],
            &stack_object,
            &mut BTreeMap::new(),
            &mut BTreeMap::new(),
            &mut EmeritusDecisionProvider,
        )
        .expect("the linked exchange resolves");

    assert!(
        engine.state.players[1]
            .graveyard
            .iter()
            .any(|card| card.instance_id == "artifact-1")
    );
    assert!(
        engine.state.players[1]
            .battlefield
            .iter()
            .any(|card| card.instance_id == "graveyard-artifact-1")
    );
}

#[test]
fn temporary_colored_hexproof_and_counter_prohibition_affect_live_rules() {
    let mut engine = test_engine(2);
    engine.state.players[0].battlefield.push(test_instance(
        "protected-creature",
        test_definition("protected-creature", "Creature"),
        "player-0",
    ));
    engine.state.players[0].library.push(test_instance(
        "drawn-card",
        test_definition("drawn-card", "Land"),
        "player-0",
    ));
    engine.record_event(
        "spellCast",
        Some("player-1".to_string()),
        Some("earlier-blue-spell".to_string()),
        json!({ "colors": ["U"] }),
    );
    let effects = json!([
        {
            "kind": "conditionalEffect",
            "condition": {
                "kind": "opponentCastSpellWithAnyColor",
                "colors": ["blue", "black"],
            },
            "then": [{
                "kind": "drawCards",
                "player": { "kind": "abilityController" },
                "count": { "kind": "integer", "value": 1 },
            }],
            "else": [],
        },
        {
            "kind": "installTemporaryCantBeCountered",
            "player": { "kind": "abilityController" },
            "duration": { "kind": "untilEndOfCurrentTurn" },
        },
        {
            "kind": "grantTemporaryHexproofFrom",
            "player": { "kind": "abilityController" },
            "includePlayer": true,
            "includeControlledPermanents": true,
            "from": ["blue", "black"],
            "duration": { "kind": "untilEndOfCurrentTurn" },
        },
    ]);
    let stack_object = StackObject {
        id: "stack:temporary-protection".to_string(),
        controller: "player-0".to_string(),
        card: test_instance(
            "protection-spell",
            test_definition("protection-spell", "Instant"),
            "player-0",
        ),
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: None,
        ability_rule: None,
        decisions: BTreeMap::new(),
        targets: BTreeMap::new(),
    };
    engine
        .execute_effects(
            &effects,
            &stack_object,
            &mut BTreeMap::new(),
            &mut BTreeMap::new(),
            &mut EmeritusDecisionProvider,
        )
        .expect("temporary protection effects resolve");

    assert!(
        engine.state.players[0]
            .hand
            .iter()
            .any(|card| card.instance_id == "drawn-card")
    );
    assert!(engine.controlled_spells_cant_be_countered("player-0"));

    let targeted_rule = json!({
        "kind": "spellAbility",
        "source": { "kind": "self" },
        "declaration": {
            "kind": "castingDeclaration",
            "decisions": [{
                "kind": "chooseTargets",
                "id": "targetPermanent",
                "minimum": 1,
                "maximum": 1,
                "candidates": {
                    "kind": "permanents",
                    "where": { "kind": "cardTypeContains", "value": "Creature" },
                },
            }],
        },
        "effects": [{
            "kind": "destroyPermanent",
            "permanent": { "kind": "chosenTarget", "id": "targetPermanent" },
        }],
    });
    let mut blue_spell = test_definition("blue-spell", "Instant");
    blue_spell.mana_cost = "{U}".to_string();
    blue_spell.rules = vec![targeted_rule.clone()];
    assert!(
        engine
            .declarations_for_card(&blue_spell, "player-1")
            .expect("blue spell declarations evaluate")
            .is_empty()
    );

    let mut red_spell = test_definition("red-spell", "Instant");
    red_spell.mana_cost = "{R}".to_string();
    red_spell.rules = vec![targeted_rule];
    assert_eq!(
        engine
            .declarations_for_card(&red_spell, "player-1")
            .expect("red spell declarations evaluate")
            .len(),
        1
    );
}

