#[test]
fn parsed_damage_then_death_replacement_exiles_the_lethally_damaged_target() {
    let parsed = parse_oracle_card(OracleCardParseRequest {
        card_name: "Pinecone Strike".to_string(),
        type_line: "Sorcery".to_string(),
        mana_cost: Some("{1}{R}".to_string()),
        oracle_text: Some(
            "Choose one or both —\n• Pinecone Strike deals 3 damage to target creature. If that creature would die this turn, exile it instead.\n• Destroy target artifact token."
                .to_string(),
        ),
        layout: None,
        faces: Vec::new(),
    });
    let rule = parsed.abilities[0]
        .rule
        .clone()
        .expect("the modal spell parses");
    assert!(rule_is_executable(&rule));
    let first_mode_effects = rule["effects"][0]["then"]
        .as_array()
        .expect("the first mode has effects");
    assert_eq!(first_mode_effects.len(), 2);

    let victim = test_instance(
        "pinecone-victim",
        test_definition("pinecone-victim", "Creature"),
        "player-1",
    );
    let source = test_instance(
        "pinecone-strike",
        test_definition("pinecone-strike", "Sorcery"),
        "player-0",
    );
    let stack_object = StackObject {
        id: "stack:pinecone-strike".to_string(),
        controller: "player-0".to_string(),
        card: source,
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: Some("spellAbility".to_string()),
        ability_rule: Some(rule.clone()),
        decisions: BTreeMap::new(),
        targets: BTreeMap::from([(
            "mode1:targetPermanent".to_string(),
            TargetRef::Permanent {
                instance_id: "pinecone-victim".to_string(),
            },
        )]),
    };
    let mut engine = test_engine(2);
    engine.state.players[1].battlefield.push(victim);
    for effect in first_mode_effects {
        engine
            .execute_effect(
                effect,
                None,
                &stack_object,
                &mut BTreeMap::new(),
                &mut BTreeMap::new(),
                &mut EmeritusDecisionProvider,
            )
            .expect("each linked mode effect executes");
    }
    engine.check_state_based_actions();

    assert!(engine.state.players[1].battlefield.is_empty());
    assert_eq!(engine.state.players[1].exile.len(), 1);
    assert_eq!(
        engine.state.players[1].exile[0].instance_id,
        "pinecone-victim"
    );
}

