    let reduction_rule = parsed
        .abilities
        .iter()
        .filter_map(|ability| ability.rule.as_ref())
        .find(|rule| value_kind(rule) == Some("staticAbility"))
        .cloned()
        .expect("the casting reduction parses");
    let trigger_rule = parsed
        .abilities
        .iter()
        .filter_map(|ability| ability.rule.as_ref())
        .find(|rule| value_kind(rule) == Some("triggeredAbility"))
        .cloned()
        .expect("the combat trigger parses");

    let mut engine = test_engine(3);
