#[test]
fn greatest_toughness_draw_then_hand_creatures_enter_together() {
    let parsed = parse_oracle_card(OracleCardParseRequest {
        card_name: "Test March".to_string(),
        type_line: "Sorcery".to_string(),
        mana_cost: Some("{6}{G}{G}".to_string()),
        oracle_text: Some(
            "Draw cards equal to the greatest toughness among creatures you control, then put any number of creature cards from your hand onto the battlefield."
                .to_string(),
        ),
        layout: None,
        faces: Vec::new(),
    });
    let rule = parsed.abilities[0]
        .rule
        .clone()
        .expect("the draw and hand-entry spell parses");
    let mut small_definition = test_definition("small-tree", "Creature - Treefolk");
    small_definition.toughness = Some("2".to_string());
    let mut large_definition = test_definition("large-tree", "Creature - Treefolk");
    large_definition.toughness = Some("5".to_string());
    let hand_creature_one = test_instance(
        "hand-creature-one",
        test_definition("hand-creature-one", "Creature - Elf"),
        "player-0",
    );
    let hand_creature_two = test_instance(
        "hand-creature-two",
        test_definition("hand-creature-two", "Artifact Creature - Golem"),
        "player-0",
    );
    let hand_artifact = test_instance(
        "hand-artifact",
        test_definition("hand-artifact", "Artifact"),
        "player-0",
    );
    let source = test_instance(
        "test-march",
        test_definition("test-march", "Sorcery"),
        "player-0",
    );
    let stack_object = StackObject {
        id: "stack:test-march".to_string(),
        controller: "player-0".to_string(),
        card: source,
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: Some("spellAbility".to_string()),
        ability_rule: Some(rule.clone()),
        decisions: BTreeMap::new(),
        targets: BTreeMap::new(),
    };
    let mut engine = test_engine(2);
    engine.state.players[0].battlefield = vec![
        test_instance("small-tree", small_definition, "player-0"),
        test_instance("large-tree", large_definition, "player-0"),
    ];
    engine.state.players[0]
        .hand
        .extend([hand_creature_one, hand_creature_two, hand_artifact]);
    let initial_hand = engine.state.players[0].hand.len();

    engine
        .execute_effects(
            &rule["effects"],
            &stack_object,
            &mut BTreeMap::new(),
            &mut BTreeMap::new(),
            &mut EmeritusDecisionProvider,
        )
        .expect("the draw and simultaneous hand entry resolve");

    assert_eq!(engine.state.players[0].hand.len(), initial_hand + 5 - 2);
    assert!(engine.permanent_position("hand-creature-one").is_some());
    assert!(engine.permanent_position("hand-creature-two").is_some());
    assert!(
        engine.state.players[0]
            .hand
            .iter()
            .any(|card| card.instance_id == "hand-artifact")
    );
}

#[test]
fn exile_until_matching_card_can_be_cast_from_another_players_exile() {
    let parsed = parse_oracle_card(OracleCardParseRequest {
        card_name: "Test Footman".to_string(),
        type_line: "Legendary Creature - Human Advisor".to_string(),
        mana_cost: Some("{2}{U}{B}".to_string()),
        oracle_text: Some(
            "Whenever Test Footman deals combat damage to a player, that player exiles cards from the top of their library until they exile an instant or sorcery card. You may cast that card without paying its mana cost. Then that player puts the exiled cards that weren't cast this way on the bottom of their library in a random order."
                .to_string(),
        ),
        layout: None,
        faces: Vec::new(),
    });
    let rule = parsed.abilities[0]
        .rule
        .clone()
        .expect("the exile-until trigger parses");
    assert!(rule_is_executable(&rule));

    let mut matching_definition = test_definition("matching-instant", "Instant");
    matching_definition.mana_cost = "{2}{U}".to_string();
    matching_definition.rules = vec![json!({
        "kind": "spellAbility",
        "source": { "kind": "self" },
        "effects": [{
            "kind": "drawCards",
            "player": { "kind": "controllerOf", "object": { "kind": "self" } },
            "count": { "kind": "integer", "value": 1 },
        }],
    })];
    let matching = test_instance("matching-instant", matching_definition, "player-1");
    let skipped_land = test_instance(
        "skipped-land",
        test_definition("skipped-land", "Basic Land - Forest"),
        "player-1",
    );
    let skipped_artifact = test_instance(
        "skipped-artifact",
        test_definition("skipped-artifact", "Artifact"),
        "player-1",
    );

    let source = test_instance(
        "test-footman",
        test_definition("test-footman", "Legendary Creature - Human Advisor"),
        "player-0",
    );
    let stack_object = StackObject {
        id: "stack:test-footman".to_string(),
        controller: "player-0".to_string(),
        card: source,
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: Some("triggeredAbility".to_string()),
        ability_rule: Some(rule.clone()),
        decisions: BTreeMap::from([(
            "triggeringPlayerId".to_string(),
            Value::String("player-1".to_string()),
        )]),
        targets: BTreeMap::new(),
    };
    let mut engine = test_engine(2);
    engine.state.players[1].library = vec![matching, skipped_land, skipped_artifact];
    let mut bindings = BTreeMap::new();
    let mut decisions = stack_object.decisions.clone();

    engine
        .execute_effects(
            &rule["effects"],
            &stack_object,
            &mut bindings,
            &mut decisions,
            &mut CastSpellDecisionProvider,
        )
        .expect("the matching opponent-owned card is cast and the remainder is returned");

    assert!(engine.state.stack.iter().any(|object| {
        object.card.instance_id == "matching-instant" && object.controller == "player-0"
    }));
    assert!(engine.state.players[1].exile.is_empty());
    let returned = engine.state.players[1]
        .library
        .iter()
        .map(|card| card.instance_id.as_str())
        .collect::<BTreeSet<_>>();
    assert_eq!(
        returned,
        BTreeSet::from(["skipped-artifact", "skipped-land"])
    );
}

#[test]
fn opponent_mill_reflexive_copy_targets_by_owner_and_triggering_mana_value() {
    let parsed = parse_oracle_card(OracleCardParseRequest {
        card_name: "Test Many Colors".to_string(),
        type_line: "Legendary Creature - Avatar Wizard".to_string(),
        mana_cost: Some("{3}{W}{U}{B}".to_string()),
        oracle_text: Some(
            "Whenever you cast your second spell each turn, each opponent mills two cards. When one or more cards are milled this way, exile target enchantment, instant, or sorcery card with equal or lesser mana value than that spell from an opponent's graveyard. Copy the exiled card. You may cast the copy without paying its mana cost."
                .to_string(),
        ),
        layout: None,
        faces: Vec::new(),
    });
    let rule = parsed.abilities[0]
        .rule
        .clone()
        .expect("the mill and reflexive copy trigger parses");
    assert!(rule_is_executable(&rule));

    let mut eligible_definition = test_definition("eligible-instant", "Instant");
    eligible_definition.mana_cost = "{2}{U}".to_string();
    eligible_definition.rules = vec![json!({
        "kind": "spellAbility",
        "source": { "kind": "self" },
        "effects": [{
            "kind": "drawCards",
            "player": { "kind": "controllerOf", "object": { "kind": "self" } },
            "count": { "kind": "integer", "value": 1 },
        }],
    })];
    let mut expensive_definition = test_definition("expensive-sorcery", "Sorcery");
    expensive_definition.mana_cost = "{5}{B}".to_string();
    let mut own_definition = test_definition("own-instant", "Instant");
    own_definition.mana_cost = "{U}".to_string();

    let source = test_instance(
        "test-many-colors",
        test_definition("test-many-colors", "Legendary Creature - Avatar Wizard"),
        "player-0",
    );
    let stack_object = StackObject {
        id: "stack:test-many-colors".to_string(),
        controller: "player-0".to_string(),
        card: source,
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: Some("triggeredAbility".to_string()),
        ability_rule: Some(rule.clone()),
        decisions: BTreeMap::from([("triggeringSpellManaValue".to_string(), Value::from(4))]),
        targets: BTreeMap::new(),
    };
    let mut engine = test_engine(3);
    engine.state.players[0].graveyard =
        vec![test_instance("own-instant", own_definition, "player-0")];
    engine.state.players[1].library = vec![
        test_instance("eligible-instant", eligible_definition, "player-1"),
        test_instance(
            "milled-land-one",
            test_definition("milled-land-one", "Basic Land - Island"),
            "player-1",
        ),
    ];
    engine.state.players[2].library = vec![
        test_instance("expensive-sorcery", expensive_definition, "player-2"),
        test_instance(
            "milled-land-two",
            test_definition("milled-land-two", "Basic Land - Swamp"),
            "player-2",
        ),
    ];
    let mut bindings = BTreeMap::new();
    let mut decisions = stack_object.decisions.clone();
    engine
        .execute_effects(
            &rule["effects"],
            &stack_object,
            &mut bindings,
            &mut decisions,
            &mut CastSpellDecisionProvider,
        )
        .expect("the opponents mill and the reflexive target is declared");
    assert!(engine.state.players[1].library.is_empty());
    assert!(engine.state.players[2].library.is_empty());
    assert_eq!(engine.state.players[0].graveyard.len(), 1);
    assert_eq!(engine.state.stack.len(), 1);
    assert_eq!(
        engine.state.stack[0].targets["graveyardCardToCopy"],
        TargetRef::Card {
            instance_id: "eligible-instant".to_string(),
        }
    );

    engine
        .resolve_top_stack(&mut CastSpellDecisionProvider)
        .expect("the reflexive ability exiles, copies, and casts the eligible card");
    assert!(
        engine.state.players[1]
            .exile
            .iter()
            .any(|card| card.instance_id == "eligible-instant")
    );
    assert!(
        engine.state.players[2]
            .graveyard
            .iter()
            .any(|card| card.instance_id == "expensive-sorcery")
    );
    let copied_spell = engine
        .state
        .stack
        .iter()
        .find(|object| object.card.flags.get("isSpellCopy") == Some(&true))
        .expect("the copied instant is cast as a spell copy");
    assert_eq!(copied_spell.controller, "player-0");
    assert_eq!(copied_spell.card.definition.name, "eligible-instant");
    assert!(
        engine.state.players[0]
            .exile
            .iter()
            .all(|card| !card.instance_id.starts_with("copy:card:"))
    );
}

#[test]
fn final_saga_chapter_resolution_triggers_observer_and_puts_revealed_saga_in_play() {
    let parsed = parse_oracle_card(OracleCardParseRequest {
        card_name: "Test Storyteller".to_string(),
        type_line: "Legendary Creature - Bard".to_string(),
        mana_cost: Some("{W}{U}{B}{R}{G}".to_string()),
        oracle_text: Some(
            "Whenever the final chapter ability of a Saga you control resolves, reveal cards from the top of your library until you reveal a Saga card. Put that card onto the battlefield and the rest on the bottom of your library in a random order. This ability triggers only once each turn."
                .to_string(),
        ),
        layout: None,
        faces: Vec::new(),
    });
    let observer_rule = parsed.abilities[0]
        .rule
        .clone()
        .expect("the final chapter observer parses");
    assert!(rule_is_executable(&observer_rule));

    let chapter_rule = |chapter| {
        json!({
            "kind": "triggeredAbility",
            "source": { "kind": "self" },
            "event": {
                "kind": "sagaChapterReached",
                "object": { "kind": "self" },
                "chapters": [{ "kind": "integer", "value": chapter }],
            },
            "effects": [{
                "kind": "gainLife",
                "player": { "kind": "controllerOf", "object": { "kind": "self" } },
                "amount": { "kind": "integer", "value": 1 },
            }],
        })
    };
    let mut saga_definition = test_definition("test-ending", "Enchantment - Saga");
    saga_definition.rules = vec![chapter_rule(1), chapter_rule(2)];
    assert!(!saga_chapter_rule_is_final(
        &saga_definition,
        &saga_definition.rules[0]
    ));
    assert!(saga_chapter_rule_is_final(
        &saga_definition,
        &saga_definition.rules[1]
    ));

    let mut observer_definition = test_definition("test-storyteller", "Legendary Creature - Bard");
    observer_definition.rules = vec![observer_rule];
    let observer = test_instance("test-storyteller", observer_definition, "player-0");
    let saga = test_instance("test-ending", saga_definition.clone(), "player-0");
    let mut engine = test_engine(2);
    engine.state.players[0].battlefield = vec![observer, saga.clone()];
    engine.state.players[0].library = vec![
        test_instance(
            "revealed-saga",
            test_definition("revealed-saga", "Enchantment - Saga"),
            "player-0",
        ),
        test_instance(
            "revealed-land",
            test_definition("revealed-land", "Basic Land - Forest"),
            "player-0",
        ),
    ];
    engine.state.stack.push(StackObject {
        id: "stack:final-chapter".to_string(),
        controller: "player-0".to_string(),
        card: saga,
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: Some("triggeredAbility".to_string()),
        ability_rule: Some(saga_definition.rules[1].clone()),
        decisions: BTreeMap::new(),
        targets: BTreeMap::new(),
    });

    engine
        .resolve_top_stack(&mut EmeritusDecisionProvider)
        .expect("the final chapter resolves and queues the observer");
    assert_eq!(engine.state.stack.len(), 1);
    assert_eq!(
        engine.state.stack[0].ability_rule.as_ref().unwrap()["event"]["kind"],
        "sagaFinalChapterAbilityResolved"
    );
    engine
        .resolve_top_stack(&mut EmeritusDecisionProvider)
        .expect("the observer reveals through a land and puts the Saga in play");
    assert!(
        engine.state.players[0]
            .battlefield
            .iter()
            .any(|card| card.instance_id == "revealed-saga")
    );
    assert_eq!(engine.state.players[0].library.len(), 1);
    assert_eq!(
        engine.state.players[0].library[0].instance_id,
        "revealed-land"
    );
}

#[test]
fn equipped_attack_alternates_tokens_and_counters_from_trigger_context() {
    let parse_trigger = |name: &str, oracle_text: &str| {
        parse_oracle_card(OracleCardParseRequest {
            card_name: name.to_string(),
            type_line: "Legendary Artifact - Equipment".to_string(),
            mana_cost: Some("{3}".to_string()),
            oracle_text: Some(oracle_text.to_string()),
            layout: None,
            faces: Vec::new(),
        })
        .abilities[0]
            .rule
            .clone()
            .expect("the Equipment attack trigger parses")
    };
    let spirit_rule = parse_trigger(
        "Test Flame",
        "Whenever equipped creature attacks, create two tapped 1/1 white Spirit creature tokens with flying. If that creature is legendary, instead create two of those tokens that are tapped and attacking.",
    );
    assert!(rule_is_executable(&spirit_rule));

    let run_spirit_trigger = |legendary: bool| {
        let mut engine = test_engine(2);
        let creature_type = if legendary {
            "Legendary Creature - Human Warrior"
        } else {
            "Creature - Human Warrior"
        };
        let attacker = test_instance(
            "equipped-attacker",
            test_definition("equipped-attacker", creature_type),
            "player-0",
        );
        let mut equipment = test_instance(
            "test-flame",
            test_definition("test-flame", "Legendary Artifact - Equipment"),
            "player-0",
        );
        equipment.attached_to = Some(attacker.instance_id.clone());
        engine.state.players[0].battlefield = vec![attacker, equipment.clone()];
        engine.state.combat.attackers = vec![DeclaredAttacker {
            attacker_id: "equipped-attacker".to_string(),
            defender: TargetRef::Player {
                player_id: "player-1".to_string(),
            },
            defending_player_id: "player-1".to_string(),
        }];
        let stack_object = StackObject {
            id: format!("stack:spirit:{legendary}"),
            controller: "player-0".to_string(),
            card: equipment,
            cant_be_countered: false,
            exile_on_leave_stack: false,
            ability_kind: Some("triggeredAbility".to_string()),
            ability_rule: Some(spirit_rule.clone()),
            decisions: BTreeMap::from([(
                "triggeringPermanentId".to_string(),
                Value::String("equipped-attacker".to_string()),
            )]),
            targets: BTreeMap::new(),
        };
        let mut bindings = BTreeMap::new();
        let mut decisions = stack_object.decisions.clone();
        engine
            .execute_effects(
                &spirit_rule["effects"],
                &stack_object,
                &mut bindings,
                &mut decisions,
                &mut EmeritusDecisionProvider,
            )
            .expect("the conditional Spirit creation resolves");
        engine
    };
    let legendary_engine = run_spirit_trigger(true);
    let legendary_tokens = legendary_engine.state.players[0]
        .battlefield
        .iter()
        .filter(|card| card.definition.is_token)
        .collect::<Vec<_>>();
    assert_eq!(legendary_tokens.len(), 2);
    assert!(legendary_tokens.iter().all(|token| token.tapped));
    assert!(
        legendary_tokens
            .iter()
            .all(|token| token.flags.get("attacking") == Some(&true))
    );
    assert_eq!(legendary_engine.state.combat.attackers.len(), 3);
    assert!(
        legendary_engine.state.combat.attackers[1..]
            .iter()
            .all(|assignment| assignment.defending_player_id == "player-1")
    );

    let ordinary_engine = run_spirit_trigger(false);
    let ordinary_tokens = ordinary_engine.state.players[0]
        .battlefield
        .iter()
        .filter(|card| card.definition.is_token)
        .collect::<Vec<_>>();
    assert_eq!(ordinary_tokens.len(), 2);
    assert!(ordinary_tokens.iter().all(|token| token.tapped));
    assert!(
        ordinary_tokens
            .iter()
            .all(|token| token.flags.get("attacking").is_none())
    );
    assert_eq!(ordinary_engine.state.combat.attackers.len(), 1);

    let counter_rule = parse_trigger(
        "Test Reforged",
        "Whenever equipped creature attacks, put a +1/+1 counter on each creature you control. If you have the city's blessing, put two +1/+1 counters on each creature you control instead.",
    );
    assert!(rule_is_executable(&counter_rule));
    let run_counter_trigger = |has_blessing: bool| {
        let mut engine = test_engine(2);
        engine.state.players[0].battlefield = vec![
            test_instance(
                "first-creature",
                test_definition("first-creature", "Creature - Human"),
                "player-0",
            ),
            test_instance(
                "second-creature",
                test_definition("second-creature", "Creature - Elf"),
                "player-0",
            ),
        ];
        if has_blessing {
            engine.state.rule_modifiers.push(json!({
                "kind": "cityBlessing",
                "playerId": "player-0",
            }));
        }
        let stack_object = StackObject {
            id: format!("stack:counters:{has_blessing}"),
            controller: "player-0".to_string(),
            card: test_instance(
                "test-reforged",
                test_definition("test-reforged", "Legendary Artifact - Equipment"),
                "player-0",
            ),
            cant_be_countered: false,
            exile_on_leave_stack: false,
            ability_kind: Some("triggeredAbility".to_string()),
            ability_rule: Some(counter_rule.clone()),
            decisions: BTreeMap::new(),
            targets: BTreeMap::new(),
        };
        let mut bindings = BTreeMap::new();
        let mut decisions = BTreeMap::new();
        engine
            .execute_effects(
                &counter_rule["effects"],
                &stack_object,
                &mut bindings,
                &mut decisions,
                &mut EmeritusDecisionProvider,
            )
            .expect("the conditional counter quantity resolves");
        engine
    };
    let unblessed = run_counter_trigger(false);
    assert!(
        unblessed.state.players[0]
            .battlefield
            .iter()
            .all(|creature| creature.counters.get("+1/+1") == Some(&1))
    );
    let blessed = run_counter_trigger(true);
    assert!(
        blessed.state.players[0]
            .battlefield
            .iter()
            .all(|creature| creature.counters.get("+1/+1") == Some(&2))
    );
}

#[test]
fn player_protection_entry_trigger_requires_the_source_to_have_been_cast() {
    let parsed = parse_oracle_card(OracleCardParseRequest {
        card_name: "Test Relic".to_string(),
        type_line: "Legendary Artifact".to_string(),
        mana_cost: Some("{4}".to_string()),
        oracle_text: Some(
            "When Test Relic enters, if you cast it, you gain protection from everything until your next turn."
                .to_string(),
        ),
        layout: None,
        faces: Vec::new(),
    });
    let rule = parsed.abilities[0]
        .rule
        .clone()
        .expect("the conditional entry trigger parses");
    assert!(rule_is_executable(&rule));

    let resolve = |was_cast: bool| {
        let mut engine = test_engine(2);
        let mut source = test_instance(
            "test-relic",
            test_definition("test-relic", "Legendary Artifact"),
            "player-0",
        );
        if was_cast {
            source.flags.insert("wasCast".to_string(), true);
        }
        engine.state.stack.push(StackObject {
            id: format!("stack:protection:{was_cast}"),
            controller: "player-0".to_string(),
            card: source,
            cant_be_countered: false,
            exile_on_leave_stack: false,
            ability_kind: Some("triggeredAbility".to_string()),
            ability_rule: Some(rule.clone()),
            decisions: BTreeMap::new(),
            targets: BTreeMap::new(),
        });
        engine
            .resolve_top_stack(&mut EmeritusDecisionProvider)
            .expect("the conditional entry trigger resolves");
        engine
    };

    let cast_engine = resolve(true);
    assert!(cast_engine.state.rule_modifiers.iter().any(|modifier| {
        value_kind(modifier) == Some("protectionFromEverything")
            && modifier["playerId"] == "player-0"
            && modifier["expiresAtTurnStart"] == "player-0"
    }));
    let uncast_engine = resolve(false);
    assert!(
        uncast_engine
            .state
            .rule_modifiers
            .iter()
            .all(|modifier| value_kind(modifier) != Some("protectionFromEverything"))
    );
}

#[test]
fn counter_linked_characteristics_follow_the_target_counter() {
    let parsed = parse_oracle_card(OracleCardParseRequest {
        card_name: "Test Fortress".to_string(),
        type_line: "Legendary Land".to_string(),
        mana_cost: None,
        oracle_text: Some(
            "{3}{B}, {T}: Put a shadow counter on target creature. For as long as that creature has a shadow counter on it, it's a Wraith in addition to its other types. (A creature with shadow can block or be blocked by only creatures with shadow.)"
                .to_string(),
        ),
        layout: None,
        faces: Vec::new(),
    });
    let rule = parsed.abilities[0]
        .rule
        .clone()
        .expect("the counter-linked activated ability parses");
    assert!(rule_is_executable(&rule));

    let source = test_instance(
        "test-fortress",
        test_definition("test-fortress", "Legendary Land"),
        "player-0",
    );
    let target = test_instance(
        "shadow-target",
        test_definition("shadow-target", "Creature - Human"),
        "player-1",
    );
    let stack_object = StackObject {
        id: "stack:shadow-counter".to_string(),
        controller: "player-0".to_string(),
        card: source,
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: Some("activatedAbility".to_string()),
        ability_rule: Some(rule.clone()),
        decisions: BTreeMap::new(),
        targets: BTreeMap::from([(
            "targetPermanent".to_string(),
            TargetRef::Permanent {
                instance_id: target.instance_id.clone(),
            },
        )]),
    };
    let mut engine = test_engine(2);
    engine.state.players[1].battlefield = vec![target];
    let mut bindings = BTreeMap::new();
    let mut decisions = BTreeMap::new();
    engine
        .execute_effects(
            &rule["effects"],
            &stack_object,
            &mut bindings,
            &mut decisions,
            &mut EmeritusDecisionProvider,
        )
        .expect("the shadow counter and linked characteristics resolve");
    let target = &engine.state.players[1].battlefield[0];
    assert_eq!(target.counters.get("shadow"), Some(&1));
    assert!(engine.permanent_has_keyword(target, "shadow"));
    assert!(engine.permanent_matches_effective_filter(
        target,
        &json!({ "kind": "subtypeContains", "value": "Wraith" })
    ));

    engine.state.players[1].battlefield[0]
        .counters
        .remove("shadow");
    let target = &engine.state.players[1].battlefield[0];
    assert!(!engine.permanent_has_keyword(target, "shadow"));
    assert!(!engine.permanent_matches_effective_filter(
        target,
        &json!({ "kind": "subtypeContains", "value": "Wraith" })
    ));
}

#[test]
fn combat_damage_received_groups_sources_and_limits_each_opponents_sacrifice() {
    let parsed = parse_oracle_card(OracleCardParseRequest {
        card_name: "Test Wraith".to_string(),
        type_line: "Legendary Creature - Wraith Noble".to_string(),
        mana_cost: Some("{3}{B}{B}".to_string()),
        oracle_text: Some(
            "Whenever one or more creatures deal combat damage to you, each opponent sacrifices a creature of their choice that dealt combat damage to you this turn. The Ring tempts you."
                .to_string(),
        ),
        layout: None,
        faces: Vec::new(),
    });
    let rule = parsed.abilities[0]
        .rule
        .clone()
        .expect("the grouped combat-damage trigger parses");
    assert!(rule_is_executable(&rule));

    let mut source_definition = test_definition("test-wraith", "Legendary Creature - Wraith Noble");
    source_definition.rules = vec![rule];
    let source = test_instance("test-wraith", source_definition, "player-0");
    let first = test_instance(
        "first-damage-source",
        test_definition("first-damage-source", "Creature - Orc"),
        "player-1",
    );
    let second = test_instance(
        "second-damage-source",
        test_definition("second-damage-source", "Creature - Goblin"),
        "player-1",
    );
    let innocent = test_instance(
        "innocent-creature",
        test_definition("innocent-creature", "Creature - Human"),
        "player-1",
    );
    let artifact = test_instance(
        "noncreature-source",
        test_definition("noncreature-source", "Artifact"),
        "player-1",
    );
    let mut engine = test_engine(2);
    engine.state.players[0].battlefield = vec![source];
    engine.state.players[1].battlefield = vec![first, second, innocent, artifact];

    engine.enqueue_combat_damage_to_player_triggers("first-damage-source", "player-0", 2);
    engine.enqueue_combat_damage_to_player_triggers("second-damage-source", "player-0", 2);
    engine.enqueue_combat_damage_to_player_triggers("noncreature-source", "player-0", 1);
    assert_eq!(engine.state.stack.len(), 1);
    assert_eq!(
        engine.state.stack[0].decisions["combatDamageSourceIds"],
        json!(["first-damage-source", "second-damage-source"])
    );

    engine
        .resolve_top_stack(&mut EmeritusDecisionProvider)
        .expect("the grouped trigger resolves");
    assert_eq!(engine.state.players[1].battlefield.len(), 3);
    assert!(
        engine.state.players[1]
            .battlefield
            .iter()
            .any(|card| card.instance_id == "innocent-creature")
    );
    assert!(
        engine.state.players[1]
            .battlefield
            .iter()
            .any(|card| card.instance_id == "noncreature-source")
    );
    assert!(engine.state.players[1].graveyard.iter().any(|card| {
        matches!(
            card.instance_id.as_str(),
            "first-damage-source" | "second-damage-source"
        )
    }));
    let emblem = engine
        .state
        .rule_modifiers
        .iter()
        .find(|modifier| value_kind(modifier) == Some("ringEmblem"))
        .expect("the Ring emblem persists");
    assert_eq!(emblem["level"], 1);
    assert_eq!(emblem["bearerId"], "test-wraith");
}

#[test]
fn ring_temptation_levels_drive_bearer_combat_rules() {
    let bearer = test_instance(
        "ring-bearer",
        test_definition("ring-bearer", "Creature - Halfling"),
        "player-0",
    );
    let mut stronger_blocker = test_instance(
        "stronger-blocker",
        test_definition("stronger-blocker", "Creature - Orc"),
        "player-1",
    );
    stronger_blocker.definition.power = Some("3".to_string());
    stronger_blocker.definition.toughness = Some("3".to_string());
    let mut engine = test_engine(2);
    engine.state.players[0].battlefield = vec![bearer.clone()];
    engine.state.players[1].battlefield = vec![stronger_blocker.clone()];
    let stack_object = StackObject {
        id: "stack:ring-temptation".to_string(),
        controller: "player-0".to_string(),
        card: bearer.clone(),
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: Some("triggeredAbility".to_string()),
        ability_rule: None,
        decisions: BTreeMap::new(),
        targets: BTreeMap::new(),
    };
    let temptation = json!({
        "kind": "ringTemptsPlayer",
        "player": { "kind": "controllerOf", "object": { "kind": "self" } },
    });
    for _ in 0..4 {
        engine
            .execute_effect(
                &temptation,
                None,
                &stack_object,
                &mut BTreeMap::new(),
                &mut BTreeMap::new(),
                &mut EmeritusDecisionProvider,
            )
            .expect("the Ring temptation resolves");
    }
    let bearer = &engine.state.players[0].battlefield[0];
    assert_eq!(engine.ring_bearer_level(bearer), 4);
    assert!(engine.permanent_matches_effective_filter(bearer, &json!({ "kind": "isLegendary" })));
    assert!(!engine.can_block(&stronger_blocker, bearer));

    let original_hand_size = engine.state.players[0].hand.len();
    let original_graveyard_size = engine.state.players[0].graveyard.len();
    engine.enqueue_declared_attacker_triggers(&["ring-bearer".to_string()]);
    assert_eq!(engine.state.stack.len(), 1);
    engine
        .resolve_top_stack(&mut EmeritusDecisionProvider)
        .expect("the Ring-bearer's attack loot resolves");
    assert_eq!(engine.state.players[0].hand.len(), original_hand_size);
    assert_eq!(
        engine.state.players[0].graveyard.len(),
        original_graveyard_size + 1
    );

    engine.enqueue_ring_bearer_blocked_trigger("ring-bearer", "stronger-blocker");
    assert_eq!(engine.state.stack.len(), 1);
    engine
        .resolve_top_stack(&mut EmeritusDecisionProvider)
        .expect("the blocked Ring-bearer trigger resolves");
    assert!(engine.permanent_position("stronger-blocker").is_some());
    engine
        .process_end_combat_exiles()
        .expect("end of combat sacrifices the blocking creature");
    assert!(engine.permanent_position("stronger-blocker").is_none());
    assert!(
        engine.state.players[1]
            .graveyard
            .iter()
            .any(|card| card.instance_id == "stronger-blocker")
    );

    engine.enqueue_combat_damage_to_player_triggers("ring-bearer", "player-1", 2);
    assert_eq!(engine.state.stack.len(), 1);
    engine
        .resolve_top_stack(&mut EmeritusDecisionProvider)
        .expect("the Ring-bearer's player-damage trigger resolves");
    assert_eq!(engine.state.players[1].life, 17);
}

#[test]
fn least_power_sacrifice_offers_only_tied_minimum_creatures() {
    let parsed = parse_oracle_card(OracleCardParseRequest {
        card_name: "Test Wraith".to_string(),
        type_line: "Legendary Creature - Wraith Noble".to_string(),
        mana_cost: Some("{4}{B}".to_string()),
        oracle_text: Some(
            "Whenever Test Wraith attacks, defending player sacrifices a creature with the least power among creatures they control."
                .to_string(),
        ),
        layout: None,
        faces: Vec::new(),
    });
    let rule = parsed.abilities[0]
        .rule
        .clone()
        .expect("the least-power attack trigger parses");
    assert!(rule_is_executable(&rule));

    let mut source_definition = test_definition("test-wraith", "Legendary Creature - Wraith Noble");
    source_definition.name = "Test Wraith".to_string();
    source_definition.rules = vec![rule];
    let source = test_instance("test-wraith", source_definition, "player-0");
    let mut large = test_instance(
        "large-creature",
        test_definition("large-creature", "Creature - Giant"),
        "player-1",
    );
    large.definition.power = Some("5".to_string());
    let mut small_a = test_instance(
        "small-a",
        test_definition("small-a", "Creature - Halfling"),
        "player-1",
    );
    small_a.definition.power = Some("1".to_string());
    let mut small_b = test_instance(
        "small-b",
        test_definition("small-b", "Creature - Goblin"),
        "player-1",
    );
    small_b.definition.power = Some("1".to_string());
    let artifact = test_instance(
        "noncreature-artifact",
        test_definition("noncreature-artifact", "Artifact"),
        "player-1",
    );

    let mut engine = test_engine(2);
    engine.state.players[0].battlefield = vec![source];
    engine.state.players[1].battlefield = vec![large, small_a, small_b, artifact];
    engine.state.combat.attackers = vec![DeclaredAttacker {
        attacker_id: "test-wraith".to_string(),
        defender: TargetRef::Player {
            player_id: "player-1".to_string(),
        },
        defending_player_id: "player-1".to_string(),
    }];
    engine.enqueue_declared_attacker_triggers(&["test-wraith".to_string()]);
    assert_eq!(engine.state.stack.len(), 1);
    engine
        .resolve_top_stack(&mut EmeritusDecisionProvider)
        .expect("the defending player chooses among the least-power creatures");

    assert!(engine.permanent_position("large-creature").is_some());
    assert!(engine.permanent_position("noncreature-artifact").is_some());
    assert_eq!(engine.state.players[1].battlefield.len(), 3);
    assert!(
        engine.state.players[1]
            .graveyard
            .iter()
            .any(|card| { matches!(card.instance_id.as_str(), "small-a" | "small-b") })
    );
}

#[test]
fn call_forth_repeated_cascade_creates_one_trigger_per_keyword_instance() {
    let parsed = parse_oracle_card(OracleCardParseRequest {
        card_name: "Test Tempest".to_string(),
        type_line: "Sorcery".to_string(),
        mana_cost: Some("{8}".to_string()),
        oracle_text: Some(
            "Cascade, cascade (When you cast this spell, exile cards from the top of your library until you exile a nonland card that costs less. You may cast it without paying its mana cost. Put the exiled cards on the bottom of your library in a random order. Then do it again.)\nTest Tempest deals damage to each creature your opponents control equal to the total mana value of other spells you've cast this turn."
                .to_string(),
        ),
        layout: None,
        faces: Vec::new(),
    });
    let rules = parsed
        .abilities
        .into_iter()
        .filter_map(|ability| ability.rule)
        .collect::<Vec<_>>();
    assert_eq!(rules.len(), 2);
    assert!(rules.iter().all(rule_is_executable));
    let mut spell = test_definition("test-tempest", "Sorcery");
    spell.name = "Test Tempest".to_string();
    spell.mana_cost = "{8}".to_string();
    spell.rules = rules;

    let mut engine = test_engine(2);
    engine.state.step = GameStep::PrecombatMain;
    engine.state.active_player = 0;
    engine.state.priority_player = Some(0);
    engine.state.players[0].hand = vec![test_instance("test-tempest", spell, "player-0")];
    engine.state.players[0].mana_pool = (0..8)
        .map(|_| FloatingMana {
            symbol: "C".to_string(),
            spend_restriction: None,
        })
        .collect();
    let action = engine
        .legal_priority_actions(0)
        .into_iter()
        .find(|action| action.card_instance_id.as_deref() == Some("test-tempest"))
        .expect("the double-cascade spell is castable");
    engine
        .apply_priority_action(&action, &mut EmeritusDecisionProvider)
        .expect("the double-cascade spell is cast");

    assert_eq!(
        engine
            .state
            .events
            .iter()
            .filter(|event| event.kind == "cascadeTriggered")
            .count(),
        2
    );
    assert_eq!(
        engine
            .state
            .stack
            .iter()
            .filter(|object| {
                object.ability_rule.as_ref().is_some_and(|rule| {
                    rule["effects"][0]["operation"] == "cascadeCastLowerManaValue"
                })
            })
            .count(),
        2
    );
}

#[test]
fn call_forth_spell_cast_event_mana_values_drive_opposing_permanent_damage() {
    let parsed = parse_oracle_card(OracleCardParseRequest {
        card_name: "Test Tempest".to_string(),
        type_line: "Sorcery".to_string(),
        mana_cost: Some("{8}".to_string()),
        oracle_text: Some(
            "Test Tempest deals damage to each creature your opponents control equal to the total mana value of other spells you've cast this turn."
                .to_string(),
        ),
        layout: None,
        faces: Vec::new(),
    });
    let rule = parsed.abilities[0]
        .rule
        .clone()
        .expect("the event-value damage spell parses");
    assert!(rule_is_executable(&rule));
    let mut source_definition = test_definition("test-tempest", "Sorcery");
    source_definition.name = "Test Tempest".to_string();
    source_definition.rules = vec![rule.clone()];
    let source = test_instance("test-tempest", source_definition, "player-0");
    let stack_object = StackObject {
        id: "stack:test-tempest".to_string(),
        controller: "player-0".to_string(),
        card: source,
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: None,
        ability_rule: Some(rule.clone()),
        decisions: BTreeMap::new(),
        targets: BTreeMap::new(),
    };
    let mut own_creature = test_instance(
        "own-creature",
        test_definition("own-creature", "Creature - Human"),
        "player-0",
    );
    own_creature.definition.toughness = Some("10".to_string());
    let mut opposing_creature = test_instance(
        "opposing-creature",
        test_definition("opposing-creature", "Creature - Orc"),
        "player-1",
    );
    opposing_creature.definition.toughness = Some("10".to_string());
    let mut engine = test_engine(2);
    engine.state.players[0].battlefield = vec![own_creature];
    engine.state.players[1].battlefield = vec![opposing_creature];
    for (instance_id, mana_value) in [("prior-one", 2), ("prior-two", 3), ("test-tempest", 8)] {
        engine.record_event(
            "spellCast",
            Some("player-0".to_string()),
            Some(instance_id.to_string()),
            json!({ "manaValue": mana_value }),
        );
    }
    engine.record_event(
        "spellCast",
        Some("player-1".to_string()),
        Some("opponent-spell".to_string()),
        json!({ "manaValue": 7 }),
    );
    engine
        .execute_effects(
            &rule["effects"],
            &stack_object,
            &mut BTreeMap::new(),
            &mut BTreeMap::new(),
            &mut EmeritusDecisionProvider,
        )
        .expect("the summed event-value damage resolves");

    assert_eq!(engine.state.players[0].battlefield[0].damage_marked, 0);
    assert_eq!(engine.state.players[1].battlefield[0].damage_marked, 5);
}

#[test]
fn aragorn_arwen_mass_counters_exclude_source_and_life_counts_allies() {
    let parsed = parse_oracle_card(OracleCardParseRequest {
        card_name: "Test Couple".to_string(),
        type_line: "Legendary Creature - Human Elf Noble".to_string(),
        mana_cost: Some("{4}{G}{W}".to_string()),
        oracle_text: Some(
            "Vigilance\nWhenever Test Couple enters or attacks, put a +1/+1 counter on each other creature you control. You gain 1 life for each other creature you control."
                .to_string(),
        ),
        layout: None,
        faces: Vec::new(),
    });
    let rule = parsed
        .abilities
        .into_iter()
        .filter_map(|ability| ability.rule)
        .find(|rule| value_kind(rule) == Some("triggeredAbility"))
        .expect("the enter-or-attack ability parses");
    assert!(rule_is_executable(&rule));

    let mut source_definition =
        test_definition("test-couple", "Legendary Creature - Human Elf Noble");
    source_definition.name = "Test Couple".to_string();
    source_definition.rules = vec![rule.clone()];
    let source = test_instance("test-couple", source_definition, "player-0");
    let ally_a = test_instance(
        "ally-a",
        test_definition("ally-a", "Creature - Human"),
        "player-0",
    );
    let ally_b = test_instance(
        "ally-b",
        test_definition("ally-b", "Artifact Creature - Construct"),
        "player-0",
    );
    let opponent = test_instance(
        "opponent-creature",
        test_definition("opponent-creature", "Creature - Orc"),
        "player-1",
    );
    let stack_object = StackObject {
        id: "stack:test-couple".to_string(),
        controller: "player-0".to_string(),
        card: source.clone(),
        cant_be_countered: false,
        exile_on_leave_stack: false,
        ability_kind: Some("triggeredAbility".to_string()),
        ability_rule: Some(rule.clone()),
        decisions: BTreeMap::new(),
        targets: BTreeMap::new(),
    };
    let mut engine = test_engine(2);
    engine.state.players[0].battlefield = vec![source, ally_a, ally_b];
    engine.state.players[1].battlefield = vec![opponent];
    engine
        .execute_effects(
            &rule["effects"],
            &stack_object,
            &mut BTreeMap::new(),
            &mut BTreeMap::new(),
            &mut EmeritusDecisionProvider,
        )
        .expect("the mass counters and life gain resolve");

    assert_eq!(
        engine.state.players[0].battlefield[0].counters.get("+1/+1"),
        None
    );
    for ally in &engine.state.players[0].battlefield[1..] {
        assert_eq!(ally.counters.get("+1/+1"), Some(&1));
    }
    assert_eq!(
        engine.state.players[1].battlefield[0].counters.get("+1/+1"),
        None
    );
    assert_eq!(engine.state.players[0].life, 22);
}

#[test]
fn flame_of_anor_modal_declarations_expand_from_one_to_two_with_wizard() {
    let parsed = parse_oracle_card(OracleCardParseRequest {
        card_name: "Test Flame".to_string(),
        type_line: "Instant".to_string(),
        mana_cost: Some("{1}{U}{R}".to_string()),
        oracle_text: Some(
            "Choose one. If you control a Wizard as you cast this spell, you may choose two instead.\n\u{2022} Target player draws two cards.\n\u{2022} Destroy target artifact.\n\u{2022} Test Flame deals 5 damage to target creature."
                .to_string(),
        ),
        layout: None,
        faces: Vec::new(),
    });
    let rule = parsed.abilities[0]
        .rule
        .clone()
        .expect("the conditional modal instant parses");
    assert!(rule_is_executable(&rule));
    let mut definition = test_definition("test-flame", "Instant");
    definition.name = "Test Flame".to_string();
    definition.rules = vec![rule];

    let artifact = test_instance(
        "target-artifact",
        test_definition("target-artifact", "Artifact"),
        "player-0",
    );
    let target_creature = test_instance(
        "target-creature",
        test_definition("target-creature", "Creature - Soldier"),
        "player-1",
    );
    let mut without_wizard = test_engine(2);
    without_wizard.state.players[0].battlefield = vec![artifact.clone()];
    without_wizard.state.players[1].battlefield = vec![target_creature.clone()];
    let declarations = without_wizard
        .declarations_for_card(&definition, "player-0")
        .expect("each singleton mode has legal targets");
    assert!(!declarations.is_empty());
    assert!(declarations.iter().all(|declaration| {
        declaration.decisions["chosenModes"]
            .as_array()
            .is_some_and(|modes| modes.len() == 1)
    }));

    let wizard = test_instance(
        "test-wizard",
        test_definition("test-wizard", "Creature - Human Wizard"),
        "player-0",
    );
    let mut with_wizard = test_engine(2);
    with_wizard.state.players[0].battlefield = vec![artifact, wizard];
    with_wizard.state.players[1].battlefield = vec![target_creature];
    let declarations = with_wizard
        .declarations_for_card(&definition, "player-0")
        .expect("the Wizard enables pairs of modes");
    assert!(declarations.iter().any(|declaration| {
        declaration.decisions["chosenModes"]
            .as_array()
            .is_some_and(|modes| modes.len() == 2)
    }));
    assert!(declarations.iter().all(|declaration| {
        declaration.decisions["chosenModes"]
            .as_array()
            .is_some_and(|modes| (1..=2).contains(&modes.len()))
    }));
}
